// Собрано tools/study_page.py из content/study/textbook.html — руками не править.
export const STUDY_HTML = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Учебник Full Stack Java</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,600;0,8..60,700;1,8..60,400&family=JetBrains+Mono:wght@400;500&display=swap\">\n<style>\n/* Учебник: слева оглавление по главам и темам (на телефоне — выезжает), справа колонка чтения ~68 знаков.\n   Цвета — из палитры pigeonpolly.com: фиолетовый и оранжевый на светлой «бумаге», тёмная тема — ночной фиолетовый сайта. */\n:root {\n  --paper: #fbfaff; --paper-2: #f2effa; --ink: #1f1832; --muted: #5d5675; --rule: #e1dcef;\n  --accent: #534ab7; --accent-soft: #ecebfb; --warm: #c4521f; --warm-soft: #fdf0e8;\n  --ok: #1d7a4e; --ok-soft: #e6f5ed; --code-bg: #f4f2fb; --mark: #fff1a8;\n  --thread: #0b6e99; --thread-soft: #e6f3fa;\n  --f-body: \"Source Serif 4\", Georgia, \"Times New Roman\", serif;\n  --f-ui: \"IBM Plex Sans\", \"Segoe UI\", system-ui, sans-serif;\n  --f-code: \"JetBrains Mono\", ui-monospace, Menlo, Consolas, monospace;\n  --side: 300px;\n  color-scheme: light;\n}\n@media (prefers-color-scheme: dark) { :root:not([data-theme=\"light\"]) {\n  --thread: #6cc4ec; --thread-soft: #10293a;\n  --paper: #1a1230; --paper-2: #231a3d; --ink: #efeafb; --muted: #b3aacb; --rule: #392e58;\n  --accent: #a59cf5; --accent-soft: #2c2452; --warm: #f0a987; --warm-soft: #3a2433;\n  --ok: #6fd3a0; --ok-soft: #1c3a32; --code-bg: #140e26; --mark: #5a4a12; color-scheme: dark; } }\n:root[data-theme=\"dark\"] {\n  --thread: #6cc4ec; --thread-soft: #10293a;\n  --paper: #1a1230; --paper-2: #231a3d; --ink: #efeafb; --muted: #b3aacb; --rule: #392e58;\n  --accent: #a59cf5; --accent-soft: #2c2452; --warm: #f0a987; --warm-soft: #3a2433;\n  --ok: #6fd3a0; --ok-soft: #1c3a32; --code-bg: #140e26; --mark: #5a4a12; color-scheme: dark; }\n\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; scroll-padding-top: 72px; }\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { transition: none !important; } }\nbody { margin: 0; background: var(--paper); color: var(--ink); font: 400 18px/1.65 var(--f-body);\n  padding-top: env(safe-area-inset-top, 0px); padding-bottom: env(safe-area-inset-bottom, 0px); }\nbody::before { content: \"\"; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 30; background: var(--paper); }\na { color: var(--accent); text-underline-offset: 3px; }\na:hover { color: var(--warm); }\n:focus-visible { outline: 2px solid var(--warm); outline-offset: 2px; border-radius: 3px; }\nh1, h2, h3, h4 { font-family: var(--f-body); text-wrap: balance; line-height: 1.2; }\ncode, pre { font-variant-ligatures: none; }\ncode { font-family: var(--f-code); font-size: .84em; background: var(--code-bg); padding: .1em .35em; border-radius: 4px; }\n\n/* верхняя полоса */\n.bar { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 20; background: var(--paper); border-bottom: 1px solid var(--rule);\n  display: flex; align-items: center; gap: 12px; padding-block: 10px;\n  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); font-family: var(--f-ui); }\n.bar .brand { font-weight: 700; font-size: 15px; color: var(--ink); text-decoration: none; white-space: nowrap; }\n.bar .brand span { color: var(--accent); }\n.bar .grow { flex: 1; min-width: 0; }\n.meter { height: 6px; background: var(--rule); border-radius: 99px; overflow: hidden; max-width: 260px; }\n.meter i { display: block; height: 100%; width: 0; background: var(--ok); transition: width .3s; }\n.bar .pct { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }\n.save { font-size: 12px; color: var(--muted); white-space: nowrap; }\n.save.err { color: var(--warm); }\n.btn { font: 500 14px var(--f-ui); border: 1px solid var(--rule); background: var(--paper-2); color: var(--ink); border-radius: 99px;\n  padding: 7px 14px; cursor: pointer; white-space: nowrap; }\n.btn:hover { border-color: var(--accent); }\n.btn.primary { background: var(--accent); color: var(--paper); border-color: var(--accent); }\n.menu-btn { display: none; }\n\n/* раскладка */\n.wrap { display: grid; grid-template-columns: var(--side) minmax(0, 1fr); }\n.side { position: sticky; top: calc(env(safe-area-inset-top, 0px) + 53px); height: calc(100vh - 53px - env(safe-area-inset-top, 0px)); overflow-y: auto;\n  border-right: 1px solid var(--rule); background: var(--paper-2); font-family: var(--f-ui); font-size: 14px; padding: 16px 12px 40px max(12px, env(safe-area-inset-left, 0px)); }\n.search { width: 100%; font: 400 14px var(--f-ui); padding: 8px 12px; border: 1px solid var(--rule); border-radius: 8px; background: var(--paper); color: var(--ink); }\n.hits { margin: 8px 0 0; padding: 0; list-style: none; }\n.hits li a { display: block; padding: 6px 8px; border-radius: 6px; text-decoration: none; color: var(--ink); }\n.hits li a:hover { background: var(--accent-soft); }\n.hits small { display: block; color: var(--muted); }\n.toc { list-style: none; margin: 14px 0 0; padding: 0; }\n.toc .part { margin: 18px 6px 6px; font-size: 11px; letter-spacing: .09em; text-transform: uppercase; color: var(--muted); font-weight: 600; }\n.toc > li > a { display: flex; gap: 8px; align-items: baseline; padding: 7px 8px; border-radius: 6px; text-decoration: none; color: var(--ink); font-weight: 500; }\n.toc > li > a .n { color: var(--muted); font-variant-numeric: tabular-nums; min-width: 1.6em; }\n.toc > li > a .t { flex: 1; min-width: 0; }\n.toc > li > a .c { font-size: 12px; color: var(--muted); font-variant-numeric: tabular-nums; }\n.toc > li > a .c.full { color: var(--ok); font-weight: 600; }\n.toc > li > a:hover { background: var(--accent-soft); }\n.toc > li.on > a { background: var(--accent-soft); color: var(--accent); }\n.toc ul { list-style: none; margin: 0 0 6px 34px; padding: 0; display: none; }\n.toc > li.on ul, .toc > li.open ul { display: block; }\n.toc ul a { display: block; padding: 3px 8px; color: var(--muted); text-decoration: none; border-left: 2px solid var(--rule); }\n.toc ul a:hover { color: var(--ink); }\n.toc ul a.on { color: var(--accent); border-left-color: var(--accent); }\n\n.main { min-width: 0; padding-block: 32px 80px; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n.col { max-width: 46rem; margin: 0 auto; }\n\n/* обложка */\n.cover { padding-block: 24px 8px; border-bottom: 3px double var(--rule); margin-bottom: 40px; }\n.cover .kicker { font: 600 12px var(--f-ui); letter-spacing: .12em; text-transform: uppercase; color: var(--warm); }\n.cover h1 { font-size: clamp(34px, 6vw, 54px); margin: 8px 0 12px; font-weight: 700; letter-spacing: -.01em; }\n.cover h1 em { font-style: italic; font-weight: 400; color: var(--accent); }\n.cover .lead { font-size: 20px; color: var(--muted); margin: 0 0 20px; }\n.cover .facts { display: flex; flex-wrap: wrap; gap: 8px 22px; font: 400 14px var(--f-ui); color: var(--muted); margin-bottom: 20px; }\n.cover .facts b { color: var(--ink); font-weight: 600; }\n.cover .go { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 24px; }\n\n/* части и главы */\n.part-h { font: 600 13px var(--f-ui); letter-spacing: .12em; text-transform: uppercase; color: var(--warm); margin: 72px 0 0; padding-top: 18px; border-top: 1px solid var(--rule); }\n.part-h + .ch { margin-top: 16px; }\n.ch { margin-top: 64px; }\n.ch-head { margin-bottom: 18px; }\n.ch-num { font: 600 13px var(--f-ui); letter-spacing: .1em; text-transform: uppercase; color: var(--accent); }\n.ch h2 { font-size: clamp(28px, 4.4vw, 38px); margin: 4px 0 8px; }\n.ch-meta { font: 400 14px var(--f-ui); color: var(--muted); margin: 0; display: flex; flex-wrap: wrap; gap: 4px 16px; }\n.ch h3 { font-size: 23px; margin: 40px 0 10px; }\n.ch h3 .sn { font: 500 14px var(--f-ui); color: var(--muted); margin-right: 8px; font-variant-numeric: tabular-nums; }\n.ch p, .ch li { max-width: 68ch; }\n.ch ul, .ch ol { padding-left: 1.3em; }\n.ch li { margin: 3px 0; }\n\n.goals { background: var(--accent-soft); border-radius: 10px; padding: 14px 20px; margin: 18px 0; }\n.goals h4, .box h4 { font: 600 13px var(--f-ui); letter-spacing: .08em; text-transform: uppercase; margin: 0 0 6px; }\n.goals h4 { color: var(--accent); }\n.goals ul { margin: 0; }\n\ndl.terms { display: grid; grid-template-columns: minmax(0, 11rem) minmax(0, 1fr); gap: 8px 18px; margin: 10px 0; }\ndl.terms dt { font: 600 15px var(--f-ui); }\ndl.terms dd { margin: 0; color: var(--muted); font-size: 16px; }\n\nul.res { list-style: none; padding: 0; margin: 10px 0; display: grid; gap: 10px; }\nul.res li { display: grid; grid-template-columns: 86px minmax(0, 1fr); gap: 2px 12px; align-items: baseline; }\nul.res .tag { grid-row: span 2; font: 600 11px var(--f-ui); letter-spacing: .06em; text-transform: uppercase; text-align: center; padding: 3px 4px; border-radius: 4px;\n  border: 1px solid var(--rule); color: var(--muted); }\nul.res .tag.book { color: var(--warm); border-color: currentColor; }\nul.res .tag.course { color: var(--accent); border-color: currentColor; }\nul.res .tag.video { color: var(--ok); border-color: currentColor; }\nul.res a { font-weight: 600; }\nul.res .note { font-size: 15px; color: var(--muted); }\nul.res .price { font: 500 12px var(--f-ui); color: var(--muted); margin-left: 6px; }\n\nfigure.code { margin: 20px 0; border: 1px solid var(--rule); border-radius: 10px; overflow: hidden; background: var(--code-bg); }\nfigure.code figcaption { font: 500 13px var(--f-ui); color: var(--muted); padding: 8px 14px; border-bottom: 1px solid var(--rule); }\nfigure.code pre { margin: 0; padding: 14px; overflow-x: auto; font: 400 13.5px/1.55 var(--f-code); }\nfigure.code code { background: none; padding: 0; font-size: inherit; }\n\n.box { border: 1px solid var(--rule); border-radius: 10px; padding: 14px 18px; margin: 20px 0; }\n.box.ex { background: var(--warm-soft); border-color: transparent; }\n.box.ex h4 { color: var(--warm); }\n.box.quiz h4 { color: var(--accent); }\n.box.skills { background: var(--ok-soft); border-color: transparent; }\n.box.skills h4 { color: var(--ok); }\n.box.fact { background: var(--paper-2); border-style: dashed; }\n.box.fact h4 { color: var(--warm); }\n.box.fact p { margin: 0; font-size: 16px; }\n.box.task { border-color: var(--accent); }\n.box.task h4 { color: var(--accent); }\n.box.task > p { margin: 4px 0 8px; }\ndetails.sol { border-top: 1px solid var(--rule); }\ndetails.sol figure.code { margin: 10px 0; }\n.quiz[data-quiz] { border: 1px solid var(--accent); border-radius: 10px; padding: 16px 18px; margin: 16px 0 24px; font-family: var(--f-ui); }\n.quiz[data-quiz] .qz-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 6px 16px; margin-bottom: 8px; }\n.quiz[data-quiz] .qz-head b { font-size: 15px; }\n.quiz[data-quiz] .qz-best { font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }\n.quiz[data-quiz] ol { padding-left: 1.4em; margin: 0; }\n.quiz[data-quiz] ol > li { margin: 0 0 18px; max-width: none; }\n.quiz[data-quiz] .qz-q { font: 400 17px/1.5 var(--f-body); margin: 0 0 6px; }\n.quiz[data-quiz] .qz-opt { display: flex; gap: 10px; align-items: flex-start; padding: 6px 10px; margin: 4px 0; border: 1px solid var(--rule); border-radius: 8px; cursor: pointer; font-size: 15px; }\n.quiz[data-quiz] .qz-opt input { margin-top: .25em; accent-color: var(--accent); flex: none; }\n.quiz[data-quiz] .qz-opt:hover { border-color: var(--accent); }\n.quiz[data-quiz].done .qz-opt { cursor: default; }\n.quiz[data-quiz] .qz-opt.right { border-color: var(--ok); background: var(--ok-soft); }\n.quiz[data-quiz] .qz-opt.wrong { border-color: var(--warm); background: var(--warm-soft); }\n.quiz[data-quiz] .qz-why { font-size: 14.5px; color: var(--muted); margin: 6px 0 0; padding-left: 10px; border-left: 2px solid var(--rule); }\n.quiz[data-quiz] .qz-why b.ok { color: var(--ok); } .quiz .qz-why b.no { color: var(--warm); }\n.quiz[data-quiz] .qz-res { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; padding: 12px 14px; border-radius: 8px; background: var(--accent-soft); margin-bottom: 14px; }\n.quiz[data-quiz] .qz-pct { font: 700 34px/1 var(--f-body); color: var(--accent); font-variant-numeric: tabular-nums; }\n.quiz[data-quiz] .qz-pct.good { color: var(--ok); } .quiz .qz-pct.low { color: var(--warm); }\n.quiz[data-quiz] .qz-bar { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }\n.quiz[data-quiz] .qz-note { font-size: 13px; color: var(--muted); }\n.thread { background: var(--thread-soft); border: 2px solid var(--thread); border-radius: 12px; padding: 4px 20px 16px; margin: 32px 0; }\n.thread > h3 { color: var(--thread); margin-top: 16px; }\n.thread .th-tag { display: inline-block; font: 600 11px var(--f-ui); letter-spacing: .1em; text-transform: uppercase; color: var(--paper); background: var(--thread); border-radius: 4px; padding: 3px 8px; margin-top: 14px; }\n.thread h4 { font: 600 13px var(--f-ui); letter-spacing: .08em; text-transform: uppercase; color: var(--thread); margin: 18px 0 6px; }\n.thread ol > li { margin: 6px 0; }\n.thread .tech { display: flex; flex-wrap: wrap; gap: 6px; padding: 0; list-style: none; margin: 6px 0; }\n.thread .tech li { font: 500 13px var(--f-ui); border: 1px solid var(--thread); color: var(--thread); border-radius: 99px; padding: 2px 10px; margin: 0; }\n.thread .tech li a { color: inherit; text-decoration: none; }\n.thread .join { border-left: 3px solid var(--thread); padding: 4px 0 4px 14px; margin: 12px 0; }\n.thread figure.code { background: var(--paper); }\n.thread ul.todo input { accent-color: var(--thread); }\n.toc ul a[data-sub$=\"-thread\"], .toc ul a[data-sub=\"intro-thread\"] { color: var(--thread); font-weight: 600; }\n.box.note { border-left: 3px solid var(--accent); border-radius: 0 10px 10px 0; font-size: 16px; }\n.box.note p { margin: 0; }\n\nul.todo { list-style: none; padding: 0; margin: 4px 0 0; }\nul.todo li { margin: 0; max-width: none; }\nul.todo label { display: flex; gap: 10px; align-items: flex-start; padding: 5px 0; cursor: pointer; }\nul.todo input { flex: none; width: 18px; height: 18px; margin-top: .3em; accent-color: var(--ok); cursor: pointer; }\nul.todo input:checked + span { color: var(--muted); text-decoration: line-through; text-decoration-color: var(--rule); }\n\ndetails { border-top: 1px solid var(--rule); padding: 8px 0; }\ndetails:first-of-type { border-top: 0; }\nsummary { cursor: pointer; font-weight: 600; }\nsummary::marker { color: var(--accent); }\ndetails p { margin: 8px 0 4px; color: var(--muted); font-size: 16px; }\n\n.tbl { overflow-x: auto; margin: 16px 0; }\ntable { border-collapse: collapse; width: 100%; font: 400 15px/1.45 var(--f-ui); }\nth, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--rule); vertical-align: top; }\nth { font-weight: 600; color: var(--muted); font-size: 13px; letter-spacing: .04em; text-transform: uppercase; }\ntd.num { font-variant-numeric: tabular-nums; white-space: nowrap; }\n\npre.tree { font: 400 13.5px/1.5 var(--f-code); background: var(--code-bg); border: 1px solid var(--rule); border-radius: 10px; padding: 14px; overflow-x: auto; }\n\n.pager { display: flex; justify-content: space-between; gap: 12px; margin-top: 40px; padding-top: 16px; border-top: 1px solid var(--rule); font-family: var(--f-ui); }\n.pager a { text-decoration: none; display: flex; flex-direction: column; max-width: 48%; }\n.pager a small { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: .08em; }\n.pager a.next { margin-left: auto; text-align: right; }\nmark { background: var(--mark); color: inherit; }\n.flash { animation: flash 1.6s ease-out; }\n@keyframes flash { from { background: var(--mark); } to { background: transparent; } }\n\n.top { position: fixed; right: max(16px, env(safe-area-inset-right, 0px)); bottom: calc(16px + env(safe-area-inset-bottom, 0px)); z-index: 15; }\n.scrim { display: none; }\n\n@media (max-width: 960px) {\n  .wrap { grid-template-columns: minmax(0, 1fr); }\n  .menu-btn { display: inline-block; }\n  .side { position: fixed; top: 0; left: 0; bottom: 0; height: auto; width: min(86vw, 340px); z-index: 40; transform: translateX(-102%); transition: transform .25s;\n    padding-top: calc(16px + env(safe-area-inset-top, 0px)); padding-bottom: calc(40px + env(safe-area-inset-bottom, 0px)); box-shadow: 0 0 40px rgb(0 0 0 / .2); }\n  body.nav .side { transform: none; }\n  body.nav .scrim { display: block; position: fixed; inset: 0; z-index: 35; background: rgb(0 0 0 / .35); }\n  .bar .meter, .save { display: none; }\n  body { font-size: 17px; }\n}\n@media (max-width: 520px) {\n  dl.terms { grid-template-columns: minmax(0, 1fr); gap: 2px; }\n  dl.terms dd { margin-bottom: 8px; }\n  ul.res li { grid-template-columns: minmax(0, 1fr); }\n  ul.res .tag { grid-row: auto; justify-self: start; }\n  .bar .brand { display: none; }\n  #cont-top { display: none; }\n}\n</style>\n</head>\n<body>\n\n<header class=\"bar\">\n  <button class=\"btn menu-btn\" id=\"menu\" aria-controls=\"side\" aria-expanded=\"false\">☰ Оглавление</button>\n  <a class=\"brand\" href=\"#top\">Full Stack <span>Java · Angular</span></a>\n  <div class=\"grow\"><div class=\"meter\" aria-hidden=\"true\"><i id=\"meter\"></i></div></div>\n  <span class=\"save\" id=\"save\"></span>\n  <span class=\"pct\" id=\"pct\">0 %</span>\n  <button class=\"btn primary\" id=\"cont-top\">Продолжить</button>\n</header>\n\n<div class=\"wrap\">\n<nav class=\"side\" id=\"side\" aria-label=\"Оглавление\">\n  <input class=\"search\" id=\"q\" type=\"search\" placeholder=\"Поиск по учебнику…\" autocomplete=\"off\">\n  <ul class=\"hits\" id=\"hits\"></ul>\n  <ul class=\"toc\" id=\"toc\"></ul>\n</nav>\n<div class=\"scrim\" id=\"scrim\"></div>\n\n<main class=\"main\" id=\"top\">\n<div class=\"col\">\n\n<section class=\"cover\" id=\"intro\" data-ch=\"0\" data-title=\"Предисловие\">\n  <div class=\"kicker\">Учебник для самостоятельного изучения</div>\n  <h1>Full Stack разработчик: <em>Java и Angular</em></h1>\n  <p class=\"lead\">Курс построен под вакансию Full Stack Developer (Java/Angular) в Swisscom DevOps Center Latvia, Рига. Начальный уровень: три курса Programming Engineer.</p>\n  <div class=\"facts\">\n    <span><b>12</b> глав</span><span><b>~10</b> месяцев</span><span><b>15–20</b> часов в неделю</span><span><b>1</b> сквозной проект</span><span><b>5 + 2</b> проектов для портфолио</span>\n  </div>\n  <div class=\"go\">\n    <button class=\"btn primary\" id=\"cont\">Продолжить с места</button>\n    <a class=\"btn\" href=\"#ch1\">Начать с главы 1</a>\n    <a class=\"btn\" href=\"#intro-thread\">Сквозной проект</a>\n    <a class=\"btn\" href=\"#ch10\">Финальные проекты</a>\n  </div>\n\n  <h3 id=\"intro-how\">Как пользоваться учебником</h3>\n  <p>Все материалы бесплатны и находятся в открытом доступе. Каждая глава устроена одинаково: <b>цели</b>, <b>ключевые понятия</b> с объяснениями, <b>теория</b> (книги, курсы, видео, документация), <b>листинг</b> с примером кода, <b>интересный факт</b>, <b>практика</b>, <b>задачи с решениями</b>, <b>упражнения</b>, <b>вопросы «Проверь себя»</b>, <b>тест</b> с оценкой в % и разбором ответов и <b>чек-лист навыков</b>. В начале главы перечислено, что вы будете уметь после неё. Галочки сохраняются на сайте, их видно с любого устройства, где выполнен вход.</p>\n  <p>Оглавление слева показывает, сколько пунктов главы уже отмечено. Кнопка «Продолжить» ведёт к первому неотмеченному пункту. Поиск находит любую тему, книгу или термин.</p>\n\n  <h3 id=\"intro-rules\">Принципы самообучения</h3>\n  <ul>\n    <li><b>30 / 70.</b> 30 % времени на теорию, 70 % на код. Каждая тема заканчивается коммитом в проект.</li>\n    <li><b>Учить по необходимости.</b> Книгу главы открывать в начале главы, не раньше.</li>\n    <li><b>Активное припоминание.</b> В конце недели 10 минут: своими словами записать в <code>LEARNING.md</code>, что понято. Ответить на «Проверь себя», не подглядывая.</li>\n    <li><b>Интервальное повторение.</b> Вопросы прошлых глав повторять через 1, 3 и 7 дней (удобно в Anki).</li>\n    <li><b>Метод Фейнмана.</b> Если тему не получается объяснить простыми словами, её стоит перечитать.</li>\n    <li><b>Публичность.</b> Все проекты на GitHub, с README, скриншотами и зелёным CI.</li>\n  </ul>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Карта</span><a href=\"https://roadmap.sh/java\" target=\"_blank\" rel=\"noopener\">roadmap.sh: Java</a><span class=\"note\">Также <a href=\"https://roadmap.sh/spring-boot\" target=\"_blank\" rel=\"noopener\">Spring Boot</a> и <a href=\"https://roadmap.sh/angular\" target=\"_blank\" rel=\"noopener\">Angular</a>: карты тем, чтобы видеть пробелы.</span></li>\n  </ul>\n\n  <h3 id=\"intro-plan\">План по месяцам</h3>\n  <div class=\"tbl\"><table>\n    <thead><tr><th>Месяц</th><th>Главы</th><th>Проект</th></tr></thead>\n    <tbody>\n      <tr><td class=\"num\">1</td><td><a href=\"#ch1\">1. Java</a>, <a href=\"#ch2\">2. Базы данных</a></td><td>logscope</td></tr>\n      <tr><td class=\"num\">2</td><td><a href=\"#ch3\">3. Spring Boot и REST</a></td><td>taskhub-api</td></tr>\n      <tr><td class=\"num\">3–4</td><td><a href=\"#ch4\">4. TypeScript и Angular</a>, <a href=\"#ch4b\">4Б. React</a></td><td>taskhub-web, FinTrack на React</td></tr>\n      <tr><td class=\"num\">5</td><td><a href=\"#ch5\">5. Безопасность и IAM</a></td><td>taskhub + Keycloak</td></tr>\n      <tr><td class=\"num\">6</td><td><a href=\"#ch6\">6. Docker, CI/CD, Kubernetes, AWS</a></td><td>taskhub в Kubernetes</td></tr>\n      <tr><td class=\"num\">7–8</td><td><a href=\"#ch7\">7. Микросервисы</a>, <a href=\"#ch10\">10. APIForge</a></td><td>APIForge</td></tr>\n      <tr><td class=\"num\">9–10</td><td><a href=\"#ch11\">11. SlotWise</a></td><td>SlotWise: от идеи до запуска</td></tr>\n    </tbody>\n  </table></div>\n  <div class=\"box note\"><p>Откликаться на вакансию можно уже после 5–6 месяца: проекты 2–5 на GitHub — достаточное портфолио для позиции junior/mid. Последние главы можно доучивать параллельно с собеседованиями.</p></div>\n\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект</span>\n  <h3 id=\"intro-thread\">FinTrack — учёт личных финансов, собранный из всех глав</h3>\n  <p>Это главный учебный проект курса. Он не связан с вакансией: он учит думать как full stack разработчик. В каждой главе 1–8 есть блок этого цвета — очередной шаг. Каждый шаг использует новые знания главы и подключается к тому, что уже построено. В конце получается полноценная система: из консольной программы она вырастает в микросервисы в Kubernetes. Всё — на бесплатных инструментах.</p>\n  <p>Чем полезен сам FinTrack: импортирует выписки из интернет-банка, раскладывает траты по категориям, показывает графики, следит за бюджетом семьи и предупреждает о превышении.</p>\n  <h4>Как растёт система</h4>\n  <div class=\"tbl\"><table><thead><tr><th>Шаг</th><th>Глава</th><th>Что добавляется</th><th>Тег</th></tr></thead><tbody>\n    <tr><td class=\"num\"><a href=\"#ch1-thread\">1</a></td><td>Java</td><td>Модуль <code>core</code>: разбор CSV, категории, отчёт</td><td>v0.1</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch2-thread\">2</a></td><td>Базы данных</td><td>PostgreSQL, миграции, импорт без дублей, SQL-отчёты</td><td>v0.2</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch3-thread\">3</a></td><td>Spring Boot</td><td>Модуль <code>api</code> поверх <code>core</code>, OpenAPI</td><td>v0.3</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch4-thread\">4</a></td><td>Angular</td><td>Модуль <code>web</code>: таблица, импорт, дашборд</td><td>v0.4</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch4b-thread\">4Б</a></td><td>React</td><td>Второй фронтенд <code>web-react</code> на том же API (по желанию)</td><td>v0.4.1</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch5-thread\">5</a></td><td>Безопасность</td><td>Keycloak, свои данные у каждого, семейный бюджет</td><td>v0.5</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch6-thread\">6</a></td><td>DevOps</td><td>Docker, CI/CD, Kubernetes, мониторинг</td><td>v0.6</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch7-thread\">7</a></td><td>Микросервисы</td><td>Kafka, import-, budget-service, уведомления</td><td>v0.7</td></tr>\n    <tr><td class=\"num\"><a href=\"#ch8-thread\">8</a></td><td>Качество</td><td>Архитектурные тесты, документация, выпуск</td><td>v1.0</td></tr>\n  </tbody></table></div>\n  <h4>Итоговая структура репозитория</h4>\n<pre class=\"tree\">fintrack/                         один репозиторий (монорепо) на всё обучение\n ├─ core/              шаг 1 · чистая Java: модель, CSV, категории — без Spring\n ├─ api/               шаг 3 · Spring Boot, зависит от core; миграции Flyway (шаг 2)\n ├─ web/               шаг 4 · Angular; nginx.conf (шаг 6)\n ├─ web-react/         шаг 4Б · тот же интерфейс на React\n ├─ import-service/    шаг 7 · тоже зависит от core\n ├─ budget-service/    шаг 7\n ├─ notifier/          шаг 7\n ├─ gateway/           шаг 7\n ├─ deploy/            шаги 5–7 · docker-compose.yml, realm.json, helm/\n ├─ docs/              ER, C4, ADR, отчёты SQL\n ├─ settings.gradle.kts           include(\"core\", \"api\", \"import-service\", …)\n └─ .github/workflows/            шаг 6 · CI/CD</pre>\n  <h4>Правила, которые склеивают шаги</h4>\n  <ol>\n    <li><b>Один репозиторий, Gradle-модули.</b> Java-части подключают друг друга через <code>implementation(project(\":core\"))</code>, а не копированием кода.</li>\n    <li><b>Чистое ядро.</b> Бизнес-логика живёт в <code>core</code> без фреймворков, поэтому её переиспользуют API и сервис импорта.</li>\n    <li><b>Контракт между частями.</b> Frontend и backend связаны файлом <code>api/openapi.json</code> и сгенерированным клиентом; сервисы — описанными событиями Kafka.</li>\n    <li><b>Одинаковые адреса везде.</b> <code>/api</code> проксируется в разработке (proxy.conf.json), в Docker и Kubernetes (nginx) — код не меняется между окружениями.</li>\n    <li><b>Каждый шаг — ветка, pull request и тег.</b> Ветка <code>step-N</code> → PR с зелёным CI → merge → тег <code>v0.N</code>. История репозитория сама показывает рост проекта.</li>\n  </ol>\n  </div>\n\n  <h3 id=\"intro-legend\">Обозначения</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag book\">Книга</span><span>Книга на английском в открытом доступе: читается бесплатно онлайн или в PDF.</span></li>\n    <li><span class=\"tag course\">Курс</span><span>Бесплатный онлайн-курс или тренажёр.</span></li>\n    <li><span class=\"tag video\">Видео</span><span>YouTube-канал или видеокурс.</span></li>\n    <li><span class=\"tag\">Доки</span><span>Официальная документация: самый достоверный источник.</span></li>\n    <li><span class=\"tag\">Сайт</span><span>Бесплатный сайт или статья признанного автора.</span></li>\n  </ul>\n</section>\n\n<!-- ============ ЧАСТЬ I ============ -->\n<div class=\"part-h\" data-part=\"Часть I · Backend\">Часть I · Backend</div>\n\n<section class=\"ch\" id=\"ch1\" data-ch=\"1\" data-title=\"Современная Java\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 1</div>\n    <h2>Современная Java и инструменты</h2>\n    <p class=\"ch-meta\"><span>3–4 недели</span><span>Проект: logscope</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Писать идиоматичный код на Java 17–21, а не «Java 8 со старыми привычками».</li>\n    <li>Уверенно работать с коллекциями, Stream API и многопоточностью.</li>\n    <li>Собирать проект Gradle/Maven, покрывать его тестами JUnit 5.</li>\n    <li>Работать в Git как в команде: ветки, pull request, rebase.</li>\n  </ul></div>\n\n  <h3 id=\"ch1-terms\"><span class=\"sn\">1.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>record</dt><dd>Неизменяемый класс-носитель данных: конструктор, equals, hashCode и toString генерируются сами.</dd>\n    <dt>sealed</dt><dd>Класс или интерфейс с закрытым списком наследников. Вместе с pattern matching даёт исчерпывающий <code>switch</code>.</dd>\n    <dt>Stream API</dt><dd>Декларативная обработка коллекций: filter, map, collect, groupingBy.</dd>\n    <dt>Optional</dt><dd>Явное «значение может отсутствовать». Задуман как тип возврата.</dd>\n    <dt>Virtual threads</dt><dd>Лёгкие потоки Java 21: тысячи одновременных блокирующих операций ввода-вывода без пулов.</dd>\n    <dt>Gradle / Maven</dt><dd>Сборка, зависимости, запуск тестов.</dd>\n  </dl>\n\n  <h3 id=\"ch1-theory\"><span class=\"sn\">1.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://dev.java/learn/\" target=\"_blank\" rel=\"noopener\">dev.java/learn</a><span class=\"note\">Официальный учебник Oracle по современной Java: records, sealed, pattern matching, virtual threads.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://greenteapress.com/wp/think-java-2e/\" target=\"_blank\" rel=\"noopener\">Think Java, 2nd ed. — Allen Downey, Chris Mayfield</a><span class=\"note\">Бесплатная книга (HTML и PDF, лицензия CC). Быстро повторить основы и закрыть пробелы.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://jenkov.com/tutorials/java-concurrency/index.html\" target=\"_blank\" rel=\"noopener\">Jenkov — Java Concurrency</a><span class=\"note\">Бесплатный подробный учебник по многопоточности: потоки, гонки, локи, ExecutorService, virtual threads.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://www.baeldung.com/\" target=\"_blank\" rel=\"noopener\">Baeldung</a><span class=\"note\">Справочник с примерами почти по любой теме Java и Spring.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://refactoring.guru/design-patterns\" target=\"_blank\" rel=\"noopener\">Refactoring.Guru — Design Patterns</a><span class=\"note\">Паттерны проектирования с примерами на Java.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://git-scm.com/book/en/v2\" target=\"_blank\" rel=\"noopener\">Pro Git</a><span class=\"note\">Бесплатная официальная книга по Git.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 1.1. Record, Stream API и groupingBy: средняя длительность запросов по адресу</figcaption>\n<pre><code>record Hit(String path, int status, long millis) {}\n\nMap&lt;String, Double&gt; avgByPath = hits.stream()\n    .filter(h -&gt; h.status() &lt; 500)\n    .collect(Collectors.groupingBy(Hit::path,\n             Collectors.averagingLong(Hit::millis)));\n\n// Java 21: виртуальный поток на каждый файл\ntry (var pool = Executors.newVirtualThreadPerTaskExecutor()) {\n    files.forEach(f -&gt; pool.submit(() -&gt; parse(f)));\n}</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Java создавали в Sun Microsystems под руководством Джеймса Гослинга. Сначала язык назывался Oak — в честь дуба за окном, но имя оказалось занято, и в 1995 году он вышел как Java. С 2018 года новая версия выходит каждые полгода, а версия с долгой поддержкой (LTS) — раз в два года: 17, 21, 25.</p></aside>\n\n  <h3 id=\"ch1-practice\"><span class=\"sn\">1.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://java-programming.mooc.fi/\" target=\"_blank\" rel=\"noopener\">Java Programming MOOC</a><span class=\"note\">Университет Хельсинки. Сотни задач с автопроверкой; пройти темы, где есть пробелы.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://exercism.org/tracks/java\" target=\"_blank\" rel=\"noopener\">Exercism — Java track</a><span class=\"note\">Задачи с бесплатным ревью от менторов.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://learngitbranching.js.org/\" target=\"_blank\" rel=\"noopener\">Learn Git Branching</a><span class=\"note\">Интерактивный тренажёр веток, merge и rebase.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://junit.org/junit5/docs/current/user-guide/\" target=\"_blank\" rel=\"noopener\">JUnit 5 User Guide</a><span class=\"note\">Параметризованные тесты, вложенные классы, расширения.</span></li>\n  </ul>\n\n  <h3 id=\"ch1-tasks\"><span class=\"sn\">1.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 1.1. Топ-3 слов</h4>\n    <p>Напишите метод <code>top3(String text)</code>, который возвращает три самых частых слова текста без учёта регистра. Только Stream API, без циклов.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java</figcaption><pre><code>static List&lt;String&gt; top3(String text) {\n    return Arrays.stream(text.toLowerCase().split(\"[^\\\\p{L}\\\\p{N}]+\"))\n        .filter(w -&gt; !w.isBlank())\n        .collect(Collectors.groupingBy(w -&gt; w, Collectors.counting()))\n        .entrySet().stream()\n        .sorted(Map.Entry.&lt;String, Long&gt;comparingByValue().reversed())\n        .limit(3)\n        .map(Map.Entry::getKey)\n        .toList();\n}</code></pre></figure>\n      <p>Регулярное выражение <code>[^\\p{L}\\p{N}]+</code> режет по всему, что не буква и не цифра, поэтому работает и для кириллицы (обычный <code>\\W</code> считает кириллицу «не словом»). <code>groupingBy</code> + <code>counting</code> строят частоты, затем сортировка по значению по убыванию.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c1-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 1.2. Площадь фигур</h4>\n    <p>Опишите фигуры круг и прямоугольник через sealed-интерфейс и records. Напишите <code>area(Shape s)</code> через <code>switch</code> с pattern matching без ветки <code>default</code>.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java 21</figcaption><pre><code>sealed interface Shape permits Circle, Rect {}\nrecord Circle(double r) implements Shape {}\nrecord Rect(double w, double h) implements Shape {}\n\nstatic double area(Shape s) {\n    return switch (s) {\n        case Circle c -&gt; Math.PI * c.r() * c.r();\n        case Rect(double w, double h) -&gt; w * h;   // record pattern, Java 21\n    };\n}</code></pre></figure>\n      <p>Компилятор знает все разрешённые реализации sealed-интерфейса, поэтому <code>switch</code> исчерпывающий и <code>default</code> не нужен. Если добавить новую фигуру, код перестанет компилироваться, пока её не обработают, — это и есть польза sealed.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c1-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c1-e1\"><span>Переписать 3 старых учебных класса на records и sealed-интерфейсы с <code>switch</code> по шаблону.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-e2\"><span>Решить 15 задач Exercism Java, к пяти из них получить ревью ментора.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-e3\"><span>Пройти Learn Git Branching: разделы Main и Remote целиком.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-e4\"><span>Сравнить время обработки 1000 файлов: обычный пул потоков и виртуальные потоки.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Чем record отличается от обычного класса?</summary><p>Поля final, а конструктор, equals, hashCode, toString и методы доступа генерируются автоматически. Record не может наследовать другой класс, но может реализовывать интерфейсы.</p></details>\n    <details><summary>Когда виртуальные потоки дают выигрыш, а когда нет?</summary><p>Выигрыш — при большом числе блокирующих операций ввода-вывода (HTTP, база, файлы). Для вычислительных задач они не быстрее обычных: число ядер не меняется.</p></details>\n    <details><summary>Почему Optional не стоит делать полем класса или параметром метода?</summary><p>Он задуман как тип возврата: «результата может не быть». В полях он усложняет сериализацию и добавляет лишний объект, в параметрах лучше перегрузка или null-проверка.</p></details>\n    <details><summary>Чем map отличается от flatMap в Stream?</summary><p>map превращает каждый элемент в один новый, flatMap — в поток элементов и «расплющивает» их в один общий поток.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 1 из 8</span>\n  <h3 id=\"ch1-thread\">FinTrack, шаг 1: ядро на чистой Java</h3>\n  <p>Консольная программа читает выписку банка в CSV, раскладывает операции по категориям по правилам и печатает отчёт за месяц. Это модуль <code>core</code> — бизнес-логика без фреймворков. Он доживёт до финала: его будут использовать и API, и сервис импорта.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://adoptium.net/\" target=\"_blank\" rel=\"noopener\">Java 21 (Temurin)</a></li><li><a href=\"https://docs.gradle.org/current/userguide/userguide.html\" target=\"_blank\" rel=\"noopener\">Gradle</a></li><li><a href=\"https://junit.org/junit5/\" target=\"_blank\" rel=\"noopener\">JUnit 5</a></li><li><a href=\"https://assertj.github.io/doc/\" target=\"_blank\" rel=\"noopener\">AssertJ</a></li><li><a href=\"https://www.jetbrains.com/idea/download/\" target=\"_blank\" rel=\"noopener\">IntelliJ IDEA Community</a></li><li><a href=\"https://git-scm.com/\" target=\"_blank\" rel=\"noopener\">Git</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Создайте репозиторий <code>fintrack</code> на GitHub и многомодульный Gradle-проект (<code>gradle init</code>) с первым модулем <code>core</code>.</li><li>Опишите модель на records: <code>Transaction(LocalDate date, BigDecimal amount, String currency, String description)</code>, <code>Category</code>, <code>Rule(String contains, String category)</code>.</li><li>Напишите <code>CsvParser</code>: выгрузите свою выписку из интернет-банка в CSV (или придумайте пример на 30 строк) и разберите её. Ошибочные строки собирайте в отчёт об ошибках, а не роняйте программу.</li><li>Напишите <code>Categorizer</code>: первое правило, чьё <code>contains</code> найдено в описании, задаёт категорию; иначе — «Прочее».</li><li>Напишите <code>MonthlyReport</code> на Stream API: сумма по категориям за месяц, отсортированная по убыванию трат.</li><li>Покройте парсер, категоризацию и отчёт тестами JUnit 5 + AssertJ, включая пустой файл и битые строки.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Это первый шаг, соединять пока нечего. Главное правило на всё обучение: <b>в <code>core</code> нет Spring, базы и HTTP</b>. Тогда на шаге 3 API просто подключит этот модуль зависимостью, а на шаге 7 его же переиспользует сервис импорта.</p></div>\n  <figure class=\"code\"><figcaption>settings.gradle.kts и деньги в BigDecimal</figcaption><pre><code>// settings.gradle.kts — сюда будут добавляться модули на следующих шагах\nrootProject.name = \"fintrack\"\ninclude(\"core\")\n\n// core/src/main/java/dev/fintrack/core/Transaction.java\npublic record Transaction(LocalDate date, BigDecimal amount, String currency, String description) {\n    public Transaction {\n        Objects.requireNonNull(date); Objects.requireNonNull(amount);\n        amount = amount.setScale(2, RoundingMode.HALF_EVEN);  // деньги — только BigDecimal\n    }\n}</code></pre></figure><aside class=\"box fact\"><h4>Почему не double</h4><p>В Java <code>0.1 + 0.2</code> в типе double даёт <code>0.30000000000000004</code>: двоичная дробь не может точно хранить десятичные копейки. Поэтому деньги считают в <code>BigDecimal</code> или в целых центах.</p></aside>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-1a\"><span>Программа печатает отчёт по настоящей или тестовой выписке: <code>./gradlew :core:run --args=\"statement.csv 2026-10\"</code>.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-1b\"><span>Тесты зелёные, в <code>core</code> нет зависимостей кроме JDK и тестовых библиотек.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-1c\"><span>README: что это, как запустить, пример вывода.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.1</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch1-test\"><span class=\"sn\">1.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"1\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c1-s1\"><span>Пишу records, sealed-интерфейсы и switch-выражения с pattern matching.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-s2\"><span>Решаю задачи со Stream API без циклов там, где так понятнее.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-s3\"><span>Знаю разницу между ExecutorService, CompletableFuture и virtual threads.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-s4\"><span>Настраиваю Gradle-проект с JUnit 5, AssertJ и Mockito с нуля.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-s5\"><span>Делаю ветку, pull request, rebase и разрешаю конфликт.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c1-s6\"><span>Проект 1 logscope готов (<a href=\"#p1\">задание</a>).</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch2\" data-ch=\"2\" data-title=\"Базы данных и SQL\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 2</div>\n    <h2>Базы данных, SQL и JPA</h2>\n    <p class=\"ch-meta\"><span>2 недели, можно параллельно с главой 3</span><span>Проект: taskhub-api</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Проектировать схему: нормализация, ключи, индексы.</li>\n    <li>Писать SQL с JOIN, агрегатами и оконными функциями.</li>\n    <li>Понимать транзакции и уровни изоляции.</li>\n    <li>Работать с JPA/Hibernate и не попадать в проблему N+1.</li>\n  </ul></div>\n\n  <h3 id=\"ch2-terms\"><span class=\"sn\">2.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>Нормализация</dt><dd>Разбиение данных по таблицам так, чтобы факт хранился в одном месте.</dd>\n    <dt>Индекс</dt><dd>Структура (обычно B-tree), ускоряющая поиск. Составной индекс (a, b) работает для запросов по a и по (a, b).</dd>\n    <dt>ACID</dt><dd>Атомарность, согласованность, изоляция, долговечность транзакции.</dd>\n    <dt>Миграция</dt><dd>Версионированное изменение схемы (Flyway: <code>V1__init.sql</code>, <code>V2__…</code>).</dd>\n    <dt>N+1</dt><dd>Один запрос за списком и ещё N — за связанными сущностями каждого элемента.</dd>\n  </dl>\n\n  <h3 id=\"ch2-theory\"><span class=\"sn\">2.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://www.postgresql.org/docs/current/tutorial.html\" target=\"_blank\" rel=\"noopener\">PostgreSQL Tutorial</a><span class=\"note\">Официальный учебник PostgreSQL: таблицы, запросы, транзакции, оконные функции.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://vladmihalcea.com/\" target=\"_blank\" rel=\"noopener\">Блог Vlad Mihalcea</a><span class=\"note\">Бесплатные статьи о Hibernate и производительности: лучший источник по теме.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://documentation.red-gate.com/flyway\" target=\"_blank\" rel=\"noopener\">Flyway Documentation</a><span class=\"note\">Миграции схемы.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-data/jpa/reference/\" target=\"_blank\" rel=\"noopener\">Spring Data JPA Reference</a><span class=\"note\">Репозитории, запросы по имени метода, @EntityGraph.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://use-the-index-luke.com/\" target=\"_blank\" rel=\"noopener\">Use The Index, Luke — Markus Winand</a><span class=\"note\">Бесплатная веб-книга об индексах и производительности SQL для разработчиков.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 2.1. Flyway-миграция V1__init.sql для taskhub</figcaption>\n<pre><code>CREATE TABLE project (\n  id    BIGSERIAL PRIMARY KEY,\n  name  TEXT NOT NULL UNIQUE\n);\nCREATE TABLE task (\n  id          BIGSERIAL PRIMARY KEY,\n  project_id  BIGINT NOT NULL REFERENCES project(id) ON DELETE CASCADE,\n  title       TEXT NOT NULL,\n  status      TEXT NOT NULL CHECK (status IN ('TODO', 'IN_PROGRESS', 'DONE')),\n  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX idx_task_project_status ON task (project_id, status);</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>SQL придумали в IBM в начале 1970-х Дональд Чемберлин и Рэймонд Бойс. Язык назывался SEQUEL, но название пришлось сменить из-за чужой торговой марки, поэтому многие до сих пор произносят SQL как «сиквел». PostgreSQL вырос из проекта POSTGRES Майкла Стоунбрейкера в Беркли; за работы над базами данных он получил премию Тьюринга в 2014 году.</p></aside>\n\n  <h3 id=\"ch2-practice\"><span class=\"sn\">2.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://sqlbolt.com/\" target=\"_blank\" rel=\"noopener\">SQLBolt</a><span class=\"note\">Интерактивные уроки SQL с задачами прямо в браузере.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://pgexercises.com/\" target=\"_blank\" rel=\"noopener\">PostgreSQL Exercises</a><span class=\"note\">Задачи на JOIN, агрегаты и рекурсивные запросы.</span></li>\n  </ul>\n\n  <h3 id=\"ch2-tasks\"><span class=\"sn\">2.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 2.1. Прогресс проектов</h4>\n    <p>Для каждого проекта выведите общее число задач, число задач DONE и процент выполненных. Проекты без задач тоже должны попасть в отчёт. Отсортируйте по проценту.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>PostgreSQL</figcaption><pre><code>SELECT p.name,\n       COUNT(t.id)                                AS total,\n       COUNT(*) FILTER (WHERE t.status = 'DONE')  AS done,\n       ROUND(100.0 * COUNT(*) FILTER (WHERE t.status = 'DONE')\n             / NULLIF(COUNT(t.id), 0), 1)          AS done_pct\nFROM project p\nLEFT JOIN task t ON t.project_id = p.id\nGROUP BY p.id, p.name\nORDER BY done_pct DESC NULLS LAST;</code></pre></figure>\n      <p><code>LEFT JOIN</code> оставляет проекты без задач. <code>COUNT(t.id)</code> не считает NULL, поэтому у пустого проекта total = 0. <code>NULLIF</code> защищает от деления на ноль, <code>FILTER</code> — компактная замена <code>SUM(CASE …)</code>.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c2-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 2.2. Убрать N+1</h4>\n    <p>Метод <code>projectRepository.findAll()</code>, а затем <code>project.getTasks()</code> в цикле даёт 1 + N запросов. Исправьте одним запросом.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Spring Data JPA</figcaption><pre><code>public interface ProjectRepository extends JpaRepository&lt;Project, Long&gt; {\n\n    @Query(\"select distinct p from Project p left join fetch p.tasks\")\n    List&lt;Project&gt; findAllWithTasks();\n\n    // или то же через EntityGraph:\n    @EntityGraph(attributePaths = \"tasks\")\n    List&lt;Project&gt; findAllBy();\n}</code></pre></figure>\n      <p><code>join fetch</code> загружает проекты и их задачи одним SQL-запросом. <code>distinct</code> убирает дубликаты проектов в результате. Для пагинации fetch join по коллекции не подходит — там используют batch fetching (<code>@BatchSize</code>).</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c2-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c2-e1\"><span>Пройти SQLBolt целиком и разделы Joins и Aggregation на pgexercises.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-e2\"><span>Нарисовать ER-диаграмму taskhub (проекты, задачи, пользователи, комментарии) и написать миграции.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-e3\"><span>Специально получить N+1 в JPA, увидеть его в логе SQL и исправить через JOIN FETCH или @EntityGraph.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-e4\"><span>Сравнить план запроса (<code>EXPLAIN ANALYZE</code>) с индексом и без.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Что такое N+1 и как его найти?</summary><p>Один запрос за списком плюс отдельный запрос за связанными данными каждого элемента. Видно в логе SQL (<code>spring.jpa.show-sql</code> или datasource-proxy). Лечится JOIN FETCH, @EntityGraph или batch fetching.</p></details>\n    <details><summary>Поможет ли индекс (project_id, status) запросу только по status?</summary><p>Обычно нет: B-tree индекс используется по левому префиксу. Для поиска только по status нужен свой индекс.</p></details>\n    <details><summary>От чего защищает уровень изоляции READ COMMITTED и от чего нет?</summary><p>Защищает от «грязного чтения» незафиксированных данных. Не защищает от неповторяющегося чтения и фантомов: повторный SELECT в той же транзакции может вернуть другой результат.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 2 из 8</span>\n  <h3 id=\"ch2-thread\">FinTrack, шаг 2: база данных</h3>\n  <p>Данные начинают храниться в PostgreSQL: счета, категории, правила, операции. Повторный импорт той же выписки не создаёт дублей. Отчёты переезжают в SQL.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://www.postgresql.org/\" target=\"_blank\" rel=\"noopener\">PostgreSQL 16</a></li><li><a href=\"https://docs.docker.com/get-started/\" target=\"_blank\" rel=\"noopener\">Docker</a></li><li><a href=\"https://dbeaver.io/\" target=\"_blank\" rel=\"noopener\">DBeaver Community</a></li><li><a href=\"https://documentation.red-gate.com/flyway\" target=\"_blank\" rel=\"noopener\">Flyway</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Запустите PostgreSQL в Docker: <code>docker run -d --name fintrack-db -e POSTGRES_PASSWORD=dev -p 5432:5432 postgres:16</code>. Подключитесь DBeaver.</li><li>Нарисуйте ER-диаграмму: <code>account</code>, <code>category</code>, <code>rule</code>, <code>txn</code>; сохраните картинку в <code>docs/</code>.</li><li>Напишите миграцию <code>V1__init.sql</code>. У операции храните <code>import_hash</code> — хэш даты, суммы и описания — с уникальным индексом по <code>(account_id, import_hash)</code>.</li><li>Напишите SQL-отчёты: траты по категориям за месяц; помесячная динамика за год; накопительный баланс оконной функцией <code>SUM(...) OVER (ORDER BY date)</code>.</li><li>Проверьте <code>EXPLAIN ANALYZE</code> отчёта за месяц на 100 000 сгенерированных операций (<code>generate_series</code>) и добавьте индекс <code>(account_id, date)</code>.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Records из <code>core</code> остаются моделью предметной области, а таблицы — способом хранения. Связывать их будет API на шаге 3: сущности JPA и records — разные классы, между ними — маппер. Миграции положите в <code>api/src/main/resources/db/migration</code> уже сейчас: Flyway в Spring Boot найдёт их там сам.</p></div>\n  <figure class=\"code\"><figcaption>Защита от повторного импорта</figcaption><pre><code>CREATE TABLE txn (\n  id           BIGSERIAL PRIMARY KEY,\n  account_id   BIGINT NOT NULL REFERENCES account(id),\n  date         DATE NOT NULL,\n  amount       NUMERIC(12, 2) NOT NULL,\n  currency     CHAR(3) NOT NULL,\n  description  TEXT NOT NULL,\n  category_id  BIGINT REFERENCES category(id),\n  import_hash  TEXT NOT NULL,\n  UNIQUE (account_id, import_hash)\n);\n-- импорт: INSERT ... ON CONFLICT (account_id, import_hash) DO NOTHING</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-2a\"><span>Повторный импорт той же выписки добавляет 0 строк.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-2b\"><span>Три SQL-отчёта сохранены в <code>docs/reports.sql</code> и дают правильные числа.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-2c\"><span>ER-диаграмма в репозитории.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.2</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch2-test\"><span class=\"sn\">2.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"2\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c2-s1\"><span>Проектирую схему в 3НФ и знаю, когда денормализовать.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-s2\"><span>Пишу JOIN, GROUP BY, оконные функции и читаю EXPLAIN.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-s3\"><span>Пишу миграции Flyway и не меняю уже применённые.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c2-s4\"><span>Настраиваю связи JPA и выбираю lazy или eager осознанно.</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch3\" data-ch=\"3\" data-title=\"Spring Boot и REST\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 3</div>\n    <h2>Spring Boot и REST API</h2>\n    <p class=\"ch-meta\"><span>5–6 недель</span><span>Проект: taskhub-api</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Понимать, что делает Spring «под капотом»: IoC, DI, автоконфигурация.</li>\n    <li>Проектировать и документировать REST API по правилам.</li>\n    <li>Обрабатывать ошибки и валидацию в едином формате.</li>\n    <li>Тестировать слои по отдельности и вместе, с настоящей базой в Testcontainers.</li>\n  </ul></div>\n\n  <h3 id=\"ch3-terms\"><span class=\"sn\">3.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>IoC / DI</dt><dd>Объекты (бины) создаёт и связывает контейнер Spring; класс получает зависимости через конструктор.</dd>\n    <dt>Автоконфигурация</dt><dd>Spring Boot сам настраивает бины по зависимостям в classpath и свойствам.</dd>\n    <dt>Профили</dt><dd>Наборы настроек для dev, test, prod (<code>application-prod.yml</code>).</dd>\n    <dt>ProblemDetail</dt><dd>Стандартный формат ошибок HTTP API (RFC 9457), встроен в Spring 6.</dd>\n    <dt>Идемпотентность</dt><dd>Повторный запрос даёт тот же результат: GET, PUT, DELETE — да, POST — нет.</dd>\n    <dt>OpenAPI</dt><dd>Машиночитаемое описание API, из него строится Swagger UI.</dd>\n    <dt>Testcontainers</dt><dd>Библиотека, поднимающая настоящие PostgreSQL, Kafka и другие сервисы в Docker на время тестов.</dd>\n  </dl>\n\n  <h3 id=\"ch3-theory\"><span class=\"sn\">3.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-framework/reference/core.html\" target=\"_blank\" rel=\"noopener\">Spring Framework — Core Technologies</a><span class=\"note\">Официальное объяснение IoC-контейнера, бинов, DI и AOP. Читать главы 1–4.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://spring.io/guides\" target=\"_blank\" rel=\"noopener\">Spring Guides</a><span class=\"note\">Короткие официальные руководства: REST, JPA, тестирование.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-boot/index.html\" target=\"_blank\" rel=\"noopener\">Spring Boot Reference</a><span class=\"note\">Официальная документация.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://spring.academy/courses\" target=\"_blank\" rel=\"noopener\">Spring Academy</a><span class=\"note\">Официальные курсы команды Spring, бесплатны после регистрации. Начать со Spring Boot Essentials.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@DanVega\" target=\"_blank\" rel=\"noopener\">Dan Vega</a><span class=\"note\">Spring Developer Advocate: короткие и точные разборы.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@amigoscode\" target=\"_blank\" rel=\"noopener\">Amigoscode</a><span class=\"note\">Полные курсы Spring Boot для начинающих.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@SpringSourceDev\" target=\"_blank\" rel=\"noopener\">SpringDeveloper</a><span class=\"note\">Официальный канал: доклады Spring I/O и SpringOne.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://learn.openapis.org/\" target=\"_blank\" rel=\"noopener\">OpenAPI — Learn</a><span class=\"note\">Как описывать API. Для Spring — <a href=\"https://springdoc.org/\" target=\"_blank\" rel=\"noopener\">springdoc-openapi</a>.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 3.1. Контроллер: внедрение через конструктор, валидация, 201 Created с Location</figcaption>\n<pre><code>@RestController\n@RequestMapping(\"/api/v1/tasks\")\nclass TaskController {\n    private final TaskService service;\n\n    TaskController(TaskService service) { this.service = service; }\n\n    @PostMapping\n    ResponseEntity&lt;TaskDto&gt; create(@Valid @RequestBody CreateTask cmd) {\n        TaskDto saved = service.create(cmd);\n        return ResponseEntity\n            .created(URI.create(\"/api/v1/tasks/\" + saved.id()))\n            .body(saved);\n    }\n\n    @GetMapping\n    Page&lt;TaskDto&gt; list(@RequestParam(required = false) Status status, Pageable page) {\n        return service.find(status, page);\n    }\n}</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Spring начался с примеров кода к книге Рода Джонсона «Expert One-on-One J2EE Design and Development» (2002). Это был ответ на тяжеловесную платформу EJB: Джонсон показал, что корпоративные приложения можно строить на простых Java-объектах. Читатели попросили выложить код отдельно, и так появился фреймворк.</p></aside>\n\n  <h3 id=\"ch3-practice\"><span class=\"sn\">3.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://testcontainers.com/guides/\" target=\"_blank\" rel=\"noopener\">Testcontainers Guides</a><span class=\"note\">Начать с «Getting started with Testcontainers in a Java Spring Boot project».</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://start.spring.io/\" target=\"_blank\" rel=\"noopener\">Spring Initializr</a><span class=\"note\">Генератор каркаса проекта.</span></li>\n  </ul>\n\n  <h3 id=\"ch3-tasks\"><span class=\"sn\">3.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 3.1. Единый формат ошибок</h4>\n    <p>Сделайте обработчик, который на ошибку валидации отдаёт 400 со списком полей, а на «задача не найдена» — 404. Оба ответа — в формате ProblemDetail.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java, Spring Boot 3</figcaption><pre><code>@RestControllerAdvice\nclass ApiErrors {\n\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail invalid(MethodArgumentNotValidException ex) {\n        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);\n        pd.setTitle(\"Validation failed\");\n        pd.setProperty(\"errors\", ex.getBindingResult().getFieldErrors().stream()\n            .collect(Collectors.toMap(FieldError::getField,\n                     e -&gt; String.valueOf(e.getDefaultMessage()), (a, b) -&gt; a)));\n        return pd;\n    }\n\n    @ExceptionHandler(TaskNotFoundException.class)\n    ProblemDetail notFound(TaskNotFoundException ex) {\n        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());\n    }\n}</code></pre></figure>\n      <p><code>@RestControllerAdvice</code> применяется ко всем контроллерам. Spring сам выставит <code>Content-Type: application/problem+json</code>. Третий аргумент <code>toMap</code> нужен, если у поля две ошибки — иначе будет исключение о дубликате ключа.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c3-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 3.2. Тест контроллера</h4>\n    <p>Напишите тест: POST с пустым title должен вернуть 400 и поле <code>errors.title</code> в ответе.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>JUnit 5, MockMvc</figcaption><pre><code>@WebMvcTest(TaskController.class)\nclass TaskControllerTest {\n\n    @Autowired MockMvc mvc;\n    @MockitoBean TaskService service;   // в Spring Boot до 3.4 — @MockBean\n\n    @Test\n    void rejectsEmptyTitle() throws Exception {\n        mvc.perform(post(\"/api/v1/tasks\")\n                .contentType(MediaType.APPLICATION_JSON)\n                .content(\"{\\\"title\\\":\\\"\\\"}\"))\n           .andExpect(status().isBadRequest())\n           .andExpect(jsonPath(\"$.errors.title\").exists());\n    }\n}</code></pre></figure>\n      <p><code>@WebMvcTest</code> поднимает только веб-слой и ваш <code>@RestControllerAdvice</code>. Сервис заменён моком: тест проверяет именно валидацию и формат ошибки, а не бизнес-логику. В <code>CreateTask</code> на поле title должна стоять аннотация <code>@NotBlank</code>.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c3-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c3-e1\"><span>Пройти 5 Spring Guides: REST Service, Accessing Data JPA, Validating Form Input, Testing the Web Layer, Building REST services with Spring.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-e2\"><span>Написать @ControllerAdvice, который отдаёт все ошибки в формате ProblemDetail.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-e3\"><span>Описать API taskhub в OpenAPI и открыть Swagger UI.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-e4\"><span>Написать по одному тесту: @WebMvcTest, @DataJpaTest, @SpringBootTest + Testcontainers.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Почему внедрение через конструктор лучше, чем @Autowired на поле?</summary><p>Зависимости видны в сигнатуре, поля можно сделать final, класс легко создать в unit-тесте без Spring, а циклические зависимости обнаруживаются сразу.</p></details>\n    <details><summary>Какой статус вернуть при создании ресурса и при ошибке валидации?</summary><p>201 Created с заголовком Location. При ошибке валидации — 400 Bad Request (иногда 422) с телом ProblemDetail, где перечислены поля.</p></details>\n    <details><summary>Чем @WebMvcTest отличается от @SpringBootTest?</summary><p>@WebMvcTest поднимает только веб-слой (контроллеры, MockMvc), сервисы подменяются моками; тест быстрый. @SpringBootTest поднимает весь контекст приложения.</p></details>\n    <details><summary>Чем PUT отличается от PATCH?</summary><p>PUT заменяет ресурс целиком и идемпотентен. PATCH меняет часть полей.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 3 из 8</span>\n  <h3 id=\"ch3-thread\">FinTrack, шаг 3: REST API на Spring Boot</h3>\n  <p>Появляется модуль <code>api</code>: загрузка выписки через HTTP, список операций с фильтрами, категории и правила, отчёты. Всё описано в OpenAPI.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://spring.io/projects/spring-boot\" target=\"_blank\" rel=\"noopener\">Spring Boot</a></li><li><a href=\"https://spring.io/projects/spring-data-jpa\" target=\"_blank\" rel=\"noopener\">Spring Data JPA</a></li><li><a href=\"https://springdoc.org/\" target=\"_blank\" rel=\"noopener\">springdoc-openapi</a></li><li><a href=\"https://testcontainers.com/\" target=\"_blank\" rel=\"noopener\">Testcontainers</a></li><li><a href=\"https://start.spring.io/\" target=\"_blank\" rel=\"noopener\">Spring Initializr</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Создайте модуль <code>api</code> через Spring Initializr (Web, Data JPA, Validation, Flyway, PostgreSQL, Actuator) и добавьте его в <code>settings.gradle.kts</code>.</li><li>Подключите <code>core</code> зависимостью и сделайте <code>ImportService</code>: принимает файл, вызывает <code>CsvParser</code> и <code>Categorizer</code> из core, сохраняет через JPA.</li><li>Эндпоинты: <code>POST /api/imports</code> (multipart CSV), <code>GET /api/transactions?month=&amp;category=&amp;page=</code>, CRUD <code>/api/categories</code> и <code>/api/rules</code>, <code>GET /api/reports/monthly?month=</code>.</li><li>Ошибки — ProblemDetail; валидация — Bean Validation; размер файла ограничьте 5 МБ (<code>spring.servlet.multipart.max-file-size</code>).</li><li>Тесты: <code>@WebMvcTest</code> для контроллеров, интеграционный тест импорта на Testcontainers с настоящим PostgreSQL.</li><li>Откройте Swagger UI и сохраните спецификацию в <code>api/openapi.json</code> — по ней на шаге 4 будет сгенерирован клиент.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Одна строка в <code>api/build.gradle.kts</code> — и вся логика шага 1 доступна в Spring. API ничего не знает о формате CSV: он передаёт поток в <code>core</code> и сохраняет результат. Миграции шага 2 Flyway применит при старте.</p></div>\n  <figure class=\"code\"><figcaption>Как api получает core</figcaption><pre><code>// settings.gradle.kts\ninclude(\"core\", \"api\")\n\n// api/build.gradle.kts\ndependencies {\n    implementation(project(\":core\"))\n    implementation(\"org.springframework.boot:spring-boot-starter-web\")\n    implementation(\"org.springframework.boot:spring-boot-starter-data-jpa\")\n    implementation(\"org.springdoc:springdoc-openapi-starter-webmvc-ui:2.6.0\")\n    testImplementation(\"org.springframework.boot:spring-boot-testcontainers\")\n    testImplementation(\"org.testcontainers:postgresql\")\n}\n\n// ImportService: core делает разбор, api — хранение\nList&lt;Transaction&gt; parsed = new CsvParser().parse(file.getInputStream()).transactions();\nparsed.stream().map(t -&gt; TxnEntity.from(t, account, categorizer.categoryOf(t))).forEach(repo::saveIgnoringDuplicates);</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-3a\"><span>Через Swagger UI можно загрузить выписку и получить отчёт за месяц.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-3b\"><span>Интеграционный тест импорта на Testcontainers зелёный.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-3c\"><span><code>api/openapi.json</code> лежит в репозитории.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.3</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch3-test\"><span class=\"sn\">3.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"3\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c3-s1\"><span>Объясняю, как Spring создаёт бины и что делает автоконфигурация.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-s2\"><span>Проектирую REST API: ресурсы, статусы, пагинация, версии.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-s3\"><span>Валидирую входные данные и отдаю ошибки в одном формате.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-s4\"><span>Пишу тесты на всех слоях, включая Testcontainers.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-s5\"><span>Настраиваю профили, Actuator и логирование.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c3-s6\"><span>Проект 2 taskhub-api готов (<a href=\"#p2\">задание</a>).</span></label></li>\n  </ul></div>\n</section>\n\n<!-- ============ ЧАСТЬ II ============ -->\n<div class=\"part-h\" data-part=\"Часть II · Frontend и безопасность\">Часть II · Frontend и безопасность</div>\n\n<section class=\"ch\" id=\"ch4\" data-ch=\"4\" data-title=\"TypeScript и Angular\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 4</div>\n    <h2>TypeScript и Angular</h2>\n    <p class=\"ch-meta\"><span>6 недель</span><span>Проект: taskhub-web</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Писать строго типизированный TypeScript.</li>\n    <li>Строить приложение на современном Angular: standalone-компоненты, signals, новый control flow.</li>\n    <li>Понимать RxJS настолько, чтобы делать поиск, загрузку и отмену запросов правильно.</li>\n    <li>Тестировать компоненты и сценарии пользователя.</li>\n  </ul></div>\n\n  <h3 id=\"ch4-terms\"><span class=\"sn\">4.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>Standalone-компонент</dt><dd>Компонент без NgModule: сам перечисляет, что импортирует. Стандарт с Angular 17.</dd>\n    <dt>Signal</dt><dd>Реактивное значение: <code>signal()</code>, производное — <code>computed()</code>, побочный эффект — <code>effect()</code>.</dd>\n    <dt>Control flow</dt><dd>Встроенные <code>@if</code>, <code>@for</code>, <code>@switch</code> в шаблоне вместо *ngIf и *ngFor.</dd>\n    <dt>Observable</dt><dd>Поток событий RxJS. HttpClient возвращает Observable.</dd>\n    <dt>switchMap</dt><dd>Оператор, который отменяет предыдущий запрос, когда приходит новое значение. Основа «живого» поиска.</dd>\n    <dt>Interceptor</dt><dd>Функция, через которую проходит каждый HTTP-запрос: токен, ошибки, индикатор загрузки.</dd>\n    <dt>Guard</dt><dd>Проверка перед переходом по маршруту (например, «пользователь вошёл?»).</dd>\n  </dl>\n\n  <h3 id=\"ch4-theory\"><span class=\"sn\">4.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://www.typescriptlang.org/docs/handbook/intro.html\" target=\"_blank\" rel=\"noopener\">TypeScript Handbook</a><span class=\"note\">Официальная книга по TypeScript: типы, generics, narrowing, utility types.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://angular.dev/tutorials\" target=\"_blank\" rel=\"noopener\">angular.dev — Tutorials</a><span class=\"note\">Официальные интерактивные уроки. Учить по angular.dev: angular.io описывает устаревшие подходы.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://angular.dev/overview\" target=\"_blank\" rel=\"noopener\">angular.dev — Guides</a><span class=\"note\">Signals, DI, роутинг, формы, HttpClient, тестирование.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://rxjs.dev/guide/overview\" target=\"_blank\" rel=\"noopener\">RxJS — Overview</a><span class=\"note\">Официальное руководство. Операторы с примерами — <a href=\"https://www.learnrxjs.io/\" target=\"_blank\" rel=\"noopener\">Learn RxJS</a>.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://developer.mozilla.org/\" target=\"_blank\" rel=\"noopener\">MDN Web Docs</a><span class=\"note\">HTML, CSS, JavaScript, HTTP, CORS — справочник для всего веба.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://material.angular.dev/\" target=\"_blank\" rel=\"noopener\">Angular Material</a><span class=\"note\">Готовые компоненты и CDK (drag &amp; drop, оверлеи).</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@Angular\" target=\"_blank\" rel=\"noopener\">Angular</a><span class=\"note\">Официальный канал команды Angular.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@DecodedFrontend\" target=\"_blank\" rel=\"noopener\">Decoded Frontend</a><span class=\"note\">Продвинутый Angular: DI, производительность, архитектура.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@JoshuaMorony\" target=\"_blank\" rel=\"noopener\">Joshua Morony</a><span class=\"note\">Signals и реактивный подход.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 4.1. Список задач на signals: данные из API, фильтр, производное значение</figcaption>\n<pre><code>@Component({\n  selector: 'app-task-list',\n  imports: [TaskCardComponent],\n  template: `\n    &lt;input placeholder=\"Фильтр\" (input)=\"filter.set($any($event.target).value)\" /&gt;\n    @for (task of visible(); track task.id) {\n      &lt;app-task-card [task]=\"task\" /&gt;\n    } @empty {\n      &lt;p&gt;Задач нет&lt;/p&gt;\n    }\n  `,\n})\nexport class TaskListComponent {\n  private api = inject(TaskApi);\n  filter = signal('');\n  tasks = toSignal(this.api.list(), { initialValue: [] });\n  visible = computed(() =&gt;\n    this.tasks().filter(t =&gt; t.title.toLowerCase().includes(this.filter().toLowerCase())));\n}</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>AngularJS (2010) и Angular (2016) — разные фреймворки. Вторую версию переписали с нуля на TypeScript, и код с первой на неё не переносится. TypeScript создал Андерс Хейлсберг — автор Turbo Pascal и Delphi и главный архитектор C#.</p></aside>\n\n  <h3 id=\"ch4-practice\"><span class=\"sn\">4.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://angular.dev/tutorials/learn-angular\" target=\"_blank\" rel=\"noopener\">Learn Angular in your browser</a><span class=\"note\">Интерактивный курс на angular.dev — пройти целиком.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://www.typescriptlang.org/play\" target=\"_blank\" rel=\"noopener\">TypeScript Playground</a><span class=\"note\">Проверять типы и примеры из Handbook прямо в браузере.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://playwright.dev/docs/intro\" target=\"_blank\" rel=\"noopener\">Playwright</a><span class=\"note\">E2E-тесты сценариев пользователя.</span></li>\n  </ul>\n\n  <h3 id=\"ch4-tasks\"><span class=\"sn\">4.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 4.1. Живой поиск</h4>\n    <p>Сделайте поле поиска задач: запрос уходит через 300 мс после остановки ввода, при новом вводе старый запрос отменяется, при ошибке список пустой, меньше двух символов — не искать.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Angular, RxJS</figcaption><pre><code>@Component({\n  selector: 'app-search',\n  imports: [ReactiveFormsModule],\n  template: `\n    &lt;input [formControl]=\"q\" placeholder=\"Поиск задач\" /&gt;\n    @for (t of results(); track t.id) { &lt;p&gt;{{ t.title }}&lt;/p&gt; }\n  `,\n})\nexport class SearchComponent {\n  private api = inject(TaskApi);\n  q = new FormControl('', { nonNullable: true });\n\n  results = toSignal(\n    this.q.valueChanges.pipe(\n      debounceTime(300),\n      map(s =&gt; s.trim()),\n      distinctUntilChanged(),\n      switchMap(s =&gt; s.length &lt; 2\n        ? of([])\n        : this.api.search(s).pipe(catchError(() =&gt; of([])))),\n    ),\n    { initialValue: [] as Task[] },\n  );\n}</code></pre></figure>\n      <p><code>debounceTime</code> ждёт паузу в вводе, <code>distinctUntilChanged</code> не повторяет тот же запрос, <code>switchMap</code> отменяет предыдущий HTTP-запрос. <code>catchError</code> стоит внутри <code>switchMap</code>: иначе одна ошибка навсегда завершит весь поток. <code>toSignal</code> сам отписывается при уничтожении компонента.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c4-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 4.2. Interceptor ошибок</h4>\n    <p>Напишите функциональный interceptor: при ответе 5xx показать тост «Сервер недоступен», ошибку пробросить дальше.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Angular</figcaption><pre><code>export const errorInterceptor: HttpInterceptorFn = (req, next) =&gt; {\n  const toast = inject(ToastService);\n  return next(req).pipe(\n    catchError((err: HttpErrorResponse) =&gt; {\n      if (err.status &gt;= 500) toast.show('Сервер недоступен, попробуйте позже');\n      return throwError(() =&gt; err);\n    }),\n  );\n};\n\n// app.config.ts\nexport const appConfig: ApplicationConfig = {\n  providers: [provideHttpClient(withInterceptors([errorInterceptor]))],\n};</code></pre></figure>\n      <p>Функциональные interceptors — современный способ вместо классов с <code>HttpInterceptor</code>. <code>inject()</code> работает внутри них, потому что Angular вызывает их в контексте внедрения. <code>throwError</code> возвращает ошибку вызывающему коду, чтобы компонент тоже мог отреагировать.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c4-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c4-e1\"><span>Прочитать разделы TypeScript Handbook: Everyday Types, Narrowing, Generics, Utility Types.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-e2\"><span>Пройти интерактивный курс angular.dev целиком.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-e3\"><span>Сделать «живой» поиск: debounceTime + distinctUntilChanged + switchMap, проверить отмену запросов во вкладке Network.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-e4\"><span>Написать функциональный interceptor, который показывает тост при ошибке 5xx.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-e5\"><span>Написать e2e-тест Playwright: создать задачу и перетащить её в колонку DONE.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Когда брать signal, а когда Observable?</summary><p>Signal — для состояния, которое нужно прочитать «сейчас» и показать в шаблоне. Observable — для потоков событий во времени: HTTP, ввод с debounce, WebSocket. Между ними переходят через toSignal и toObservable.</p></details>\n    <details><summary>Почему для поиска switchMap, а не mergeMap?</summary><p>switchMap отменяет предыдущий запрос, когда пользователь ввёл новый символ, поэтому старый ответ не перезапишет новый. mergeMap выполняет все запросы параллельно, и ответы могут прийти не по порядку.</p></details>\n    <details><summary>Зачем в @for нужен track?</summary><p>По нему Angular узнаёт элементы при обновлении списка и перерисовывает только изменённые, а не весь список.</p></details>\n    <details><summary>Где во фронтенде хранить токен доступа?</summary><p>Безопаснее всего в памяти, а обновлять через refresh-механизм библиотеки OIDC. localStorage доступен любому скрипту при XSS. В крупных системах часто используют паттерн BFF: токены на сервере, браузер держит только HttpOnly-cookie.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 4 из 8</span>\n  <h3 id=\"ch4-thread\">FinTrack, шаг 4: интерфейс на Angular</h3>\n  <p>Появляется <code>web</code>: загрузка выписки перетаскиванием, таблица операций с фильтрами, редактор категорий и правил, дашборд с графиками трат.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://angular.dev/\" target=\"_blank\" rel=\"noopener\">Angular</a></li><li><a href=\"https://material.angular.dev/\" target=\"_blank\" rel=\"noopener\">Angular Material и CDK</a></li><li><a href=\"https://www.chartjs.org/docs/latest/\" target=\"_blank\" rel=\"noopener\">Chart.js</a></li><li><a href=\"https://openapi-generator.tech/\" target=\"_blank\" rel=\"noopener\">OpenAPI Generator</a></li><li><a href=\"https://playwright.dev/\" target=\"_blank\" rel=\"noopener\">Playwright</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Создайте приложение в папке <code>web</code>: <code>npx @angular/cli new web --routing --style=scss</code>.</li><li>Сгенерируйте клиент API из <code>api/openapi.json</code>: <code>npx @openapitools/openapi-generator-cli generate -i ../api/openapi.json -g typescript-angular -o src/app/api</code>.</li><li>Страницы (lazy-маршруты): «Операции» — таблица с фильтром по месяцу и категории на signals; «Импорт» — зона перетаскивания файла и отчёт о результате; «Категории и правила»; «Дашборд» — круговая диаграмма по категориям и столбцы по месяцам на Chart.js.</li><li>Смена категории операции прямо в таблице (оптимистичное обновление: сразу показать, откатить при ошибке).</li><li>E2E-тест Playwright: загрузить тестовую выписку → увидеть операции → поменять категорию → дашборд изменился.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Во время разработки Angular-сервер на порту 4200 перенаправляет все запросы <code>/api</code> на Spring Boot (8080) — так не нужен CORS, а адреса в коде те же, что будут в продакшене. Сгенерированный клиент гарантирует, что фронтенд и API говорят на одном контракте: изменили API — перегенерировали клиент — компилятор покажет, что сломалось.</p></div>\n  <figure class=\"code\"><figcaption>web/proxy.conf.json и запуск</figcaption><pre><code>{\n  \"/api\": { \"target\": \"http://localhost:8080\", \"secure\": false }\n}\n\n// angular.json → projects.web.architect.serve.options:\n//   \"proxyConfig\": \"proxy.conf.json\"\n// запуск: в одном терминале ./gradlew :api:bootRun, в другом cd web &amp;&amp; npx ng serve</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-4a\"><span>Весь путь «загрузил выписку → увидел график» работает в браузере.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-4b\"><span>Клиент API сгенерирован, ручных HTTP-вызовов с адресами в коде нет.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-4c\"><span>E2E-тест проходит, интерфейс удобен на телефоне.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.4</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch4-test\"><span class=\"sn\">4.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"4\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c4-s1\"><span>Пишу TypeScript в strict-режиме без <code>any</code>.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-s2\"><span>Строю приложение из standalone-компонентов с lazy-loaded маршрутами и guards.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-s3\"><span>Управляю состоянием на signals и знаю, когда нужен NgRx.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-s4\"><span>Делаю Reactive Forms с валидацией и своими валидаторами.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-s5\"><span>Уверенно использую 10 основных операторов RxJS и не забываю об отписке.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4-s6\"><span>Проект 3 taskhub-web готов (<a href=\"#p3\">задание</a>).</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch4b\" data-ch=\"12\" data-title=\"React\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 4Б</div>\n    <h2>React</h2>\n    <p class=\"ch-meta\"><span>3 недели</span><span>После главы 4 — TypeScript уже знаком</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Строить интерфейс из функциональных компонентов на React и TypeScript.</li>\n    <li>Управлять состоянием хуками и понимать, когда компонент перерисовывается.</li>\n    <li>Загружать данные с сервера через TanStack Query: кэш, загрузка, ошибки, отмена.</li>\n    <li>Делать маршруты, формы с валидацией и тесты компонентов.</li>\n    <li>Объяснять разницу между React и Angular и выбирать между ними.</li>\n  </ul></div>\n  <div class=\"box note\"><p>В вакансии Swisscom нужен Angular, но React — самая распространённая библиотека интерфейсов, и его просят во многих full stack вакансиях. После Angular изучить React быстро: TypeScript, компоненты и работа с API уже знакомы.</p></div>\n\n  <h3 id=\"ch4b-terms\"><span class=\"sn\">4Б.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>Компонент</dt><dd>Функция, которая получает данные (props) и возвращает разметку. Весь интерфейс — дерево компонентов.</dd>\n    <dt>JSX</dt><dd>Синтаксис «HTML внутри JavaScript»: <code>&lt;Card title=\"…\" /&gt;</code>. Компилируется в обычные вызовы функций.</dd>\n    <dt>Props</dt><dd>Входные данные компонента от родителя. Только для чтения.</dd>\n    <dt>State</dt><dd>Данные, которые компонент помнит между перерисовками: <code>useState</code>. Изменение состояния вызывает новую отрисовку.</dd>\n    <dt>Хуки</dt><dd>Функции <code>use…</code>: useState, useEffect, useMemo, useContext и свои. Вызываются только на верхнем уровне компонента.</dd>\n    <dt>useEffect</dt><dd>Синхронизация с внешним миром после отрисовки: подписки, таймеры. Для загрузки данных лучше TanStack Query.</dd>\n    <dt>Подъём состояния</dt><dd>Общее состояние двух компонентов хранится в их ближайшем общем родителе и передаётся вниз через props.</dd>\n    <dt>Context</dt><dd>Передача данных глубоко по дереву без props на каждом уровне: тема, текущий пользователь.</dd>\n    <dt>Серверное состояние</dt><dd>Данные с сервера, у которых есть кэш, устаревание и повторные запросы. Им управляет TanStack Query, а не useState.</dd>\n  </dl>\n\n  <h3 id=\"ch4b-theory\"><span class=\"sn\">4Б.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://react.dev/learn\" target=\"_blank\" rel=\"noopener\">react.dev — Learn</a><span class=\"note\">Официальный учебник React: компоненты, состояние, хуки. Начать с «Thinking in React».</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://fullstackopen.com/en/\" target=\"_blank\" rel=\"noopener\">Full Stack Open</a><span class=\"note\">Бесплатный курс Хельсинкского университета: React, TypeScript, тестирование. Части 1, 2, 5 и 9.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://www.patterns.dev/\" target=\"_blank\" rel=\"noopener\">Patterns.dev — Addy Osmani, Lydia Hallie</a><span class=\"note\">Бесплатная онлайн-книга о паттернах React и производительности.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://react-typescript-cheatsheet.netlify.app/\" target=\"_blank\" rel=\"noopener\">React TypeScript Cheatsheet</a><span class=\"note\">Как типизировать props, события, хуки, контекст.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://tanstack.com/query/latest/docs/framework/react/overview\" target=\"_blank\" rel=\"noopener\">TanStack Query</a><span class=\"note\">Загрузка и кэширование данных с сервера.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://reactrouter.com/\" target=\"_blank\" rel=\"noopener\">React Router</a><span class=\"note\">Маршруты и вложенные страницы.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://react-hook-form.com/\" target=\"_blank\" rel=\"noopener\">React Hook Form</a><span class=\"note\">Формы; схемы валидации — <a href=\"https://zod.dev/\" target=\"_blank\" rel=\"noopener\">Zod</a>.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://vite.dev/guide/\" target=\"_blank\" rel=\"noopener\">Vite</a><span class=\"note\">Быстрый сборщик и сервер разработки для нового проекта.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@WebDevSimplified\" target=\"_blank\" rel=\"noopener\">Web Dev Simplified</a><span class=\"note\">Короткие понятные разборы хуков и паттернов React.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@jherr\" target=\"_blank\" rel=\"noopener\">Jack Herrington</a><span class=\"note\">React и TypeScript на продвинутом уровне.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 4Б.1. Тот же список задач, что в листинге 4.1, но на React</figcaption>\n<pre><code>export function TaskList({ tasks }: { tasks: Task[] }) {\n  const [filter, setFilter] = useState('');\n  const visible = useMemo(\n    () =&gt; tasks.filter(t =&gt; t.title.toLowerCase().includes(filter.toLowerCase())),\n    [tasks, filter],\n  );\n  return (\n    &lt;&gt;\n      &lt;input placeholder=\"Фильтр\" value={filter} onChange={e =&gt; setFilter(e.target.value)} /&gt;\n      {visible.length === 0\n        ? &lt;p&gt;Задач нет&lt;/p&gt;\n        : visible.map(t =&gt; &lt;TaskCard key={t.id} task={t} /&gt;)}\n    &lt;/&gt;\n  );\n}</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>React создал Джордан Уок, инженер Facebook. В 2011 году библиотеку впервые использовали в ленте новостей Facebook, в 2012-м — в Instagram, а в мае 2013 года её открыли для всех на конференции JSConf US. Многие разработчики тогда сочли идею «HTML внутри JavaScript» ошибкой — сейчас JSX один из самых распространённых способов описывать интерфейсы.</p></aside>\n\n  <div class=\"tbl\"><table><thead><tr><th>Задача</th><th>Angular</th><th>React</th></tr></thead><tbody>\n    <tr><td>Что это</td><td>Фреймворк «всё включено»</td><td>Библиотека интерфейса, остальное — отдельные библиотеки</td></tr>\n    <tr><td>Состояние</td><td>signal, computed</td><td>useState, useMemo</td></tr>\n    <tr><td>Данные с сервера</td><td>HttpClient + RxJS</td><td>fetch + TanStack Query</td></tr>\n    <tr><td>Маршруты</td><td>Angular Router</td><td>React Router</td></tr>\n    <tr><td>Формы</td><td>Reactive Forms</td><td>React Hook Form + Zod</td></tr>\n    <tr><td>Внедрение зависимостей</td><td>Встроенный DI</td><td>Context и обычные импорты</td></tr>\n    <tr><td>Тесты</td><td>TestBed</td><td>Vitest + Testing Library</td></tr>\n  </tbody></table></div>\n\n  <h3 id=\"ch4b-practice\"><span class=\"sn\">4Б.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://react.dev/learn/tutorial-tic-tac-toe\" target=\"_blank\" rel=\"noopener\">react.dev — Tutorial: Tic-Tac-Toe</a><span class=\"note\">Официальный пошаговый проект: игра крестики-нолики с историей ходов.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://testing-library.com/docs/react-testing-library/intro/\" target=\"_blank\" rel=\"noopener\">Testing Library для React</a><span class=\"note\">Тесты «как пользователь»: найти кнопку по тексту, нажать, проверить результат. Запуск — <a href=\"https://vitest.dev/\" target=\"_blank\" rel=\"noopener\">Vitest</a>.</span></li>\n  </ul>\n\n  <h3 id=\"ch4b-tasks\"><span class=\"sn\">4Б.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 4Б.1. Почему +1, а не +3?</h4>\n    <p>По нажатию кнопки вызывается <code>setCount(count + 1)</code> три раза подряд, но счётчик растёт на 1. Объясните и исправьте.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>React</figcaption><pre><code>// было: все три вызова видят одно и то же значение count из текущей отрисовки\nsetCount(count + 1);\nsetCount(count + 1);\nsetCount(count + 1);\n\n// стало: функция получает актуальное значение после предыдущего обновления\nsetCount(c =&gt; c + 1);\nsetCount(c =&gt; c + 1);\nsetCount(c =&gt; c + 1);</code></pre></figure>\n      <p>Внутри одной отрисовки <code>count</code> — константа (например, 0), поэтому три раза ставится 0 + 1. Обновления состояния собираются в очередь; функция-обновлятор получает результат предыдущего шага, и получается 3. Правило: если новое состояние зависит от старого — передавайте функцию.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c4b-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 4Б.2. Живой поиск на React</h4>\n    <p>Сделайте то же, что в задаче 4.1, но на React: запрос через 300 мс после остановки ввода, не искать при длине меньше 2, устаревший запрос отменяется.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>React, TanStack Query</figcaption><pre><code>function useDebounce&lt;T&gt;(value: T, ms = 300): T {\n  const [v, setV] = useState(value);\n  useEffect(() =&gt; {\n    const id = setTimeout(() =&gt; setV(value), ms);\n    return () =&gt; clearTimeout(id);   // новый ввод — старый таймер отменяется\n  }, [value, ms]);\n  return v;\n}\n\nexport function TaskSearch() {\n  const [q, setQ] = useState('');\n  const term = useDebounce(q.trim());\n  const { data = [], isFetching, isError } = useQuery({\n    queryKey: ['tasks', term],\n    queryFn: ({ signal }) =&gt;\n      fetch(`/api/tasks?q=${encodeURIComponent(term)}`, { signal }).then(r =&gt; r.json() as Promise&lt;Task[]&gt;),\n    enabled: term.length &gt;= 2,\n  });\n  return (\n    &lt;&gt;\n      &lt;input value={q} onChange={e =&gt; setQ(e.target.value)} placeholder=\"Поиск задач\" /&gt;\n      {isFetching &amp;&amp; &lt;p&gt;Ищу…&lt;/p&gt;}\n      {isError &amp;&amp; &lt;p&gt;Не удалось загрузить&lt;/p&gt;}\n      &lt;ul&gt;{data.map(t =&gt; &lt;li key={t.id}&gt;{t.title}&lt;/li&gt;)}&lt;/ul&gt;\n    &lt;/&gt;\n  );\n}</code></pre></figure>\n      <p>Функция очистки в <code>useEffect</code> отменяет таймер при каждом новом вводе — это аналог debounceTime. TanStack Query передаёт <code>signal</code>: если запрос стал не нужен (сменился <code>queryKey</code>), fetch прерывается — аналог switchMap. <code>enabled</code> не даёт искать по короткой строке, а кэш по ключу мгновенно показывает уже найденное.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c4b-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c4b-e1\"><span>Пройти «Thinking in React» и Tutorial: Tic-Tac-Toe на react.dev.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-e2\"><span>Full Stack Open: части 1 и 2 (основы React, работа с сервером) с упражнениями.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-e3\"><span>Переписать канбан-доску из taskhub-web на React и сравнить объём кода и удобство.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-e4\"><span>Написать 3 теста Testing Library: отрисовка списка, фильтр, ошибка загрузки.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Почему хуки нельзя вызывать внутри if и циклов?</summary><p>React связывает состояние с хуком по порядку вызова при каждой отрисовке. Если хук вызывается не всегда, порядок сбивается и состояние «переезжает» к другому хуку.</p></details>\n    <details><summary>Когда useEffect не нужен?</summary><p>Для вычисления значения из props и state (считайте прямо при отрисовке или через useMemo) и для реакции на событие пользователя (делайте в обработчике). useEffect — для синхронизации с внешним миром.</p></details>\n    <details><summary>Зачем key в списке и почему плохо использовать индекс?</summary><p>По key React узнаёт элементы между отрисовками. Индекс меняется при вставке и сортировке — состояние полей ввода может «перепрыгнуть» на соседний элемент. Нужен стабильный id.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · дополнительный шаг 4Б</span>\n  <h3 id=\"ch4b-thread\">FinTrack, шаг 4Б: второй интерфейс на React</h3>\n  <p>Тот же FinTrack, второй фронтенд <code>web-react</code> на том же API. Лучшая демонстрация того, зачем на шаге 3 сделали контракт OpenAPI: сервер не меняется вообще.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://vite.dev/guide/\" target=\"_blank\" rel=\"noopener\">Vite</a></li><li><a href=\"https://react.dev/\" target=\"_blank\" rel=\"noopener\">React</a></li><li><a href=\"https://tanstack.com/query/latest\" target=\"_blank\" rel=\"noopener\">TanStack Query</a></li><li><a href=\"https://reactrouter.com/\" target=\"_blank\" rel=\"noopener\">React Router</a></li><li><a href=\"https://www.chartjs.org/docs/latest/\" target=\"_blank\" rel=\"noopener\">Chart.js</a></li><li><a href=\"https://openapi-generator.tech/\" target=\"_blank\" rel=\"noopener\">OpenAPI Generator</a></li><li><a href=\"https://vitest.dev/\" target=\"_blank\" rel=\"noopener\">Vitest</a></li></ul>\n  <h4>Как делать</h4>\n  <ol>\n    <li>Создайте проект: <code>npm create vite@latest web-react -- --template react-ts</code>.</li>\n    <li>Сгенерируйте клиент из того же файла: <code>npx @openapitools/openapi-generator-cli generate -i ../api/openapi.json -g typescript-fetch -o src/api</code>.</li>\n    <li>Повторите страницы шага 4: «Операции», «Импорт», «Категории и правила», «Дашборд». Данные — через TanStack Query, маршруты — React Router.</li>\n    <li>Смена категории с оптимистичным обновлением: <code>useMutation</code> с <code>onMutate</code> и откатом в <code>onError</code>.</li>\n    <li>Тесты Vitest + Testing Library для таблицы и формы правила.</li>\n    <li>В README сравните два фронтенда: объём кода, время сборки, что было проще.</li>\n  </ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Сервер Vite перенаправляет <code>/api</code> на Spring Boot — так же, как proxy.conf.json у Angular, поэтому код одинаково работает в разработке и в продакшене. На шаге 6 образ nginx может отдавать сборку любого из двух фронтендов: API, Keycloak и база общие. На шаге 5 для входа подойдёт бесплатная библиотека <a href=\"https://github.com/authts/react-oidc-context\" target=\"_blank\" rel=\"noopener\">react-oidc-context</a> с тем же клиентом Keycloak.</p></div>\n  <figure class=\"code\"><figcaption>web-react/vite.config.ts</figcaption><pre><code>import { defineConfig } from 'vite';\nimport react from '@vitejs/plugin-react';\n\nexport default defineConfig({\n  plugins: [react()],\n  server: { proxy: { '/api': 'http://localhost:8080' } },\n});</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-4ba\"><span>Все страницы шага 4 работают на React против того же API.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-4bb\"><span>Клиент сгенерирован из <code>api/openapi.json</code>, сервер не менялся.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-4bc\"><span>Тесты Vitest зелёные, в README есть сравнение Angular и React.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.4.1</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch4b-test\"><span class=\"sn\">4Б.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"12\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c4b-s1\"><span>Пишу функциональные компоненты на React и TypeScript, типизирую props.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-s2\"><span>Понимаю, когда компонент перерисовывается, и правильно использую useState, useEffect, useMemo.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-s3\"><span>Загружаю данные через TanStack Query: кэш, ошибки, мутации.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-s4\"><span>Делаю маршруты и формы с валидацией, пишу тесты Testing Library.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c4b-s5\"><span>Объясняю разницу между React и Angular на собеседовании.</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch5\" data-ch=\"5\" data-title=\"Безопасность и IAM\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 5</div>\n    <h2>Безопасная разработка и IAM</h2>\n    <p class=\"ch-meta\"><span>3 недели</span><span>Проект: taskhub + Keycloak</span></p>\n  </header>\n  <div class=\"box note\"><p>В вакансии отдельно названы secure development и, как плюс, IAM и ForgeRock. Эта глава даёт заметное преимущество перед другими кандидатами.</p></div>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Знать OWASP Top 10 и уметь закрыть каждый пункт в своём коде.</li>\n    <li>Понимать OAuth 2.0 и OpenID Connect на уровне схем потоков.</li>\n    <li>Настроить Spring Security как Resource Server и вход в Angular через Keycloak.</li>\n    <li>Встроить проверку зависимостей и образов в CI.</li>\n  </ul></div>\n\n  <h3 id=\"ch5-terms\"><span class=\"sn\">5.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>Аутентификация</dt><dd>Кто ты (401 Unauthorized, если неизвестно).</dd>\n    <dt>Авторизация</dt><dd>Что тебе можно (403 Forbidden, если нельзя).</dd>\n    <dt>OAuth 2.0</dt><dd>Протокол делегирования доступа: клиент получает access token к API.</dd>\n    <dt>OpenID Connect</dt><dd>Слой над OAuth 2.0 для входа пользователя: добавляет ID token и userinfo.</dd>\n    <dt>PKCE</dt><dd>Защита Authorization Code flow для публичных клиентов (SPA, мобильные).</dd>\n    <dt>JWT</dt><dd>Подписанный токен с полями (claims): кто, до какого времени, какие роли.</dd>\n    <dt>IAM</dt><dd>Identity and Access Management: Keycloak, ForgeRock (с 2023 года в составе Ping Identity), Okta.</dd>\n  </dl>\n\n  <h3 id=\"ch5-theory\"><span class=\"sn\">5.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://owasp.org/www-project-top-ten/\" target=\"_blank\" rel=\"noopener\">OWASP Top 10</a><span class=\"note\">Десять главных рисков веб-приложений.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://cheatsheetseries.owasp.org/\" target=\"_blank\" rel=\"noopener\">OWASP Cheat Sheet Series</a><span class=\"note\">Короткие практические инструкции: пароли, JWT, REST Security, CSRF.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-security/reference/\" target=\"_blank\" rel=\"noopener\">Spring Security Reference</a><span class=\"note\">Главное — архитектура (filter chain) и OAuth2 Resource Server.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://oauth.net/2/\" target=\"_blank\" rel=\"noopener\">oauth.net/2</a><span class=\"note\">Справочник по OAuth 2.0: потоки, RFC, рекомендации.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://www.oauth.com/\" target=\"_blank\" rel=\"noopener\">OAuth 2.0 Simplified — Aaron Parecki</a><span class=\"note\">Бесплатная онлайн-книга одного из авторов спецификаций OAuth: все потоки по шагам.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://owasp.org/www-project-application-security-verification-standard/\" target=\"_blank\" rel=\"noopener\">OWASP ASVS</a><span class=\"note\">Стандарт проверки безопасности приложения: готовый чек-лист требований.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://www.keycloak.org/getting-started\" target=\"_blank\" rel=\"noopener\">Keycloak — Getting Started</a><span class=\"note\">Бесплатный IAM-сервер: realm, клиенты, роли — локально в Docker.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.pingidentity.com/\" target=\"_blank\" rel=\"noopener\">Ping Identity Docs</a><span class=\"note\">Документация ForgeRock AM / IDM / Identity Cloud — для общего понимания продукта.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 5.1. Spring Security: API как OAuth2 Resource Server с проверкой JWT</figcaption>\n<pre><code>@Bean\nSecurityFilterChain api(HttpSecurity http) throws Exception {\n    return http\n        .authorizeHttpRequests(a -&gt; a\n            .requestMatchers(\"/actuator/health\").permitAll()\n            .requestMatchers(HttpMethod.DELETE, \"/api/**\").hasRole(\"ADMIN\")\n            .anyRequest().authenticated())\n        .oauth2ResourceServer(o -&gt; o.jwt(Customizer.withDefaults()))\n        .build();\n}\n// Keycloak кладёт роли в realm_access.roles — для hasRole нужен свой\n// JwtAuthenticationConverter, который превращает их в ROLE_ADMIN и т. д.</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>В декабре 2021 года нашли Log4Shell (CVE-2021-44228) — уязвимость в популярной Java-библиотеке логирования Log4j с максимальной оценкой опасности CVSS 10. Достаточно было записать в лог строку от злоумышленника, чтобы выполнить его код на сервере. Многие компании неделями искали, где у них спрятан Log4j, — поэтому сканирование зависимостей теперь обязательная часть CI.</p></aside>\n\n  <h3 id=\"ch5-practice\"><span class=\"sn\">5.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://portswigger.net/web-security\" target=\"_blank\" rel=\"noopener\">PortSwigger Web Security Academy</a><span class=\"note\">Бесплатные лабораторные работы по уязвимостям: лучшая практика по безопасности.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://owasp.org/www-project-dependency-check/\" target=\"_blank\" rel=\"noopener\">OWASP Dependency-Check</a><span class=\"note\">Проверка зависимостей на известные уязвимости. Образы Docker — <a href=\"https://trivy.dev/\" target=\"_blank\" rel=\"noopener\">Trivy</a>.</span></li>\n  </ul>\n\n  <h3 id=\"ch5-tasks\"><span class=\"sn\">5.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 5.1. Роли из Keycloak</h4>\n    <p>Keycloak кладёт роли в JWT в поле <code>realm_access.roles</code>, а Spring ждёт <code>ROLE_…</code>. Напишите конвертер, чтобы работал <code>hasRole(\"ADMIN\")</code>.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Spring Security</figcaption><pre><code>@Bean\nJwtAuthenticationConverter jwtAuthenticationConverter() {\n    JwtAuthenticationConverter conv = new JwtAuthenticationConverter();\n    conv.setJwtGrantedAuthoritiesConverter(jwt -&gt; {\n        Map&lt;String, Object&gt; realm = jwt.getClaimAsMap(\"realm_access\");\n        if (realm == null) return List.of();\n        @SuppressWarnings(\"unchecked\")\n        List&lt;String&gt; roles = (List&lt;String&gt;) realm.getOrDefault(\"roles\", List.of());\n        return roles.stream()\n            .map(r -&gt; (GrantedAuthority) new SimpleGrantedAuthority(\"ROLE_\" + r))\n            .toList();\n    });\n    return conv;\n}</code></pre></figure>\n      <p>Бин <code>JwtAuthenticationConverter</code> Spring Security подхватывает сам при <code>oauth2ResourceServer(o -> o.jwt(...))</code>. Префикс <code>ROLE_</code> нужен, потому что <code>hasRole(\"ADMIN\")</code> ищет полномочие <code>ROLE_ADMIN</code>.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c5-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 5.2. Найди уязвимость</h4>\n    <p>Что не так с этим кодом и как исправить?<br><code>jdbc.query(\"SELECT * FROM task WHERE title LIKE '%\" + q + \"%'\", mapper);</code></p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java, JdbcTemplate</figcaption><pre><code>// Уязвимо: q = \"' OR '1'='1\" вернёт все задачи,\n// а более хитрый ввод может прочитать или удалить чужие данные.\n\n// Исправлено: значение передаётся параметром, а не склеивается в SQL\njdbc.query(\"SELECT * FROM task WHERE title LIKE ?\", mapper, \"%\" + q + \"%\");</code></pre></figure>\n      <p>Это SQL-инъекция: пользовательский ввод становится частью SQL-кода. Параметр <code>?</code> передаётся базе отдельно от текста запроса, поэтому никогда не исполняется как код. Это пункт A03 Injection в OWASP Top 10.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c5-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c5-e1\"><span>Решить лабораторные PortSwigger: SQL injection, XSS, CSRF, Access control (уровень Apprentice).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-e2\"><span>Поднять Keycloak в Docker, создать realm, клиента для SPA и роли ADMIN / MEMBER.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-e3\"><span>Нарисовать от руки схему Authorization Code + PKCE и объяснить каждый шаг вслух.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-e4\"><span>Подключить Dependabot и Trivy в CI, исправить найденное.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Чем OAuth 2.0 отличается от OpenID Connect?</summary><p>OAuth 2.0 — про доступ к ресурсам (access token). OIDC добавляет вход пользователя: ID token с данными о том, кто вошёл.</p></details>\n    <details><summary>Почему Implicit flow больше не рекомендуют?</summary><p>Токен приходит в URL и может утечь через историю, логи или Referer. Для SPA рекомендован Authorization Code + PKCE (OAuth 2.0 Security Best Current Practice).</p></details>\n    <details><summary>Когда 401, а когда 403?</summary><p>401 — запрос без действительной аутентификации. 403 — пользователь известен, но прав на действие нет.</p></details>\n    <details><summary>Как защититься от SQL-инъекций?</summary><p>Только параметризованные запросы (PreparedStatement, JPA-параметры) и никакой склейки строк с пользовательским вводом. Плюс минимальные права у пользователя БД.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 5 из 8</span>\n  <h3 id=\"ch5-thread\">FinTrack, шаг 5: пользователи и безопасность</h3>\n  <p>FinTrack становится многопользовательским: вход через Keycloak, каждый видит только свои данные, можно вести общий семейный бюджет.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://www.keycloak.org/getting-started/getting-started-docker\" target=\"_blank\" rel=\"noopener\">Keycloak</a></li><li><a href=\"https://docs.spring.io/spring-security/reference/\" target=\"_blank\" rel=\"noopener\">Spring Security</a></li><li><a href=\"https://github.com/damienbod/angular-auth-oidc-client\" target=\"_blank\" rel=\"noopener\">angular-auth-oidc-client</a></li><li><a href=\"https://trivy.dev/\" target=\"_blank\" rel=\"noopener\">Trivy</a></li><li><a href=\"https://owasp.org/www-project-dependency-check/\" target=\"_blank\" rel=\"noopener\">OWASP Dependency-Check</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Добавьте Keycloak в <code>docker-compose.yml</code>, создайте realm <code>fintrack</code>, публичного клиента <code>web</code> (PKCE) и экспортируйте realm в <code>deploy/realm.json</code>, чтобы он поднимался сам.</li><li>API — OAuth2 Resource Server. Добавьте таблицу <code>household</code> и <code>member(household_id, user_sub)</code>; у счёта появляется <code>household_id</code>.</li><li>Каждый запрос фильтруется по семьям текущего пользователя (<code>jwt.sub</code>). Чужой счёт — 404, а не 403, чтобы не раскрывать, что он существует.</li><li>В Angular подключите angular-auth-oidc-client: вход, выход, автоматическое обновление токена; токен к запросам <code>/api</code> добавляет interceptor библиотеки.</li><li>Защита загрузки: только <code>text/csv</code>, не больше 5 МБ. При экспорте в CSV экранируйте ячейки, начинающиеся с <code>= + - @</code> (CSV injection).</li><li>Тесты на 401, 404 для чужих данных и вход в e2e. Trivy и Dependency-Check в CI.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Keycloak становится третьим сервисом рядом с базой и API. Angular получает токен у Keycloak и передаёт его в API, API проверяет подпись по адресу Keycloak (<code>issuer-uri</code>). В коде <code>core</code> ничего не меняется — безопасность живёт на границе (API), а не в бизнес-логике.</p></div>\n  <figure class=\"code\"><figcaption>Keycloak в docker-compose.yml и настройка API</figcaption><pre><code>services:\n  keycloak:\n    image: quay.io/keycloak/keycloak:26.0\n    command: start-dev --import-realm\n    environment:\n      KC_BOOTSTRAP_ADMIN_USERNAME: admin\n      KC_BOOTSTRAP_ADMIN_PASSWORD: admin\n    volumes: [\"./deploy/realm.json:/opt/keycloak/data/import/realm.json\"]\n    ports: [\"8081:8080\"]\n\n# api/src/main/resources/application.yml\nspring.security.oauth2.resourceserver.jwt.issuer-uri: http://localhost:8081/realms/fintrack</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-5a\"><span>Два пользователя не видят данные друг друга; общий семейный счёт видят оба участника.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-5b\"><span>Вход, выход и обновление токена работают в Angular.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-5c\"><span>CSV injection закрыта, сканеры в CI без критичных находок.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.5</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch5-test\"><span class=\"sn\">5.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"5\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c5-s1\"><span>Объясняю каждый пункт OWASP Top 10 и как его закрыть.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-s2\"><span>Рассказываю потоки OAuth 2.0 / OIDC: Authorization Code + PKCE, Client Credentials.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-s3\"><span>Настраиваю Spring Security Resource Server и роли из JWT.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-s4\"><span>Подключаю вход через Keycloak в Angular-приложении.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c5-s5\"><span>Проект 4 готов (<a href=\"#p4\">задание</a>).</span></label></li>\n  </ul></div>\n</section>\n\n<!-- ============ ЧАСТЬ III ============ -->\n<div class=\"part-h\" data-part=\"Часть III · Облако и архитектура\">Часть III · Облако и архитектура</div>\n\n<section class=\"ch\" id=\"ch6\" data-ch=\"6\" data-title=\"Docker, CI/CD, K8s, AWS\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 6</div>\n    <h2>Docker, CI/CD, Kubernetes и AWS</h2>\n    <p class=\"ch-meta\"><span>6 недель</span><span>Проект: taskhub в Kubernetes</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Упаковывать сервисы в компактные и безопасные образы.</li>\n    <li>Строить конвейер: сборка → тесты → проверка → образ → развёртывание.</li>\n    <li>Разворачивать и отлаживать приложение в Kubernetes, описывать его в Helm.</li>\n    <li>Знать базовые сервисы AWS и описывать инфраструктуру в Terraform.</li>\n    <li>Видеть, что происходит с приложением: метрики, логи, трассировка.</li>\n  </ul></div>\n\n  <h3 id=\"ch6-terms\"><span class=\"sn\">6.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>Образ / контейнер</dt><dd>Образ — неизменяемый шаблон, контейнер — его запущенный экземпляр.</dd>\n    <dt>Multi-stage build</dt><dd>Сборка в одном образе, а в итоговый попадает только результат.</dd>\n    <dt>Pod / Deployment</dt><dd>Pod — один или несколько контейнеров вместе; Deployment держит нужное число одинаковых подов и обновляет их.</dd>\n    <dt>Service / Ingress</dt><dd>Постоянный адрес группы подов; Ingress — вход снаружи по HTTP.</dd>\n    <dt>Probes</dt><dd>liveness — «жив ли, не пора ли перезапустить»; readiness — «готов ли принимать трафик».</dd>\n    <dt>Helm</dt><dd>Пакетный менеджер Kubernetes: шаблоны манифестов с параметрами.</dd>\n    <dt>IaC</dt><dd>Инфраструктура как код: Terraform описывает облачные ресурсы файлами.</dd>\n  </dl>\n\n  <h3 id=\"ch6-theory\"><span class=\"sn\">6.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.docker.com/get-started/\" target=\"_blank\" rel=\"noopener\">Docker — Get Started</a><span class=\"note\">Официальное введение: образы, контейнеры, Compose.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.github.com/en/actions\" target=\"_blank\" rel=\"noopener\">GitHub Actions</a><span class=\"note\">Конвейеры CI/CD в GitHub. Для общего понимания — <a href=\"https://docs.gitlab.com/ee/ci/\" target=\"_blank\" rel=\"noopener\">GitLab CI/CD</a>.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://kubernetes.io/docs/tutorials/kubernetes-basics/\" target=\"_blank\" rel=\"noopener\">Kubernetes Basics</a><span class=\"note\">Официальный интерактивный учебник.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://12factor.net/\" target=\"_blank\" rel=\"noopener\">The Twelve-Factor App</a><span class=\"note\">12 принципов облачных приложений: конфигурация, логи, процессы. Основа cloud-native.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://github.com/kelseyhightower/kubernetes-the-hard-way\" target=\"_blank\" rel=\"noopener\">Kubernetes The Hard Way</a><span class=\"note\">Кластер вручную, шаг за шагом, — после основ, чтобы понять устройство изнутри.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://helm.sh/docs/\" target=\"_blank\" rel=\"noopener\">Helm Docs</a><span class=\"note\">Чарты, шаблоны, values.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@TechWorldwithNana\" target=\"_blank\" rel=\"noopener\">TechWorld with Nana</a><span class=\"note\">Понятные курсы по Docker, Kubernetes, CI/CD, Terraform.</span></li>\n    <li><span class=\"tag video\">Видео</span><a href=\"https://www.youtube.com/@freecodecamp\" target=\"_blank\" rel=\"noopener\">freeCodeCamp</a><span class=\"note\">Полные многочасовые курсы по AWS и Kubernetes.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://skillbuilder.aws/\" target=\"_blank\" rel=\"noopener\">AWS Skill Builder</a><span class=\"note\">Бесплатный курс AWS Cloud Practitioner Essentials.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://developer.hashicorp.com/terraform/tutorials\" target=\"_blank\" rel=\"noopener\">Terraform Tutorials</a><span class=\"note\">Официальные уроки HashiCorp, есть трек для AWS.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-boot/reference/actuator/index.html\" target=\"_blank\" rel=\"noopener\">Spring Boot Actuator</a><span class=\"note\">Метрики Micrometer → <a href=\"https://prometheus.io/docs/introduction/overview/\" target=\"_blank\" rel=\"noopener\">Prometheus</a> → Grafana; трассировка — <a href=\"https://opentelemetry.io/docs/languages/java/\" target=\"_blank\" rel=\"noopener\">OpenTelemetry Java</a>.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 6.1. Multi-stage Dockerfile для Spring Boot</figcaption>\n<pre><code>FROM eclipse-temurin:21-jdk AS build\nWORKDIR /app\nCOPY . .\nRUN ./gradlew bootJar --no-daemon\n\nFROM eclipse-temurin:21-jre\nWORKDIR /app\nCOPY --from=build /app/build/libs/*.jar app.jar\nUSER 1000\nEXPOSE 8080\nENTRYPOINT [\"java\", \"-jar\", \"app.jar\"]</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Kubernetes вырос из опыта Google с внутренней системой Borg, которая годами управляла их серверами. Название по-гречески значит «кормчий, рулевой» — отсюда штурвал на логотипе. Сокращение K8s: между K и s ровно 8 букв. А Docker впервые показали публике в 2013 году на конференции PyCon в пятиминутном докладе.</p></aside>\n\n  <figure class=\"code\"><figcaption>Листинг 6.2. GitHub Actions: тесты и образ на каждый push в main</figcaption>\n<pre><code>name: ci\non: { push: { branches: [main] }, pull_request: {} }\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with: { distribution: temurin, java-version: 21 }\n      - run: ./gradlew test\n      - run: docker build -t ghcr.io/${{ github.repository }}:${{ github.sha }} .</code></pre></figure>\n\n  <h3 id=\"ch6-practice\"><span class=\"sn\">6.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://kind.sigs.k8s.io/\" target=\"_blank\" rel=\"noopener\">kind</a><span class=\"note\">Kubernetes в Docker на своём компьютере. Альтернатива — <a href=\"https://minikube.sigs.k8s.io/docs/start/\" target=\"_blank\" rel=\"noopener\">minikube</a>.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://aws.amazon.com/free/\" target=\"_blank\" rel=\"noopener\">AWS Free Tier</a><span class=\"note\">Сразу настроить AWS Budgets с оповещением, чтобы не получить счёт.</span></li>\n  </ul>\n\n  <h3 id=\"ch6-tasks\"><span class=\"sn\">6.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 6.1. Deployment с пробами</h4>\n    <p>Опишите Deployment для taskhub-api: 2 реплики, запрос и лимит памяти, readiness- и liveness-пробы на эндпоинты Spring Boot Actuator.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Kubernetes YAML</figcaption><pre><code>apiVersion: apps/v1\nkind: Deployment\nmetadata: { name: taskhub-api }\nspec:\n  replicas: 2\n  selector: { matchLabels: { app: taskhub-api } }\n  template:\n    metadata: { labels: { app: taskhub-api } }\n    spec:\n      containers:\n        - name: api\n          image: ghcr.io/USER/taskhub-api:1.0.0\n          ports: [{ containerPort: 8080 }]\n          resources:\n            requests: { cpu: 250m, memory: 384Mi }\n            limits: { memory: 512Mi }\n          readinessProbe:\n            httpGet: { path: /actuator/health/readiness, port: 8080 }\n            initialDelaySeconds: 10\n          livenessProbe:\n            httpGet: { path: /actuator/health/liveness, port: 8080 }\n            initialDelaySeconds: 30</code></pre></figure>\n      <p>Spring Boot сам включает группы <code>liveness</code> и <code>readiness</code>, когда видит, что запущен в Kubernetes. Лимит CPU специально не задан: он часто тормозит JVM на старте, а памяти лимит нужен обязательно. Тег образа — конкретная версия, а не <code>latest</code>.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c6-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 6.2. Compose: API и база</h4>\n    <p>Напишите docker-compose.yml: PostgreSQL и API; API должен стартовать только когда база действительно готова.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Docker Compose</figcaption><pre><code>services:\n  db:\n    image: postgres:16\n    environment: { POSTGRES_DB: taskhub, POSTGRES_USER: app, POSTGRES_PASSWORD: app }\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U app -d taskhub\"]\n      interval: 5s\n      retries: 10\n  api:\n    build: .\n    ports: [\"8080:8080\"]\n    environment:\n      SPRING_DATASOURCE_URL: jdbc:postgresql://db:5432/taskhub\n      SPRING_DATASOURCE_USERNAME: app\n      SPRING_DATASOURCE_PASSWORD: app\n    depends_on:\n      db: { condition: service_healthy }</code></pre></figure>\n      <p>Простой <code>depends_on</code> ждёт только запуска контейнера, а не готовности базы. <code>condition: service_healthy</code> вместе с <code>healthcheck</code> ждёт, пока <code>pg_isready</code> ответит успешно. Имя сервиса <code>db</code> работает как имя хоста внутри сети Compose.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c6-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c6-e1\"><span>Уменьшить образ taskhub-api вдвое за счёт multi-stage и JRE-образа; сравнить размеры.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-e2\"><span>Пройти Kubernetes Basics целиком, затем развернуть taskhub в kind вручную через kubectl.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-e3\"><span>Сломать readiness probe и посмотреть через <code>kubectl describe</code>, как под пропадает из Service.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-e4\"><span>Пройти курс Cloud Practitioner Essentials и трек Terraform «Get Started — AWS».</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-e5\"><span>Собрать дашборд Grafana: RPS, p95 времени ответа, ошибки 5xx.</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Чем liveness probe отличается от readiness probe?</summary><p>Провал liveness — Kubernetes перезапускает контейнер. Провал readiness — под временно убирается из Service и не получает трафик, но не перезапускается.</p></details>\n    <details><summary>Зачем нужен multi-stage build?</summary><p>JDK, Gradle и исходники остаются в промежуточном образе, в итоговом только JRE и jar. Образ меньше, быстрее скачивается и содержит меньше уязвимостей.</p></details>\n    <details><summary>Чем Deployment отличается от StatefulSet?</summary><p>Deployment — для одинаковых взаимозаменяемых подов без состояния. StatefulSet даёт подам постоянные имена и собственные тома — для баз данных и брокеров.</p></details>\n    <details><summary>Как не переплатить за учебный аккаунт AWS?</summary><p>Включить AWS Budgets с оповещением на почту, создавать ресурсы только через Terraform и после демонстрации выполнять <code>terraform destroy</code>. EKS и NAT Gateway платные даже при простое.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 6 из 8</span>\n  <h3 id=\"ch6-thread\">FinTrack, шаг 6: контейнеры, CI/CD и Kubernetes</h3>\n  <p>Вся система поднимается одной командой, каждая правка проверяется в CI, а приложение работает в локальном Kubernetes с мониторингом.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://docs.docker.com/compose/\" target=\"_blank\" rel=\"noopener\">Docker / Docker Compose</a></li><li><a href=\"https://nginx.org/en/docs/\" target=\"_blank\" rel=\"noopener\">nginx</a></li><li><a href=\"https://docs.github.com/en/actions\" target=\"_blank\" rel=\"noopener\">GitHub Actions</a></li><li><a href=\"https://kind.sigs.k8s.io/\" target=\"_blank\" rel=\"noopener\">kind</a></li><li><a href=\"https://helm.sh/docs/\" target=\"_blank\" rel=\"noopener\">Helm</a></li><li><a href=\"https://github.com/prometheus-community/helm-charts/tree/main/charts/kube-prometheus-stack\" target=\"_blank\" rel=\"noopener\">kube-prometheus-stack</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Multi-stage Dockerfile для <code>api</code> (JDK собирает, JRE запускает) и для <code>web</code> (Node собирает, nginx отдаёт статику и проксирует <code>/api</code>).</li><li>Полный <code>docker-compose.yml</code>: db, keycloak, api, web. Цель — <code>docker compose up</code> и открыть <code>http://localhost</code>.</li><li>GitHub Actions (бесплатно для публичных репозиториев): тесты core и api, сборка web, e2e, Trivy, публикация образов в GitHub Container Registry.</li><li>Кластер kind; Helm-чарт <code>deploy/helm/fintrack</code> с Deployment и Service для api и web, Ingress, пробами Actuator и Secret для паролей.</li><li>Мониторинг: kube-prometheus-stack, метрики Micrometer, дашборд Grafana «импорты в час, ошибки, p95».</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>nginx в образе <code>web</code> делает то же, что proxy.conf.json на шаге 4: <code>/api</code> уходит в сервис <code>api</code>. Поэтому код Angular не меняется между разработкой и продакшеном. В Kubernetes имена сервисов (<code>api</code>, <code>keycloak</code>) работают как DNS-имена — та же схема, что в Compose.</p></div>\n  <figure class=\"code\"><figcaption>web/nginx.conf — фронтенд и API под одним адресом</figcaption><pre><code>server {\n  listen 80;\n  root /usr/share/nginx/html;\n\n  location /api/ {\n    proxy_pass http://api:8080;      # имя сервиса в Compose и в Kubernetes\n  }\n  location / {\n    try_files $uri $uri/ /index.html; # маршруты Angular\n  }\n}</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-6a\"><span><code>docker compose up</code> поднимает всю систему с нуля.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-6b\"><span>CI зелёный, образы публикуются в GHCR.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-6c\"><span>В kind работает Helm-релиз, в Grafana видны метрики.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.6</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch6-test\"><span class=\"sn\">6.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"6\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c6-s1\"><span>Пишу Dockerfile и docker-compose для сервиса с базой.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-s2\"><span>Строю CI/CD в GitHub Actions: тесты, проверки, образ, развёртывание.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-s3\"><span>Разворачиваю и отлаживаю приложение в Kubernetes, пишу Helm-чарт.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-s4\"><span>Знаю IAM, VPC, EC2, ECR, EKS/ECS, RDS, S3, CloudWatch на базовом уровне.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-s5\"><span>Описываю инфраструктуру в Terraform.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c6-s6\"><span>Проект 5 готов (<a href=\"#p5\">задание</a>).</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch7\" data-ch=\"7\" data-title=\"Микросервисы и интеграции\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 7</div>\n    <h2>Микросервисы и интеграции</h2>\n    <p class=\"ch-meta\"><span>4 недели</span><span>Проект: APIForge</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Делить систему на сервисы по бизнес-границам, а не по слоям.</li>\n    <li>Выбирать между синхронным REST и асинхронными сообщениями.</li>\n    <li>Делать систему устойчивой к сбоям соседей.</li>\n    <li>Понимать интеграционные паттерны (EAI), которыми занимается команда в Swisscom.</li>\n  </ul></div>\n\n  <h3 id=\"ch7-terms\"><span class=\"sn\">7.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>API Gateway</dt><dd>Единая точка входа: маршрутизация, аутентификация, лимиты.</dd>\n    <dt>Bounded context</dt><dd>Граница модели предметной области из DDD; хороший кандидат в отдельный сервис.</dd>\n    <dt>Circuit Breaker</dt><dd>«Предохранитель»: при серии сбоев перестаёт звать сервис и сразу отдаёт запасной ответ.</dd>\n    <dt>Outbox</dt><dd>Запись события в таблицу в той же транзакции, что и данные; отдельный процесс публикует его в брокер.</dd>\n    <dt>Saga</dt><dd>Распределённая операция как цепочка локальных транзакций с компенсирующими действиями.</dd>\n    <dt>Контрактный тест</dt><dd>Проверка, что поставщик API и потребитель понимают контракт одинаково.</dd>\n  </dl>\n\n  <h3 id=\"ch7-theory\"><span class=\"sn\">7.2</span>Теория</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Сайт</span><a href=\"https://microservices.io/\" target=\"_blank\" rel=\"noopener\">microservices.io</a><span class=\"note\">Бесплатный каталог паттернов микросервисов Chris Richardson.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://martinfowler.com/articles/microservices.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler — Microservices</a><span class=\"note\">Статья, с которой началось широкое обсуждение микросервисов: признаки и компромиссы.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://www.enterpriseintegrationpatterns.com/patterns/messaging/\" target=\"_blank\" rel=\"noopener\">Enterprise Integration Patterns</a><span class=\"note\">Бесплатный каталог паттернов интеграции (EAI) Gregor Hohpe и Bobby Woolf — то, чем занимается команда.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://martinfowler.com/bliki/MonolithFirst.html\" target=\"_blank\" rel=\"noopener\">Martin Fowler — MonolithFirst</a><span class=\"note\">Почему начинать стоит с монолита.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://spring.io/projects/spring-cloud-gateway\" target=\"_blank\" rel=\"noopener\">Spring Cloud Gateway</a><span class=\"note\">Шлюз на Spring: маршруты, фильтры, rate limiting.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://resilience4j.readme.io/\" target=\"_blank\" rel=\"noopener\">Resilience4j</a><span class=\"note\">Circuit Breaker, Retry, Rate Limiter, Bulkhead.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://kafka.apache.org/quickstart\" target=\"_blank\" rel=\"noopener\">Apache Kafka Quickstart</a><span class=\"note\">Запустить Kafka и отправить первые сообщения.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://developer.confluent.io/courses/\" target=\"_blank\" rel=\"noopener\">Confluent Developer Courses</a><span class=\"note\">Бесплатные курсы: Kafka 101, Spring for Apache Kafka.</span></li>\n  </ul>\n\n  <figure class=\"code\"><figcaption>Листинг 7.1. Resilience4j: предохранитель с запасным ответом из кэша</figcaption>\n<pre><code>@CircuitBreaker(name = \"catalog\", fallbackMethod = \"lastKnown\")\npublic List&lt;ApiSummary&gt; fetchCatalog() {\n    return catalogClient.list();\n}\n\nprivate List&lt;ApiSummary&gt; lastKnown(Throwable ex) {\n    log.warn(\"catalog unavailable, serving cache\", ex);\n    return cache.lastKnown();\n}</code></pre></figure>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Закон Конвея (1967): организации проектируют системы, повторяющие структуру своих коммуникаций. Поэтому микросервисы — вопрос не только архитектуры, но и устройства команд. А Apache Kafka создали в LinkedIn около 2010 года; Джей Крепс назвал её в честь писателя Франца Кафки, потому что это «система, оптимизированная для записи».</p></aside>\n\n  <h3 id=\"ch7-practice\"><span class=\"sn\">7.3</span>Практика</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://spring.io/projects/spring-cloud-contract\" target=\"_blank\" rel=\"noopener\">Spring Cloud Contract</a><span class=\"note\">Контрактные тесты. Альтернатива — <a href=\"https://docs.pact.io/\" target=\"_blank\" rel=\"noopener\">Pact</a>.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.spring.io/spring-kafka/reference/\" target=\"_blank\" rel=\"noopener\">Spring for Apache Kafka</a><span class=\"note\">Продюсеры, консьюмеры, обработка ошибок.</span></li>\n  </ul>\n\n  <h3 id=\"ch7-tasks\"><span class=\"sn\">7.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 7.1. Идемпотентный консьюмер</h4>\n    <p>Kafka может доставить событие использования API дважды. Напишите обработчик, который увеличивает счётчик вызовов за день ровно один раз на событие.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java, Spring Kafka, PostgreSQL</figcaption><pre><code>@KafkaListener(topics = \"api-usage\")\n@Transactional\npublic void on(UsageEvent e) {\n    int inserted = jdbc.update(\n        \"INSERT INTO processed_event (id) VALUES (?) ON CONFLICT DO NOTHING\",\n        e.eventId());\n    if (inserted == 0) return;   // это событие уже обработано\n\n    jdbc.update(\"\"\"\n        INSERT INTO usage_daily (api_id, day, calls) VALUES (?, ?, 1)\n        ON CONFLICT (api_id, day) DO UPDATE SET calls = usage_daily.calls + 1\n        \"\"\", e.apiId(), e.day());\n}</code></pre></figure>\n      <p>Таблица <code>processed_event</code> с первичным ключом по id события запоминает обработанные события. Обе вставки в одной транзакции: либо засчитано и запомнено, либо ни то ни другое. Повторная доставка увидит <code>inserted == 0</code> и ничего не изменит.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c7-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 7.2. Outbox</h4>\n    <p>При одобрении подписки нужно сохранить её в БД и отправить событие в Kafka. Сделайте так, чтобы событие не потерялось и не ушло без сохранённых данных.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java, Spring</figcaption><pre><code>@Transactional\npublic Subscription approve(long id) {\n    Subscription s = repo.findById(id).orElseThrow();\n    s.approve();\n    outbox.save(new OutboxEvent(\"subscription.approved\", s.getId(), toJson(s)));\n    return s;   // данные и событие сохраняются в одной транзакции\n}\n\n@Scheduled(fixedDelay = 1000)\n@Transactional\npublic void publish() throws Exception {\n    for (OutboxEvent e : outbox.findTop100BySentFalseOrderById()) {\n        kafka.send(\"subscriptions\", e.getKey(), e.getPayload()).get();  // ждём подтверждения\n        e.markSent();\n    }\n}</code></pre></figure>\n      <p>Событие пишется в таблицу outbox в той же транзакции, что и данные, — двойной записи больше нет. Отдельная задача публикует неотправленные события. Если она упадёт после отправки, но до <code>markSent</code>, событие уйдёт ещё раз — поэтому консьюмеры и должны быть идемпотентными (задача 7.1).</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c7-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <div class=\"box ex\"><h4>Упражнения</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c7-e1\"><span>Пройти Kafka 101 на Confluent Developer.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-e2\"><span>Реализовать Outbox: событие в таблицу в одной транзакции и публикация в Kafka по расписанию.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-e3\"><span>Выключить сервис-зависимость и показать, как срабатывает Circuit Breaker (метрики в Actuator).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-e4\"><span>Написать ADR «Почему REST между catalog и subscription, а Kafka для usage».</span></label></li>\n  </ul></div>\n\n  <div class=\"box quiz\"><h4>Проверь себя</h4>\n    <details><summary>Когда микросервисы НЕ нужны?</summary><p>Маленькая команда, неясная предметная область, нет автоматизации развёртывания и наблюдаемости. Тогда лучше модульный монолит (Fowler, «MonolithFirst»).</p></details>\n    <details><summary>Какую проблему решает Outbox?</summary><p>Проблему «двойной записи»: нельзя атомарно сохранить данные в БД и отправить сообщение в брокер. Outbox делает запись события частью той же транзакции БД.</p></details>\n    <details><summary>Какие состояния у Circuit Breaker?</summary><p>CLOSED — вызовы идут; OPEN — вызовы сразу отклоняются; HALF_OPEN — пробные вызовы, чтобы понять, восстановился ли сервис.</p></details>\n    <details><summary>Почему консьюмер Kafka должен быть идемпотентным?</summary><p>Обычная гарантия доставки — at-least-once: одно сообщение может прийти дважды (например, после ребалансировки). Повторная обработка не должна портить данные.</p></details>\n  </div>\n\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 7 из 8</span>\n  <h3 id=\"ch7-thread\">FinTrack, шаг 7: микросервисы и события</h3>\n  <p>Импорт уходит в отдельный асинхронный сервис, появляются бюджеты с уведомлениями о превышении и пересчёт валют по курсам ЕЦБ.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://kafka.apache.org/quickstart\" target=\"_blank\" rel=\"noopener\">Apache Kafka</a></li><li><a href=\"https://docs.spring.io/spring-kafka/reference/\" target=\"_blank\" rel=\"noopener\">Spring for Apache Kafka</a></li><li><a href=\"https://spring.io/projects/spring-cloud-gateway\" target=\"_blank\" rel=\"noopener\">Spring Cloud Gateway</a></li><li><a href=\"https://resilience4j.readme.io/\" target=\"_blank\" rel=\"noopener\">Resilience4j</a></li><li><a href=\"https://frankfurter.dev/\" target=\"_blank\" rel=\"noopener\">Frankfurter (курсы ЕЦБ)</a></li><li><a href=\"https://mailpit.axllent.org/\" target=\"_blank\" rel=\"noopener\">Mailpit</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>Новый модуль <code>import-service</code>: тоже зависит от <code>core</code>. API при загрузке сохраняет файл, пишет событие <code>import.requested</code> через Outbox и сразу отвечает <code>202 Accepted</code> с id импорта.</li><li><code>import-service</code> читает событие, разбирает файл, сохраняет операции идемпотентно (уникальный <code>import_hash</code> из шага 2) и публикует <code>transactions.imported</code>.</li><li>Новый модуль <code>budget-service</code>: бюджеты по категориям на месяц; при <code>transactions.imported</code> пересчитывает траты и публикует <code>budget.exceeded</code>.</li><li><code>notifier</code> слушает <code>budget.exceeded</code> и отправляет письмо (локально — Mailpit) или сообщение Telegram-боту.</li><li>Пересчёт в евро: клиент к бесплатному API Frankfurter с Circuit Breaker и кэшем последних курсов.</li><li>Spring Cloud Gateway — единый вход: проверка JWT, маршруты к api и budget-service. Трассировка OpenTelemetry показывает путь импорта через все сервисы.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Соединяют сервисы не вызовы друг друга, а события в Kafka: <code>import.requested → transactions.imported → budget.exceeded</code>. <code>core</code> теперь используют два модуля — вот зачем на шаге 1 его держали без Spring. В Compose и Helm добавляются kafka, import-service, budget-service, notifier, gateway; nginx из шага 6 теперь проксирует <code>/api</code> на gateway.</p></div>\n  <div class=\"tbl\"><table><thead><tr><th>Событие</th><th>Кто публикует</th><th>Кто слушает</th><th>Ключ</th></tr></thead><tbody>\n<tr><td><code>import.requested</code></td><td>api (Outbox)</td><td>import-service</td><td>accountId</td></tr>\n<tr><td><code>transactions.imported</code></td><td>import-service</td><td>budget-service</td><td>householdId</td></tr>\n<tr><td><code>budget.exceeded</code></td><td>budget-service</td><td>notifier</td><td>householdId</td></tr>\n</tbody></table></div>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-7a\"><span>Загрузка возвращает 202, операции появляются через секунды; при повторной доставке события дублей нет.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-7b\"><span>Превышение бюджета приходит письмом в Mailpit.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-7c\"><span>При недоступном Frankfurter работают кэшированные курсы; в трассировке виден весь путь импорта.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v0.7</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch7-test\"><span class=\"sn\">7.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"7\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c7-s1\"><span>Делю систему на сервисы по бизнес-границам и защищаю решение в ADR.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-s2\"><span>Пишу продюсеров и консьюмеров Kafka с обработкой ошибок и повторов.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-s3\"><span>Применяю Circuit Breaker, Retry, Outbox, идемпотентность.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-s4\"><span>Настраиваю шлюз: маршруты, JWT, rate limiting.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c7-s5\"><span>Пишу контрактные тесты и смотрю распределённую трассировку.</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch8\" data-ch=\"8\" data-title=\"Сквозные навыки\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 8</div>\n    <h2>Сквозные навыки</h2>\n    <p class=\"ch-meta\"><span>1–2 часа в неделю на протяжении всего курса</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Понимать, как работает команда в масштабированном Agile (SAFe).</li>\n    <li>Писать чистый и проверяемый код.</li>\n    <li>Быть готовым к алгоритмической части собеседования.</li>\n  </ul></div>\n\n  <h3 id=\"ch8-agile\"><span class=\"sn\">8.1</span>Agile и SAFe</h3>\n  <p>Команда в вакансии называется «API ART». ART — Agile Release Train из SAFe: несколько команд, которые планируют работу вместе на квартал (PI Planning) и поставляют её спринтами.</p>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://scrumguides.org/scrum-guide.html\" target=\"_blank\" rel=\"noopener\">The Scrum Guide</a><span class=\"note\">13 страниц — официальное описание Scrum.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://framework.scaledagile.com/agile-release-train/\" target=\"_blank\" rel=\"noopener\">SAFe — Agile Release Train</a><span class=\"note\">Что такое ART, PI Planning, роли.</span></li>\n  </ul>\n\n  <h3 id=\"ch8-quality\"><span class=\"sn\">8.2</span>Качество кода</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://google.github.io/styleguide/javaguide.html\" target=\"_blank\" rel=\"noopener\">Google Java Style Guide</a><span class=\"note\">Правила оформления Java-кода, которые используют во многих командах.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://refactoring.guru/refactoring\" target=\"_blank\" rel=\"noopener\">Refactoring.Guru — Refactoring</a><span class=\"note\">Бесплатный каталог «запахов кода» и приёмов рефакторинга.</span></li>\n    <li><span class=\"tag book\">Книга</span><a href=\"https://opendatastructures.org/\" target=\"_blank\" rel=\"noopener\">Open Data Structures (Java) — Pat Morin</a><span class=\"note\">Бесплатная книга о структурах данных с кодом на Java — к собеседованию.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://sonarcloud.io/\" target=\"_blank\" rel=\"noopener\">SonarCloud</a><span class=\"note\">Бесплатный анализ кода для публичных репозиториев.</span></li>\n  </ul>\n\n  <h3 id=\"ch8-algo\"><span class=\"sn\">8.3</span>Алгоритмы к собеседованию</h3>\n  <ul class=\"res\">\n    <li><span class=\"tag course\">Курс</span><a href=\"https://neetcode.io/practice\" target=\"_blank\" rel=\"noopener\">NeetCode 150</a><span class=\"note\">150 задач по темам с видеоразборами.</span></li>\n    <li><span class=\"tag course\">Курс</span><a href=\"https://leetcode.com/\" target=\"_blank\" rel=\"noopener\">LeetCode</a><span class=\"note\">3–4 задачи в неделю, уровни Easy и Medium.</span></li>\n  </ul>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Agile-манифест подписали 17 разработчиков в феврале 2001 года на горнолыжном курорте Сноуберд в штате Юта. Весь манифест — четыре ценности и двенадцать принципов, он умещается на одной странице agilemanifesto.org.</p></aside>\n  <h3 id=\"ch8-tasks\"><span class=\"sn\">8.4</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 8.1. Скобки</h4>\n    <p>Классическая задача собеседований: проверьте, что в строке правильно расставлены скобки <code>()[]{}</code>. Сложность O(n).</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java</figcaption><pre><code>static boolean balanced(String s) {\n    Deque&lt;Character&gt; st = new ArrayDeque&lt;&gt;();\n    for (char c : s.toCharArray()) {\n        switch (c) {\n            case '(', '[', '{' -&gt; st.push(c);\n            case ')' -&gt; { if (st.isEmpty() || st.pop() != '(') return false; }\n            case ']' -&gt; { if (st.isEmpty() || st.pop() != '[') return false; }\n            case '}' -&gt; { if (st.isEmpty() || st.pop() != '{') return false; }\n            default -&gt; { }\n        }\n    }\n    return st.isEmpty();\n}</code></pre></figure>\n      <p>Открывающая скобка кладётся в стек, закрывающая должна совпасть с верхушкой стека. В конце стек должен быть пустым. <code>ArrayDeque</code> — рекомендуемая замена устаревшему классу <code>Stack</code>.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"c8-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"thread\">\n  <span class=\"th-tag\">Сквозной проект · шаг 8 из 8</span>\n  <h3 id=\"ch8-thread\">FinTrack, шаг 8: качество и выпуск v1.0</h3>\n  <p>Всё собирается в цельный, проверенный и задокументированный продукт, который не стыдно показать на собеседовании.</p>\n  <h4>Технологии (все бесплатные)</h4>\n  <ul class=\"tech\"><li><a href=\"https://www.archunit.org/userguide/html/000_Index.html\" target=\"_blank\" rel=\"noopener\">ArchUnit</a></li><li><a href=\"https://sonarcloud.io/\" target=\"_blank\" rel=\"noopener\">SonarCloud</a></li><li><a href=\"https://grafana.com/docs/k6/latest/\" target=\"_blank\" rel=\"noopener\">k6</a></li><li><a href=\"https://c4model.com/\" target=\"_blank\" rel=\"noopener\">C4 model</a></li><li><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">ADR</a></li></ul>\n  <h4>Как делать</h4>\n  <ol><li>ArchUnit-тесты границ: <code>core</code> не зависит от Spring, сервисы не ходят в чужие базы.</li><li>SonarCloud для всех модулей; исправить критичные замечания, покрытие core — не меньше 80 %.</li><li>Нагрузочный тест k6: 50 одновременных импортов по 5 000 строк; записать время и узкое место.</li><li>Документация: C4-диаграммы (контекст, контейнеры), 5–7 ADR с главными решениями, README с запуском одной командой.</li><li>Выпуск: тег <code>v1.0</code>, GitHub Release с описанием изменений, видео-демо на 3 минуты, демо-пользователи в <code>realm.json</code>.</li></ol>\n  <h4>Как соединить с предыдущими шагами</h4>\n  <div class=\"join\"><p>Здесь проверяется, что все части действительно работают вместе: один e2e-сценарий проходит через Angular → gateway → api → Kafka → import-service → budget-service → notifier. Если он зелёный в CI на каждом коммите, система цельная.</p></div>\n  <figure class=\"code\"><figcaption>ArchUnit: core остаётся чистым</figcaption><pre><code>@AnalyzeClasses(packages = \"dev.fintrack\")\nclass ArchitectureTest {\n\n    @ArchTest\n    static final ArchRule coreIsPure = noClasses()\n        .that().resideInAPackage(\"dev.fintrack.core..\")\n        .should().dependOnClassesThat().resideInAPackage(\"org.springframework..\");\n}</code></pre></figure>\n  <h4>Шаг готов, когда</h4>\n  <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"th-8a\"><span>Сквозной e2e-сценарий через все сервисы зелёный в CI.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-8b\"><span>ArchUnit и SonarCloud без нарушений, покрытие core ≥ 80 %.</span></label></li><li><label><input type=\"checkbox\" data-k=\"th-8c\"><span>Есть тег v1.0, Release, README, C4, ADR и видео-демо.</span></label></li></ul>\n  <p class=\"ch-meta\"><span>Коммит и тег <code>v1.0</code></span><span>Навигация: <a href=\"#intro-thread\">обзор проекта</a></span></p>\n  </div>\n\n  <h3 id=\"ch8-test\"><span class=\"sn\">8.5</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"8\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"c8-s1\"><span>Объясняю, что такое ART, PI Planning, Definition of Done.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c8-s2\"><span>SonarCloud подключён ко всем проектам, критичных замечаний нет.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c8-s3\"><span>Решено 75 задач NeetCode.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c8-s4\"><span>Решено 150 задач NeetCode.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"c8-s5\"><span>README, коммиты и документация всех проектов — на английском.</span></label></li>\n  </ul></div>\n</section>\n\n<!-- ============ ЧАСТЬ IV ============ -->\n<div class=\"part-h\" data-part=\"Часть IV · Практикум\">Часть IV · Практикум</div>\n\n<section class=\"ch\" id=\"ch9\" data-ch=\"9\" data-title=\"Тренировочные проекты\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 9</div>\n    <h2>Тренировочные проекты</h2>\n    <p class=\"ch-meta\"><span>Идут вместе с главами 1–6</span><span>Каждый — в портфолио</span></p>\n  </header>\n  <div class=\"box note\"><p>У каждого проекта: README по <a href=\"#appA\">шаблону из Приложения А</a>, зелёный CI и не меньше 70 % покрытия бизнес-логики тестами. Проекты 2–5 — одна система, которая растёт от главы к главе.</p></div>\n\n  <h3 id=\"p1\"><span class=\"sn\">9.1</span>Проект 1 — logscope (Java CLI)</h3>\n  <p>Анализатор логов: читает access-логи nginx и Spring, считает топ ошибок, медленные адреса и запросы в минуту; выводит отчёт в консоль, JSON или CSV. Пригодится потом для отладки на работе.</p>\n  <p><b>Стек:</b> Java 21, records, Stream API, virtual threads, picocli, JUnit 5, Gradle.</p>\n<pre class=\"tree\">logscope/\n ├─ src/main/java/dev/logscope/\n │   ├─ cli/        # picocli-команды\n │   ├─ parse/      # парсеры форматов (sealed interface LogFormat)\n │   ├─ stats/      # агрегаты на Stream API\n │   └─ report/     # консоль, JSON, CSV\n ├─ src/test/java/...\n ├─ samples/        # примеры логов\n └─ .github/workflows/ci.yml</pre>\n  <div class=\"box ex\"><h4>Готово, когда</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"p1-1\"><span>Разбирает минимум 2 формата логов, формат определяется сам.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p1-2\"><span>Файл в 1 ГБ обрабатывается, в README — замер времени.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p1-3\"><span>Тесты на парсеры и агрегаты, CI зелёный.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p1-4\"><span>Опубликован GitHub Release с исполняемым jar.</span></label></li>\n  </ul></div>\n\n  <h3 id=\"p2\"><span class=\"sn\">9.2</span>Проект 2 — taskhub-api (Spring Boot REST)</h3>\n  <p>API трекера задач: проекты, задачи, исполнители, статусы, комментарии, фильтры и пагинация.</p>\n  <p><b>Стек:</b> Spring Boot, Spring Data JPA, PostgreSQL, Flyway, springdoc-openapi, Testcontainers.</p>\n<pre class=\"tree\">taskhub-api/\n ├─ src/main/java/.../{project,task,user}/   # пакет на фичу: controller, service, repo, dto\n ├─ src/main/resources/db/migration/          # Flyway V1__init.sql …\n ├─ src/test/java/...                         # unit + Testcontainers\n ├─ docker-compose.yml                        # postgres\n └─ .github/workflows/ci.yml</pre>\n  <div class=\"box ex\"><h4>Готово, когда</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"p2-1\"><span>Swagger UI описывает все эндпоинты с примерами.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p2-2\"><span>Все ошибки — в формате ProblemDetail.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p2-3\"><span>Интеграционные тесты на Testcontainers проходят в CI.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p2-4\"><span>В логе SQL нет N+1 на списках.</span></label></li>\n  </ul></div>\n\n  <h3 id=\"p3\"><span class=\"sn\">9.3</span>Проект 3 — taskhub-web (Angular)</h3>\n  <p>Интерфейс для taskhub-api: канбан-доска с перетаскиванием, формы с валидацией, поиск, тёмная тема.</p>\n  <p><b>Стек:</b> Angular, signals, Angular Material и CDK, RxJS, Playwright.</p>\n<pre class=\"tree\">taskhub-web/\n ├─ src/app/\n │   ├─ core/        # interceptors, guards, api-клиенты\n │   ├─ features/\n │   │   ├─ board/   # канбан (lazy)\n │   │   └─ projects/\n │   └─ shared/      # общие компоненты\n ├─ e2e/             # Playwright\n └─ .github/workflows/ci.yml</pre>\n  <div class=\"box ex\"><h4>Готово, когда</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"p3-1\"><span>Канбан с drag &amp; drop сохраняет статус через API.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p3-2\"><span>Поиск с debounce и отменой запросов; interceptor для ошибок и загрузки.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p3-3\"><span>Удобно и на телефоне, и на компьютере; e2e-тест основных сценариев.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p3-4\"><span>Фронтенд развёрнут (GitHub Pages, Netlify или S3), ссылка в README.</span></label></li>\n  </ul></div>\n\n  <h3 id=\"p4\"><span class=\"sn\">9.4</span>Проект 4 — безопасность taskhub</h3>\n  <p>Keycloak в docker-compose; вход в Angular через Authorization Code + PKCE; API — OAuth2 Resource Server; роли ADMIN и MEMBER; правило «задачу меняет только участник проекта».</p>\n  <div class=\"box ex\"><h4>Готово, когда</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"p4-1\"><span>Вход и выход работают, токен обновляется сам.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p4-2\"><span>Права проверяются на сервере, тесты на 401 и 403.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p4-3\"><span>В CI: Dependabot, Trivy, OWASP Dependency-Check.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p4-4\"><span>В README раздел Security: какие пункты OWASP Top 10 закрыты и как.</span></label></li>\n  </ul></div>\n\n  <h3 id=\"p5\"><span class=\"sn\">9.5</span>Проект 5 — taskhub в Kubernetes</h3>\n  <p>Dockerfile, Helm-чарт, развёртывание в kind, конвейер GitHub Actions, мониторинг, Terraform для AWS.</p>\n  <div class=\"box ex\"><h4>Готово, когда</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"p5-1\"><span>Конвейер: build → test → scan → push в GHCR → helm upgrade.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p5-2\"><span>Probes, лимиты ресурсов и HPA настроены.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p5-3\"><span>Prometheus и Grafana-дашборд; скриншот в README.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"p5-4\"><span>Terraform-модуль для AWS (ECR + EKS или ECS + RDS); после демонстрации — <code>terraform destroy</code>.</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"ch10\" data-ch=\"10\" data-title=\"Финальный проект APIForge\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 10</div>\n    <h2>Финальный проект: APIForge</h2>\n    <p class=\"ch-meta\"><span>8–10 недель</span><span>Платформа API-продуктов</span></p>\n  </header>\n  <p>Небольшая версия того, чем занимается команда API ART в Swisscom: внутренние команды публикуют свои API, потребители подписываются, получают доступ и видят статистику использования. На собеседовании этот проект легко связать с их работой: API Products, IAM, EAI.</p>\n\n  <h3 id=\"fp-features\"><span class=\"sn\">10.1</span>Возможности</h3>\n  <ol>\n    <li><b>Каталог API:</b> загрузка OpenAPI-спецификации, версии, статусы draft / published / deprecated, документация в Swagger UI.</li>\n    <li><b>Подписки:</b> потребитель запрашивает доступ, владелец одобряет, выдаются client credentials в Keycloak.</li>\n    <li><b>Шлюз:</b> Spring Cloud Gateway проверяет токен, применяет rate limit (Redis) и проксирует запрос.</li>\n    <li><b>Учёт использования:</b> шлюз пишет события в Kafka, usage-service считает статистику, портал рисует графики.</li>\n    <li><b>Портал на Angular:</b> роли Provider, Consumer, Admin; дашборды, поиск по каталогу.</li>\n    <li><b>Уведомления:</b> письмо или webhook, когда API помечен deprecated.</li>\n  </ol>\n\n  <h3 id=\"fp-arch\"><span class=\"sn\">10.2</span>Архитектура</h3>\n<pre class=\"tree\">Angular portal ──► api-gateway (Spring Cloud Gateway: JWT, rate limit)\n                      ├─► catalog-service       (PostgreSQL) ── REST\n                      ├─► subscription-service  (PostgreSQL) ── REST + Keycloak Admin API\n                      ├─► usage-service         (PostgreSQL / TimescaleDB)\n                      └─► demo-backends         (2–3 мок-API)\napi-gateway ──события──► Kafka ──► usage-service\n                              └──► notification-service\nKeycloak (IAM) · Prometheus + Grafana · OpenTelemetry → Jaeger или Tempo</pre>\n\n  <h3 id=\"fp-repo\"><span class=\"sn\">10.3</span>Структура репозитория</h3>\n<pre class=\"tree\">apiforge/\n ├─ services/{gateway,catalog,subscription,usage,notification}/\n ├─ portal/                     # Angular\n ├─ infra/helm/                 # umbrella-чарт\n ├─ infra/terraform/aws/\n ├─ docs/adr/                   # Architecture Decision Records\n ├─ docs/architecture.md        # C4-диаграммы\n ├─ docker-compose.yml          # вся система одной командой\n └─ .github/workflows/</pre>\n\n  <h3 id=\"fp-plan\"><span class=\"sn\">10.4</span>Этапы по неделям</h3>\n  <div class=\"box ex\"><h4>План</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"fp-w1\"><span><b>Неделя 1.</b> Требования, C4-диаграммы, первые ADR, каркас всех сервисов, CI.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w2\"><span><b>Недели 2–3.</b> catalog-service и портал: каталог, загрузка OpenAPI.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w4\"><span><b>Неделя 4.</b> Keycloak, subscription-service, выдача доступа.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w5\"><span><b>Неделя 5.</b> Шлюз: JWT, rate limit, маршруты.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w6\"><span><b>Неделя 6.</b> Kafka, usage-service, графики в портале.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w7\"><span><b>Неделя 7.</b> Resilience4j, Outbox, контрактные тесты, трассировка.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w8\"><span><b>Неделя 8.</b> Helm, развёртывание в kind и AWS, дашборды Grafana.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-w9\"><span><b>Недели 9–10.</b> Нагрузочный тест (k6 или Gatling), безопасность, документация, видео-демо на 3 минуты.</span></label></li>\n  </ul></div>\n\n  <h3 id=\"fp-done\"><span class=\"sn\">10.5</span>Критерии готовности</h3>\n  <div class=\"box skills\"><h4>Для портфолио</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"fp-d1\"><span><code>docker compose up</code> поднимает всю систему с демо-пользователями.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-d2\"><span>Тесты на трёх уровнях (unit, integration, contract) и e2e портала; CI зелёный.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-d3\"><span>README: архитектура, ADR, скриншоты, видео, раздел «Trade-offs &amp; what I'd do next».</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"fp-d4\"><span>Результат нагрузочного теста: «шлюз держит N rps при p95 &lt; X мс».</span></label></li>\n  </ul></div>\n  <ul class=\"res\">\n    <li><span class=\"tag\">Доки</span><a href=\"https://c4model.com/\" target=\"_blank\" rel=\"noopener\">C4 model</a><span class=\"note\">Как рисовать архитектуру на 4 уровнях детализации.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://adr.github.io/\" target=\"_blank\" rel=\"noopener\">Architecture Decision Records</a><span class=\"note\">Шаблоны и примеры ADR.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://grafana.com/docs/k6/latest/\" target=\"_blank\" rel=\"noopener\">Grafana k6</a><span class=\"note\">Нагрузочные тесты на JavaScript.</span></li>\n  </ul>\n  <div class=\"box note\"><p>Потом пригодится и вне собеседования: шлюз с лимитами и учётом использования подходит для своих API или pet-SaaS.</p></div>\n</section>\n\n<section class=\"ch\" id=\"ch11\" data-ch=\"11\" data-title=\"Финальный проект SlotWise\">\n  <header class=\"ch-head\">\n    <div class=\"ch-num\">Глава 11</div>\n    <h2>Второй финальный проект: SlotWise — онлайн-запись к мастерам</h2>\n    <p class=\"ch-meta\"><span>8–10 недель</span><span>Полный цикл: от разговора с пользователями до запуска</span></p>\n  </header>\n  <div class=\"goals\"><h4>После этой главы вы будете уметь</h4><ul>\n    <li>Превращать проблему реальных людей в требования, макеты и план.</li>\n    <li>Проектировать API по контракту и генерировать по нему клиент.</li>\n    <li>Решать «взрослые» задачи: одновременные записи, часовые пояса, напоминания без дублей.</li>\n    <li>Выпускать приложение в продакшен с HTTPS, бэкапами и мониторингом.</li>\n    <li>Запускать продукт для настоящих пользователей и улучшать его по их отзывам.</li>\n  </ul></div>\n  <p>Парикмахеры, репетиторы, массажисты, фотографы часто записывают клиентов в мессенджерах и блокноте: путаница, двойные записи, забытые визиты. SlotWise даёт мастеру ссылку, по которой клиент сам выбирает свободное время, а за день до визита получает напоминание. Проект не связан с вакансией, но использует тот же стек: Java, Spring Boot, PostgreSQL, Angular, Keycloak, Kafka, Docker, Kubernetes, CI/CD. И им смогут пользоваться реальные люди.</p>\n\n  <h3 id=\"ch11-terms\"><span class=\"sn\">11.1</span>Ключевые понятия</h3>\n  <dl class=\"terms\">\n    <dt>MVP</dt><dd>Минимальная версия продукта, которая уже решает главную проблему и позволяет проверить, нужен ли он людям.</dd>\n    <dt>User story</dt><dd>Требование глазами пользователя: «Как мастер, я хочу видеть записи на неделю, чтобы планировать день».</dd>\n    <dt>Критерии приёмки</dt><dd>Проверяемые условия, при которых история считается сделанной.</dd>\n    <dt>Contract-first</dt><dd>Сначала пишется спецификация API (OpenAPI), затем по ней код сервера и клиента.</dd>\n    <dt>Exclusion constraint</dt><dd>Ограничение PostgreSQL: строки не могут «пересекаться» по заданному правилу, например по времени записи к одному мастеру.</dd>\n    <dt>tstzrange</dt><dd>Тип PostgreSQL «интервал времени с часовым поясом»; оператор <code>&amp;&amp;</code> проверяет пересечение.</dd>\n    <dt>SKIP LOCKED</dt><dd>Режим выборки, при котором строки, заблокированные другой транзакцией, пропускаются. Основа очередей задач в базе.</dd>\n    <dt>PWA</dt><dd>Веб-приложение, которое устанавливается на телефон и работает с кэшем без сети благодаря service worker.</dd>\n    <dt>Staging</dt><dd>Копия продакшена для проверки перед выпуском.</dd>\n  </dl>\n\n  <h3 id=\"ch11-arch\"><span class=\"sn\">11.2</span>Архитектура</h3>\n<pre class=\"tree\">Angular PWA: страница мастера для клиентов · кабинет мастера\n   └─► Spring Boot (модульный монолит)            ← Keycloak (MASTER, ADMIN)\n         ├─ schedule   — услуги, рабочие часы, отпуск\n         ├─ booking    — записи, слоты, защита от двойной записи\n         └─ outbox ──► Kafka (booking.created / booking.cancelled)\n                          └─► notification-service ──► email · Telegram\nPostgreSQL · Prometheus + Grafana · CI/CD → Kubernetes (k3s или EKS)</pre>\n  <div class=\"box note\"><p>Начинаем с модульного монолита и выделяем в отдельный сервис только уведомления: у них другой ритм нагрузки и внешние зависимости. Так проект показывает и микросервисы, и умение не дробить систему без причины.</p></div>\n<pre class=\"tree\">slotwise/\n ├─ backend/                    # Spring Boot: модули schedule, booking, outbox\n ├─ notification-service/       # Spring Boot + Kafka\n ├─ web/                        # Angular PWA\n ├─ api/openapi.yaml            # контракт — источник правды\n ├─ infra/helm/ · infra/terraform/\n ├─ docs/adr/ · docs/user-stories.md · docs/wireframes/\n ├─ load/                       # сценарии k6\n └─ docker-compose.yml          # всё локально: Postgres, Kafka, Keycloak, Mailpit</pre>\n\n  <aside class=\"box fact\"><h4>Интересный факт</h4><p>Время — один из главных источников ошибок в программах записи. В Латвии в последнее воскресенье марта часы в 03:00 переводят на 04:00, и времени 03:30 в этот день просто не существует. А в последнее воскресенье октября час с 03:00 до 04:00 повторяется дважды. Поэтому время записи хранят в UTC, а в местное переводят только для показа.</p></aside>\n\n  <ul class=\"res\">\n    <li><span class=\"tag\">Сайт</span><a href=\"https://excalidraw.com/\" target=\"_blank\" rel=\"noopener\">Excalidraw</a><span class=\"note\">Бесплатные наброски экранов и схем прямо в браузере.</span></li>\n    <li><span class=\"tag\">Сайт</span><a href=\"https://penpot.app/\" target=\"_blank\" rel=\"noopener\">Penpot</a><span class=\"note\">Бесплатный дизайн-инструмент с открытым кодом для макетов.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://openapi-generator.tech/\" target=\"_blank\" rel=\"noopener\">OpenAPI Generator</a><span class=\"note\">Генерация клиента для Angular (typescript-angular) из спецификации.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://www.postgresql.org/docs/current/rangetypes.html\" target=\"_blank\" rel=\"noopener\">PostgreSQL — Range Types</a><span class=\"note\">Интервалы времени и ограничения-исключения для них.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://angular.dev/ecosystem/service-workers\" target=\"_blank\" rel=\"noopener\">Angular — Service Workers и PWA</a><span class=\"note\">Как сделать приложение устанавливаемым и работающим без сети.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://core.telegram.org/bots/api\" target=\"_blank\" rel=\"noopener\">Telegram Bot API</a><span class=\"note\">Отправка напоминаний в Telegram.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://mailpit.axllent.org/\" target=\"_blank\" rel=\"noopener\">Mailpit</a><span class=\"note\">Локальный почтовый сервер для проверки писем без настоящей рассылки.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://docs.k3s.io/\" target=\"_blank\" rel=\"noopener\">k3s</a><span class=\"note\">Лёгкий Kubernetes для одного недорогого сервера.</span></li>\n    <li><span class=\"tag\">Доки</span><a href=\"https://cert-manager.io/docs/\" target=\"_blank\" rel=\"noopener\">cert-manager</a><span class=\"note\">Бесплатные HTTPS-сертификаты Let's Encrypt в Kubernetes автоматически.</span></li>\n  </ul>\n\n  <h3 id=\"ch11-s0\"><span class=\"sn\">11.3</span>Этап 0. Идея и разговоры с людьми</h3>\n  <p class=\"ch-meta\"><span>1 неделя</span><span>Найти реальную боль до того, как писать код.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-0a\"><span>Поговорить с 3–5 мастерами (парикмахер, репетитор, массажист, фотограф): как они сейчас записывают клиентов, что раздражает.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-0b\"><span>Записать 3 главные проблемы их словами, например: «клиенты забывают прийти», «переписка в трёх мессенджерах».</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-0c\"><span>Сформулировать MVP одной фразой и список того, чего в MVP точно не будет (оплата, мобильное приложение, отзывы).</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s1\"><span class=\"sn\">11.4</span>Этап 1. Требования и дизайн</h3>\n  <p class=\"ch-meta\"><span>1 неделя</span><span>Описать, что строим, так, чтобы это можно было проверить.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-1a\"><span>10–15 user stories в формате «Как &lt;роль&gt;, я хочу &lt;действие&gt;, чтобы &lt;польза&gt;» с критериями приёмки.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-1b\"><span>Черновые макеты экранов в Excalidraw или Penpot: страница мастера для клиента, выбор времени, кабинет мастера с календарём.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-1c\"><span>ER-диаграмма: мастер, услуга, рабочие часы, исключения (отпуск), клиент, запись.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-1d\"><span>ADR: начать с модульного монолита, notification-service выделить позже.</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s2\"><span class=\"sn\">11.5</span>Этап 2. Контракт API</h3>\n  <p class=\"ch-meta\"><span>3–4 дня</span><span>Сначала договор, потом код (contract-first).</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-2a\"><span>OpenAPI-спецификация всех эндпоинтов: услуги, свободные слоты, запись, отмена, кабинет мастера.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-2b\"><span>Сгенерировать из спецификации TypeScript-клиент для Angular (openapi-generator).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-2c\"><span>Описать коды ошибок: 409 — время уже занято, 422 — время вне рабочих часов.</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s3\"><span class=\"sn\">11.6</span>Этап 3. Backend</h3>\n  <p class=\"ch-meta\"><span>2–3 недели</span><span>Основная логика и надёжность записи.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-3a\"><span>Модули schedule и booking в Spring Boot, миграции Flyway, защита от двойной записи на уровне базы (задача 11.1).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-3b\"><span>Расчёт свободных слотов с учётом часового пояса и перехода на летнее время (задача 11.2).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-3c\"><span>Keycloak: роли MASTER и ADMIN; клиент записывается без регистрации, по ссылке подтверждения.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-3d\"><span>События booking.created и booking.cancelled в Kafka через Outbox; notification-service отправляет письмо (локально — Mailpit) и сообщение в Telegram.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-3e\"><span>Напоминание за 24 часа задачей по расписанию без дублей при нескольких экземплярах (задача 11.3).</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s4\"><span class=\"sn\">11.7</span>Этап 4. Frontend</h3>\n  <p class=\"ch-meta\"><span>2 недели</span><span>Два сценария: клиент записывается, мастер управляет днём.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-4a\"><span>Публичная страница мастера по ссылке /m/имя: услуги, выбор дня, свободные слоты, форма записи.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-4b\"><span>Кабинет мастера: календарь на неделю, рабочие часы, отпуск, отмена записи.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-4c\"><span>PWA: приложение ставится на телефон мастера, кабинет открывается без интернета (последние данные из кэша).</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-4d\"><span>Удобно на телефоне: проверено на ширине 360 px; доступность — фокус, подписи полей, контраст.</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s5\"><span class=\"sn\">11.8</span>Этап 5. Качество</h3>\n  <p class=\"ch-meta\"><span>1 неделя</span><span>Доказать, что всё работает, а не надеяться.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-5a\"><span>Unit-тесты расчёта слотов, включая день перехода на летнее время.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-5b\"><span>Интеграционные тесты на Testcontainers: две одновременные записи на одно время — проходит ровно одна.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-5c\"><span>E2E на Playwright: клиент записался → мастер видит запись → клиент отменил.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-5d\"><span>Нагрузочный тест k6: 200 клиентов одновременно бьются за 10 слотов, дублей 0.</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s6\"><span class=\"sn\">11.9</span>Этап 6. Инфраструктура и продакшен</h3>\n  <p class=\"ch-meta\"><span>1–2 недели</span><span>Настоящий адрес в интернете, HTTPS, бэкапы.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-6a\"><span>Docker-образы и Helm-чарт; кластер k3s на недорогом сервере или EKS в AWS.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-6b\"><span>CI/CD: тесты → сканирование → образ → развёртывание на staging → ручное подтверждение → production.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-6c\"><span>Домен и HTTPS через cert-manager и Let's Encrypt.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-6d\"><span>Ежедневный бэкап PostgreSQL и проверенное восстановление из него.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-6e\"><span>Grafana: записи за день, ошибки, время ответа; оповещение, если сервис недоступен.</span></label></li>\n  </ul>\n  <h3 id=\"ch11-s7\"><span class=\"sn\">11.10</span>Этап 7. Запуск и развитие</h3>\n  <p class=\"ch-meta\"><span>2+ недели</span><span>Самое ценное для портфолио — реальные пользователи.</span></p>\n  <ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-7a\"><span>Подключить первого настоящего мастера и провести с ним неделю.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-7b\"><span>Собрать обратную связь и сделать 2 итерации улучшений по ней.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-7c\"><span>Измерить результат, например «доля неявок снизилась с X % до Y % после напоминаний».</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-7d\"><span>README с архитектурой, ADR, скриншотами и видео; короткая статья о проекте в LinkedIn или блоге.</span></label></li>\n  </ul>\n\n  <h3 id=\"ch11-tasks\"><span class=\"sn\">11.11</span>Задачи с решениями</h3>\n  <div class=\"box task\"><h4>Задача 11.1. Никаких двойных записей</h4>\n    <p>Два клиента одновременно нажимают «Записаться» на 15:00 к одному мастеру. Проверка «свободно ли» в Java не спасает: обе транзакции видят слот свободным. Сделайте так, чтобы база сама не пустила пересекающиеся записи.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>PostgreSQL + Spring</figcaption><pre><code>CREATE EXTENSION IF NOT EXISTS btree_gist;\n\nCREATE TABLE booking (\n  id         BIGSERIAL PRIMARY KEY,\n  master_id  BIGINT NOT NULL REFERENCES master(id),\n  client     TEXT   NOT NULL,\n  slot       TSTZRANGE NOT NULL,          -- [начало, конец)\n  status     TEXT NOT NULL DEFAULT 'ACTIVE',\n  EXCLUDE USING gist (master_id WITH =, slot WITH &amp;&amp;)\n    WHERE (status = 'ACTIVE')\n);\n\n-- в Spring: нарушение ограничения → 409 Conflict\n@ExceptionHandler(DataIntegrityViolationException.class)\nProblemDetail taken() {\n    return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, \"Это время уже занято\");\n}</code></pre></figure>\n      <p>Ограничение запрещает две активные записи одного мастера с пересекающимися интервалами (<code>&amp;&amp;</code>). Расширение <code>btree_gist</code> нужно, чтобы в одном GiST-индексе сравнивать и число (<code>=</code>), и интервал. Отменённые записи (<code>status</code> не ACTIVE) не мешают занять время снова. Гонка решена там, где она возникает, — в базе.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"f2-t1\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 11.2. Свободные слоты с учётом часового пояса</h4>\n    <p>Напишите метод, который для дня, часов работы и длительности услуги вернёт свободные слоты мастера в Риге, исключая занятые интервалы.</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java</figcaption><pre><code>record Busy(Instant start, Instant end) {}\n\nstatic List&lt;ZonedDateTime&gt; freeSlots(LocalDate day, LocalTime open, LocalTime close,\n                                     Duration len, List&lt;Busy&gt; busy) {\n    ZoneId riga = ZoneId.of(\"Europe/Riga\");\n    ZonedDateTime end = day.atTime(close).atZone(riga);\n    List&lt;ZonedDateTime&gt; out = new ArrayList&lt;&gt;();\n    for (ZonedDateTime t = day.atTime(open).atZone(riga); !t.plus(len).isAfter(end); t = t.plus(len)) {\n        Instant s = t.toInstant(), e = t.plus(len).toInstant();\n        boolean taken = busy.stream().anyMatch(b -&gt; b.start().isBefore(e) &amp;&amp; s.isBefore(b.end()));\n        if (!taken) out.add(t);\n    }\n    return out;\n}</code></pre></figure>\n      <p>Интервалы [s, e) и [b.start, b.end) пересекаются, если каждый начинается раньше конца другого. Сравнение идёт по <code>Instant</code> (UTC), поэтому переход на летнее время не ломает расчёт: <code>atZone</code> сам сдвигает несуществующее время 03:30 на 04:30. Тест обязательно для 29 марта 2026 года — дня перехода.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"f2-t2\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n  <div class=\"box task\"><h4>Задача 11.3. Напоминания без дублей</h4>\n    <p>Приложение работает в двух экземплярах, и в каждом раз в минуту запускается задача «отправить напоминания о записях через 24 часа». Как сделать, чтобы клиент не получил два одинаковых напоминания?</p>\n    <details class=\"sol\"><summary>Показать решение</summary>\n      <figure class=\"code\"><figcaption>Java, PostgreSQL</figcaption><pre><code>@Scheduled(fixedDelay = 60_000)\n@Transactional\npublic void remind() {\n    List&lt;Long&gt; ids = jdbc.queryForList(\"\"\"\n        SELECT id FROM booking\n        WHERE status = 'ACTIVE' AND reminded_at IS NULL\n          AND lower(slot) BETWEEN now() + interval '23 hours' AND now() + interval '24 hours'\n        ORDER BY lower(slot)\n        LIMIT 100\n        FOR UPDATE SKIP LOCKED\n        \"\"\", Long.class);\n    for (Long id : ids) {\n        outbox.save(OutboxEvent.reminder(id));   // отправит notification-service\n        jdbc.update(\"UPDATE booking SET reminded_at = now() WHERE id = ?\", id);\n    }\n}</code></pre></figure>\n      <p><code>FOR UPDATE</code> блокирует выбранные строки до конца транзакции, а <code>SKIP LOCKED</code> заставляет второй экземпляр пропустить их и взять другие. Отметка <code>reminded_at</code> и событие в outbox сохраняются в той же транзакции, поэтому повторного напоминания не будет даже после перезапуска.</p>\n    </details>\n    <ul class=\"todo\"><li><label><input type=\"checkbox\" data-k=\"f2-t3\"><span>Решено самостоятельно, прежде чем открыть решение</span></label></li></ul>\n  </div>\n\n  <h3 id=\"ch11-test\"><span class=\"sn\">11.12</span>Тест для самопроверки</h3>\n  <div class=\"quiz\" data-quiz=\"11\"></div>\n\n  <div class=\"box skills\"><h4>Чек-лист навыков</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"f2-s1\"><span>Провожу интервью с пользователями и превращаю их проблемы в user stories.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-s2\"><span>Разрабатываю API contract-first и генерирую по нему клиент.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-s3\"><span>Защищаю данные от гонок на уровне базы.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-s4\"><span>Правильно работаю со временем и часовыми поясами.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-s5\"><span>Выпускаю приложение в продакшен с HTTPS, бэкапами и мониторингом.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"f2-s6\"><span>SlotWise работает у реального мастера, есть метрики и отзывы.</span></label></li>\n  </ul></div>\n</section>\n\n<!-- ============ ПРИЛОЖЕНИЯ ============ -->\n<div class=\"part-h\" data-part=\"Приложения\">Приложения</div>\n\n<section class=\"ch\" id=\"appA\" data-ch=\"21\" data-title=\"А. Шаблон README\">\n  <header class=\"ch-head\"><div class=\"ch-num\">Приложение А</div><h2>Шаблон README проекта</h2></header>\n  <figure class=\"code\"><figcaption>README.md</figcaption>\n<pre><code># Project name\n\nOne sentence: what problem it solves and for whom.\n\n![CI](badge-url) ![Coverage](badge-url)\n\n## Features\n- …\n\n## Tech stack\nJava 21 · Spring Boot · PostgreSQL · Angular · Docker · Kubernetes\n\n## Architecture\n(diagram + 3–5 sentences, links to docs/adr/)\n\n## Run locally\n    docker compose up\n    open http://localhost:8080/swagger-ui.html\n\n## API docs\nLink to Swagger UI / OpenAPI file.\n\n## Screenshots\n\n## What I learned\n- …\n\n## Trade-offs &amp; what I'd do next\n- …</code></pre></figure>\n</section>\n\n<section class=\"ch\" id=\"appB\" data-ch=\"22\" data-title=\"Б. Подготовка к собеседованию\">\n  <header class=\"ch-head\"><div class=\"ch-num\">Приложение Б</div><h2>Подготовка к собеседованию</h2></header>\n  <div class=\"box skills\"><h4>Чек-лист</h4><ul class=\"todo\">\n    <li><label><input type=\"checkbox\" data-k=\"b-1\"><span>Резюме на английском, одна страница, ссылки на GitHub, APIForge и SlotWise.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-2\"><span>Профиль GitHub: закреплены 4–6 лучших репозиториев, у каждого README.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-3\"><span>Рассказ о себе на 2 минуты на английском.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-4\"><span>3 истории по схеме STAR: трудная задача, конфликт, ошибка и что из неё вынесено.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-5\"><span>Повторены все «Проверь себя» из глав 1–7.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-6\"><span>Пробное собеседование: system design APIForge за 30 минут у доски.</span></label></li>\n    <li><label><input type=\"checkbox\" data-k=\"b-7\"><span>Сверены требования оригинальной вакансии с главами этого учебника.</span></label></li>\n  </ul></div>\n</section>\n\n<section class=\"ch\" id=\"appC\" data-ch=\"23\" data-title=\"В. Требования вакансии\">\n  <header class=\"ch-head\"><div class=\"ch-num\">Приложение В</div><h2>Требования вакансии и источники</h2></header>\n  <div class=\"tbl\"><table>\n    <thead><tr><th>Требование</th><th>Глава</th></tr></thead>\n    <tbody>\n      <tr><td>Java 17+, Spring Boot</td><td><a href=\"#ch1\">1</a>, <a href=\"#ch3\">3</a></td></tr>\n      <tr><td>Angular (TypeScript, RxJS)</td><td><a href=\"#ch4\">4</a></td></tr>\n      <tr><td>REST API, микросервисы, базы данных</td><td><a href=\"#ch2\">2</a>, <a href=\"#ch3\">3</a>, <a href=\"#ch7\">7</a></td></tr>\n      <tr><td>Cloud-native, AWS, Kubernetes, CI/CD</td><td><a href=\"#ch6\">6</a></td></tr>\n      <tr><td>Secure development</td><td><a href=\"#ch5\">5</a></td></tr>\n      <tr><td>Agile, команда API ART (SAFe)</td><td><a href=\"#ch8\">8</a></td></tr>\n      <tr><td>Плюсом: IAM, ForgeRock</td><td><a href=\"#ch5\">5</a></td></tr>\n      <tr><td>Хороший английский</td><td><a href=\"#ch8\">8</a>, <a href=\"#appB\">Б</a></td></tr>\n    </tbody>\n  </table></div>\n  <p>Требования собраны из объявлений Swisscom DevOps Center Riga:</p>\n  <ul>\n    <li><a href=\"https://www.cvmarket.lv/full-stack-developer-javaangular-riga-swisscom-devops-center-latvia-sia-1660299\" target=\"_blank\" rel=\"noopener\">CV Market — Full Stack Developer (Java/Angular)</a> — оригинал вакансии</li>\n    <li><a href=\"https://freehire.me/jobs/full-stack-developer-java-angular-swisscom-lv-mffoet2i\" target=\"_blank\" rel=\"noopener\">Freehire — Full Stack Developer (Java/Angular), Swisscom</a></li>\n    <li><a href=\"https://sdcriga.swisscom.ch/homepage\" target=\"_blank\" rel=\"noopener\">SDC Riga — Open positions</a></li>\n    <li><a href=\"https://lv.linkedin.com/jobs/view/software-developer-at-swisscom-devops-center-riga-3653987007\" target=\"_blank\" rel=\"noopener\">LinkedIn — Software Developer, Swisscom DevOps Center Riga</a></li>\n  </ul>\n  <div class=\"box note\"><p>Все материалы бесплатны и в открытом доступе: официальная документация, открытые книги, бесплатные курсы и крупные каналы. Если ссылка перестала открываться, ресурс легко найти по названию.</p></div>\n</section>\n\n</div>\n</main>\n</div>\n\n<button class=\"btn top\" id=\"up\" aria-label=\"Наверх\" hidden>↑</button>\n\n<script>\n(() => {\n  const $ = s => document.querySelector(s), $$ = s => [...document.querySelectorAll(s)];\n  const boxes = $$('input[type=checkbox][data-k]');\n  const chapters = $$('section[data-ch]');\n  const KEY = 'study-progress';\n  let state = {};\n\n  // ---------- оглавление ----------\n  const toc = $('#toc');\n  let html = '';\n  for (const el of document.querySelectorAll('.part-h, section[data-ch]')) {\n    if (el.classList.contains('part-h')) { html += `<li class=\"part\">${el.dataset.part}</li>`; continue; }\n    const subs = [...el.querySelectorAll('h3[id]')].map(h => `<li><a href=\"#${h.id}\" data-sub=\"${h.id}\">${(h.querySelector('.sn') ? h.textContent.slice(h.querySelector('.sn').textContent.length) : h.textContent).trim()}</a></li>`).join('');\n    const n = el.id === 'intro' ? '' : (el.querySelector('.ch-num')?.textContent.replace(/^(Глава|Приложение)\\s*/, '') || '');\n    html += `<li data-for=\"${el.id}\"><a href=\"#${el.id}\"><span class=\"n\">${n}</span><span class=\"t\">${el.dataset.title}</span><span class=\"c\" data-c=\"${el.id}\"></span></a>${subs ? `<ul>${subs}</ul>` : ''}</li>`;\n  }\n  toc.innerHTML = html;\n\n  // ---------- «предыдущая / следующая» ----------\n  chapters.forEach((ch, i) => {\n    const prev = chapters[i - 1], next = chapters[i + 1];\n    if (!prev && !next) return;\n    const nav = document.createElement('nav'); nav.className = 'pager';\n    nav.innerHTML = (prev ? `<a href=\"#${prev.id}\" class=\"prev\"><small>← Назад</small>${prev.dataset.title}</a>` : '') +\n                    (next ? `<a href=\"#${next.id}\" class=\"next\"><small>Дальше →</small>${next.dataset.title}</a>` : '');\n    ch.appendChild(nav);\n  });\n\n  // ---------- прогресс ----------\n  function paint() {\n    let done = 0;\n    for (const b of boxes) { b.checked = !!state[b.dataset.k]; if (b.checked) done++; }\n    const pct = boxes.length ? Math.round(done * 100 / boxes.length) : 0;\n    $('#meter').style.width = pct + '%';\n    $('#pct').textContent = `${pct} % · ${done}/${boxes.length}`;\n    for (const ch of chapters) {\n      const own = ch.querySelectorAll('input[data-k]'), c = toc.querySelector(`[data-c=\"${ch.id}\"]`);\n      if (!c || !own.length) continue;\n      const d = [...own].filter(b => b.checked).length;\n      const qz = state['qz' + ch.dataset.ch];\n      c.textContent = (d === own.length ? '✓' : `${d}/${own.length}`) + (qz ? ` · ${qz}%` : '');\n      c.classList.toggle('full', d === own.length);\n    }\n  }\n  const saveEl = $('#save');\n  const local = { get() { try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch (e) { return {}; } },\n                  set(v) { try { localStorage.setItem(KEY, JSON.stringify(v)); } catch (e) {} } };\n  let timer = 0;\n  function save() {\n    local.set(state);\n    saveEl.textContent = 'Сохраняю…'; saveEl.classList.remove('err');\n    clearTimeout(timer);\n    timer = setTimeout(async () => {\n      try {\n        const r = await fetch('/api/study', { method: 'POST', credentials: 'same-origin', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ state }) });\n        if (!r.ok) throw new Error(r.status);\n        saveEl.textContent = 'Сохранено';\n      } catch (e) { saveEl.textContent = 'Не сохранилось — проверьте вход на сайт'; saveEl.classList.add('err'); }\n    }, 600);\n  }\n  document.addEventListener('change', e => {\n    const b = e.target.closest('input[data-k]'); if (!b) return;\n    if (b.checked) state[b.dataset.k] = 1; else delete state[b.dataset.k];\n    paint(); save();\n  });\n  state = local.get(); paint();\n  fetch('/api/study', { credentials: 'same-origin', cache: 'no-store' }).then(r => r.ok ? r.json() : null).then(d => {\n    if (d && d.state && typeof d.state === 'object') { state = d.state; local.set(state); paint(); quizBest(); saveEl.textContent = 'Сохранено на сайте'; }\n  }).catch(() => {});\n\n\n  // ---------- тесты: бесконечные попытки, результат в %, разбор; лучший результат — state['qzN'] ----------\n  const QUIZ = {\"12\": [{\"q\": \"Что возвращает <code>useState(0)</code>?\", \"a\": [\"Число 0\", \"Массив: текущее значение и функцию для его изменения\", \"Объект с методами get и set\", \"Promise\"], \"c\": 1, \"why\": \"Обычно его сразу разбирают: <code>const [count, setCount] = useState(0)</code>.\"}, {\"q\": \"Зачем элементам списка нужен <code>key</code>?\", \"a\": [\"Для стилей\", \"Чтобы React узнавал элементы между отрисовками\", \"Для сортировки\", \"Для доступности\"], \"c\": 1, \"why\": \"Стабильный key (id из данных) позволяет обновить только изменённые элементы и не перепутать их состояние.\"}, {\"q\": \"Когда выполняется <code>useEffect(fn, [])</code>?\", \"a\": [\"Перед каждой отрисовкой\", \"Один раз после первой отрисовки компонента\", \"При каждом изменении любого state\", \"Никогда\"], \"c\": 1, \"why\": \"Пустой массив зависимостей — «после монтирования». В режиме разработки со StrictMode React специально запускает эффект дважды, чтобы найти ошибки очистки.\"}, {\"q\": \"Можно ли вызывать хук внутри <code>if</code>?\", \"a\": [\"Да, если условие редко меняется\", \"Нет: хуки вызываются в одном и том же порядке на верхнем уровне компонента\", \"Только useEffect\", \"Только в классовых компонентах\"], \"c\": 1, \"why\": \"React сопоставляет состояние с хуками по порядку вызова. Условный хук этот порядок ломает.\"}, {\"q\": \"<code>count</code> равен 0. В обработчике трижды вызвали <code>setCount(count + 1)</code>. Каким станет count?\", \"a\": [\"3\", \"1\", \"0\", \"Будет ошибка\"], \"c\": 1, \"why\": \"Все три вызова видят count = 0 из текущей отрисовки. Чтобы получить 3, используйте <code>setCount(c =&gt; c + 1)</code>.\"}, {\"q\": \"Что такое props?\", \"a\": [\"Внутреннее состояние компонента\", \"Входные данные от родителя, доступные только для чтения\", \"Глобальные переменные\", \"CSS-свойства\"], \"c\": 1, \"why\": \"Менять props внутри компонента нельзя: данные текут сверху вниз, а изменения идут через функции-колбэки от родителя.\"}, {\"q\": \"Для чего TanStack Query?\", \"a\": [\"Для стилей\", \"Для серверного состояния: загрузка, кэш, повтор, отмена, обновление\", \"Для маршрутов\", \"Для анимаций\"], \"c\": 1, \"why\": \"Он избавляет от ручного useEffect + useState для каждого запроса и даёт кэш по ключу запроса.\"}, {\"q\": \"Чем по сути React отличается от Angular?\", \"a\": [\"React быстрее всегда\", \"React — библиотека интерфейса, маршруты, формы и HTTP берут отдельными библиотеками; Angular — фреймворк, где всё встроено\", \"Angular не поддерживает TypeScript\", \"React работает только на сервере\"], \"c\": 1, \"why\": \"Поэтому в React-проектах больше выбора и решений «как устроить», а в Angular — больше единообразия между проектами.\"}], \"11\": [{\"q\": \"Что такое MVP?\", \"a\": [\"Первая версия со всеми задуманными функциями\", \"Минимальная версия, которая решает главную проблему и проверяет, нужен ли продукт\", \"Прототип только из макетов\", \"Версия для инвесторов\"], \"c\": 1, \"why\": \"MVP — способ быстро узнать, решает ли продукт реальную проблему, прежде чем тратить месяцы на функции, которые могут оказаться не нужны.\"}, {\"q\": \"Как надёжнее всего не допустить двух записей на одно время?\", \"a\": [\"Проверить в Java, что слот свободен, и потом сохранить\", \"Ограничение в базе (exclusion constraint) и обработка ошибки\", \"Отключить кнопку на фронтенде после нажатия\", \"Сохранять записи раз в минуту пачкой\"], \"c\": 1, \"why\": \"Проверка в коде и вставка — две операции, между ними успеет вклиниться другой запрос. Ограничение в базе срабатывает атомарно для всех экземпляров приложения.\"}, {\"q\": \"Какой статус HTTP вернуть, если выбранное время уже заняли?\", \"a\": [\"400 Bad Request\", \"404 Not Found\", \"409 Conflict\", \"500 Internal Server Error\"], \"c\": 2, \"why\": \"409 означает конфликт с текущим состоянием ресурса. Клиенту стоит обновить список слотов и выбрать другое время.\"}, {\"q\": \"Как правильно хранить время записи?\", \"a\": [\"В местном времени мастера как текст\", \"В UTC (timestamptz), а переводить в местное только для показа\", \"В миллисекундах без часового пояса, «как на сервере»\", \"В часовом поясе браузера клиента\"], \"c\": 1, \"why\": \"UTC не знает перехода на летнее время и одинаков для всех серверов. Местное время зависит от зоны и правил, которые меняются.\"}, {\"q\": \"Что делает <code>FOR UPDATE SKIP LOCKED</code>?\", \"a\": [\"Удаляет заблокированные строки\", \"Блокирует выбранные строки и пропускает те, что уже заблокированы другой транзакцией\", \"Ждёт, пока все блокировки снимутся\", \"Отключает блокировки\"], \"c\": 1, \"why\": \"Так несколько экземпляров приложения разбирают общую очередь задач, не мешая друг другу и не обрабатывая одно дважды.\"}, {\"q\": \"Какой формат у user story?\", \"a\": [\"«Система должна…»\", \"«Как &lt;роль&gt;, я хочу &lt;действие&gt;, чтобы &lt;польза&gt;»\", \"«Если X, то Y»\", \"Номер задачи и срок\"], \"c\": 1, \"why\": \"Формат напоминает, для кого фича и зачем она. Критерии приёмки делают историю проверяемой.\"}, {\"q\": \"Что значит contract-first?\", \"a\": [\"Сначала подписать договор с заказчиком\", \"Сначала описать API в OpenAPI, затем писать сервер и клиент по спецификации\", \"Сначала написать тесты\", \"Сначала развернуть инфраструктуру\"], \"c\": 1, \"why\": \"Фронтенд и бэкенд могут работать параллельно, клиент генерируется автоматически, а расхождения видны сразу.\"}, {\"q\": \"Что даёт PWA мастеру?\", \"a\": [\"Публикацию в App Store без проверки\", \"Установку на телефон и работу кабинета с кэшем без сети\", \"Бесплатный хостинг\", \"Автоматические push в любой мессенджер\"], \"c\": 1, \"why\": \"Service worker кэширует приложение и данные; иконка на экране телефона открывает кабинет как обычное приложение.\"}], \"1\": [{\"q\": \"Что компилятор автоматически создаёт для <code>record</code>?\", \"a\": [\"Канонический конструктор, методы доступа, equals, hashCode и toString\", \"Только геттеры и сеттеры\", \"Builder и конструктор без параметров\", \"Ничего, всё пишется вручную\"], \"c\": 0, \"why\": \"Record — носитель данных: поля final, а конструктор, методы доступа (<code>name()</code>, не <code>getName()</code>), equals, hashCode и toString генерируются. Сеттеров нет — record неизменяемый.\"}, {\"q\": \"Что вернёт <code>List.of(1, 2, 3).stream().map(x -&gt; x * 2).filter(x -&gt; x &gt; 2).count()</code>?\", \"a\": [\"3\", \"2\", \"1\", \"6\"], \"c\": 1, \"why\": \"После map получаем 2, 4, 6. Фильтр «больше 2» оставляет 4 и 6 — это 2 элемента.\"}, {\"q\": \"Что произойдёт при вызове <code>List.of(1, 2).add(3)</code>?\", \"a\": [\"Список станет [1, 2, 3]\", \"Вернётся false\", \"Будет UnsupportedOperationException\", \"Ошибка компиляции\"], \"c\": 2, \"why\": \"<code>List.of</code> создаёт неизменяемый список. Код компилируется, потому что add есть в интерфейсе List, но во время выполнения бросается UnsupportedOperationException.\"}, {\"q\": \"В какой задаче виртуальные потоки дают наибольший выигрыш?\", \"a\": [\"Вычисление больших простых чисел\", \"Тысячи одновременных HTTP-запросов и запросов к базе\", \"Сортировка массива в памяти\", \"Обработка изображения на одном ядре\"], \"c\": 1, \"why\": \"Виртуальные потоки дёшевы, пока ждут ввода-вывода. Для вычислительных задач они не быстрее обычных: число ядер процессора не меняется.\"}, {\"q\": \"Что означает <code>sealed interface Shape permits Circle, Rect</code>?\", \"a\": [\"Shape нельзя реализовать вообще\", \"Реализовать Shape могут только Circle и Rect\", \"Circle и Rect нельзя наследовать\", \"Shape становится final-классом\"], \"c\": 1, \"why\": \"sealed ограничивает список наследников. Благодаря этому компилятор знает все варианты и проверяет, что <code>switch</code> по Shape исчерпывающий.\"}, {\"q\": \"Чем <code>orElseGet(supplier)</code> отличается от <code>orElse(value)</code> у Optional?\", \"a\": [\"Ничем\", \"orElseGet вычисляет запасное значение только если Optional пуст\", \"orElseGet бросает исключение при пустом Optional\", \"orElse работает только со строками\"], \"c\": 1, \"why\": \"Аргумент <code>orElse</code> вычисляется всегда, даже если значение есть. <code>orElseGet</code> вызывает функцию только при пустом Optional — это важно, если запасное значение дорого получить.\"}, {\"q\": \"Что сравнивает <code>==</code> для двух объектов String?\", \"a\": [\"Содержимое строк\", \"Длину строк\", \"Ссылки — один ли это объект\", \"Хэш-коды\"], \"c\": 2, \"why\": \"<code>==</code> для объектов сравнивает ссылки. Содержимое строк сравнивают через <code>equals</code>.\"}, {\"q\": \"Какая команда Git переносит коммиты ветки поверх другой ветки, переписывая историю?\", \"a\": [\"git merge\", \"git rebase\", \"git cherry\", \"git stash\"], \"c\": 1, \"why\": \"<code>rebase</code> переигрывает коммиты поверх новой базы и создаёт новые коммиты. <code>merge</code> историю не переписывает, а добавляет коммит слияния.\"}], \"2\": [{\"q\": \"Какой запрос вернёт все проекты, даже без задач?\", \"a\": [\"project INNER JOIN task\", \"project LEFT JOIN task\", \"task LEFT JOIN project\", \"project CROSS JOIN task\"], \"c\": 1, \"why\": \"LEFT JOIN сохраняет все строки левой таблицы (project); у проектов без задач поля задачи будут NULL.\"}, {\"q\": \"Есть индекс <code>(project_id, status)</code>. Какой фильтр использует его лучше всего?\", \"a\": [\"WHERE status = ?\", \"WHERE project_id = ? AND status = ?\", \"WHERE title = ?\", \"WHERE created_at &gt; ?\"], \"c\": 1, \"why\": \"Составной B-tree индекс работает по левому префиксу: (project_id) или (project_id, status). Только по status он обычно не помогает.\"}, {\"q\": \"Что означает атомарность (A в ACID)?\", \"a\": [\"Транзакция выполняется быстро\", \"Все изменения транзакции применяются целиком или не применяются вовсе\", \"Данные шифруются\", \"Транзакции идут строго по очереди\"], \"c\": 1, \"why\": \"Атомарность — «всё или ничего». Последовательное выполнение — это про изоляцию, а не атомарность.\"}, {\"q\": \"Чем <code>COUNT(column)</code> отличается от <code>COUNT(*)</code>?\", \"a\": [\"Ничем\", \"COUNT(column) не считает строки, где column равен NULL\", \"COUNT(*) не считает NULL\", \"COUNT(column) работает только с числами\"], \"c\": 1, \"why\": \"COUNT(*) считает все строки, COUNT(column) — только строки с не-NULL значением. Поэтому при LEFT JOIN считают COUNT(t.id).\"}, {\"q\": \"Чем HAVING отличается от WHERE?\", \"a\": [\"Ничем, это синонимы\", \"HAVING фильтрует группы после GROUP BY, WHERE — строки до группировки\", \"WHERE работает только с индексами\", \"HAVING быстрее\"], \"c\": 1, \"why\": \"WHERE отбрасывает строки до группировки, HAVING — готовые группы по агрегатам (например, HAVING COUNT(*) &gt; 5).\"}, {\"q\": \"Что такое проблема N+1?\", \"a\": [\"Ошибка индексации на N+1 строке\", \"Один запрос за списком и ещё по запросу на каждый элемент за связанными данными\", \"Лимит соединений с базой\", \"Переполнение первичного ключа\"], \"c\": 1, \"why\": \"Типичная ловушка JPA с ленивыми связями. Лечится JOIN FETCH, @EntityGraph или batch fetching.\"}, {\"q\": \"Можно ли поменять уже применённую миграцию Flyway V1?\", \"a\": [\"Да, Flyway применит изменения сам\", \"Нет: изменится контрольная сумма и проверка упадёт — нужна новая миграция V2\", \"Да, если перезапустить приложение\", \"Только в PostgreSQL\"], \"c\": 1, \"why\": \"Flyway хранит контрольные суммы применённых миграций. Изменения схемы всегда идут новой версией.\"}, {\"q\": \"Какая стратегия загрузки по умолчанию у <code>@OneToMany</code> в JPA?\", \"a\": [\"EAGER\", \"LAZY\", \"BATCH\", \"Зависит от базы\"], \"c\": 1, \"why\": \"Коллекции (@OneToMany, @ManyToMany) по умолчанию LAZY, а @ManyToOne и @OneToOne — EAGER.\"}], \"3\": [{\"q\": \"Какой статус HTTP возвращают при успешном создании ресурса?\", \"a\": [\"200 OK\", \"201 Created\", \"204 No Content\", \"302 Found\"], \"c\": 1, \"why\": \"201 Created и заголовок Location с адресом нового ресурса.\"}, {\"q\": \"Какой метод HTTP не идемпотентен?\", \"a\": [\"GET\", \"PUT\", \"DELETE\", \"POST\"], \"c\": 3, \"why\": \"Повторный POST обычно создаёт ещё один ресурс. GET, PUT и DELETE при повторе дают тот же результат.\"}, {\"q\": \"Что нужно, чтобы аннотации вроде @NotBlank на DTO проверялись в контроллере?\", \"a\": [\"@Valid перед @RequestBody\", \"@Autowired\", \"@Transactional\", \"Ничего, проверка включена всегда\"], \"c\": 0, \"why\": \"Без @Valid (или @Validated) Spring не запускает Bean Validation для тела запроса.\"}, {\"q\": \"Что поднимает @WebMvcTest?\", \"a\": [\"Весь контекст приложения и базу\", \"Только веб-слой: контроллеры, advice, MockMvc\", \"Только репозитории\", \"Настоящий HTTP-сервер на порту\"], \"c\": 1, \"why\": \"@WebMvcTest — срез веб-слоя. Сервисы подменяются моками, поэтому тест быстрый.\"}, {\"q\": \"Какой способ внедрения зависимостей рекомендуется?\", \"a\": [\"@Autowired на поле\", \"Через конструктор\", \"Через статический метод\", \"Через сеттер всегда\"], \"c\": 1, \"why\": \"Через конструктор: поля final, зависимости видны, класс легко создать в тесте без Spring.\"}, {\"q\": \"Как держать отдельные настройки для production?\", \"a\": [\"Менять application.yml перед каждым деплоем\", \"Профиль: application-prod.yml и spring.profiles.active=prod\", \"Писать настройки в коде\", \"Отдельная ветка Git\"], \"c\": 1, \"why\": \"Профили позволяют один артефакт запускать с разной конфигурацией. Секреты — через переменные окружения.\"}, {\"q\": \"Что делает @RestControllerAdvice?\", \"a\": [\"Ускоряет контроллеры\", \"Обрабатывает исключения всех контроллеров в одном месте\", \"Создаёт REST-клиент\", \"Включает CORS\"], \"c\": 1, \"why\": \"Обработчики @ExceptionHandler в таком классе применяются ко всем контроллерам — так получается единый формат ошибок.\"}, {\"q\": \"Зачем нужен Testcontainers?\", \"a\": [\"Генерировать тестовые данные\", \"Поднимать настоящие PostgreSQL, Kafka и др. в Docker на время тестов\", \"Запускать тесты параллельно\", \"Измерять покрытие\"], \"c\": 1, \"why\": \"Тесты идут против настоящей базы той же версии, что в production, а не против H2, которая ведёт себя иначе.\"}], \"4\": [{\"q\": \"Какой оператор RxJS отменяет предыдущий запрос при новом значении?\", \"a\": [\"mergeMap\", \"concatMap\", \"switchMap\", \"exhaustMap\"], \"c\": 2, \"why\": \"switchMap переключается на новый внутренний поток и отписывается от старого. mergeMap выполняет всё параллельно, concatMap — по очереди, exhaustMap игнорирует новые, пока идёт текущий.\"}, {\"q\": \"Как в Angular создать значение, вычисляемое из других сигналов?\", \"a\": [\"effect()\", \"computed()\", \"signal()\", \"input()\"], \"c\": 1, \"why\": \"computed() пересчитывается автоматически, когда меняются сигналы, которые он читает. effect() — для побочных действий, а не для значений.\"}, {\"q\": \"Зачем в <code>@for</code> указывают <code>track</code>?\", \"a\": [\"Для сортировки\", \"Чтобы Angular узнавал элементы и перерисовывал только изменённые\", \"Для фильтрации\", \"Это необязательное украшение\"], \"c\": 1, \"why\": \"По track Angular сопоставляет элементы между обновлениями. В @for он обязателен.\"}, {\"q\": \"Что произойдёт, если вызвать <code>http.get(url)</code> и не подписаться?\", \"a\": [\"Запрос уйдёт сразу\", \"Запрос не отправится\", \"Будет ошибка\", \"Запрос уйдёт при следующем рендере\"], \"c\": 1, \"why\": \"Observable из HttpClient «холодный»: запрос отправляется только при подписке (subscribe, async pipe, toSignal).\"}, {\"q\": \"Как подключить функциональный interceptor?\", \"a\": [\"@Injectable в providers\", \"provideHttpClient(withInterceptors([fn]))\", \"В angular.json\", \"Через @Component\"], \"c\": 1, \"why\": \"В приложениях на standalone-компонентах interceptors-функции передают в withInterceptors при provideHttpClient.\"}, {\"q\": \"Что делает <code>debounceTime(300)</code>?\", \"a\": [\"Задерживает каждое значение на 300 мс\", \"Пропускает значение, только если после него 300 мс не было новых\", \"Выдаёт не чаще раза в 300 мс первое значение\", \"Ограничивает запрос 300 мс\"], \"c\": 1, \"why\": \"debounce ждёт паузу. «Не чаще раза в N мс» — это throttleTime.\"}, {\"q\": \"Как называется тип <code>string | number</code> в TypeScript?\", \"a\": [\"Intersection\", \"Union\", \"Tuple\", \"Generic\"], \"c\": 1, \"why\": \"Union — «одно из». Intersection (<code>A &amp; B</code>) — «и то и другое одновременно».\"}, {\"q\": \"Чем standalone-компонент отличается от прежних?\", \"a\": [\"Не может иметь шаблон\", \"Не требует NgModule и сам перечисляет импорты\", \"Работает без TypeScript\", \"Не поддерживает DI\"], \"c\": 1, \"why\": \"Standalone-компоненты — стандарт современного Angular: зависимости указываются в поле imports самого компонента.\"}], \"5\": [{\"q\": \"Пользователь вошёл, но у него нет прав на удаление. Какой статус?\", \"a\": [\"400\", \"401\", \"403\", \"404\"], \"c\": 2, \"why\": \"403 Forbidden — личность известна, прав нет. 401 — нет действительной аутентификации.\"}, {\"q\": \"Какой поток OAuth рекомендован для SPA?\", \"a\": [\"Implicit\", \"Password\", \"Authorization Code + PKCE\", \"Client Credentials\"], \"c\": 2, \"why\": \"Implicit и Password больше не рекомендуются. PKCE защищает обмен кода для клиентов, которые не могут хранить секрет.\"}, {\"q\": \"Что OpenID Connect добавляет к OAuth 2.0?\", \"a\": [\"Шифрование трафика\", \"Аутентификацию пользователя: ID token и userinfo\", \"Хранение паролей\", \"Rate limiting\"], \"c\": 1, \"why\": \"OAuth 2.0 — про доступ к ресурсам. OIDC добавляет вход: кто именно пользователь.\"}, {\"q\": \"Лучшая защита от SQL-инъекций?\", \"a\": [\"Экранировать кавычки вручную\", \"Параметризованные запросы\", \"Скрывать текст ошибок\", \"Использовать HTTPS\"], \"c\": 1, \"why\": \"Параметры передаются базе отдельно от SQL и не могут стать кодом. Ручное экранирование легко ошибается.\"}, {\"q\": \"Для чего нужен refresh token?\", \"a\": [\"Обновлять страницу\", \"Получать новый access token без повторного входа\", \"Хранить пароль\", \"Подписывать запросы\"], \"c\": 1, \"why\": \"Access token живёт коротко (минуты). Refresh token позволяет получить новый без участия пользователя.\"}, {\"q\": \"Почему хранить токен в localStorage рискованно?\", \"a\": [\"Он слишком мал\", \"Его может прочитать любой скрипт на странице при XSS\", \"Его удаляет браузер каждый час\", \"Он не работает с HTTPS\"], \"c\": 1, \"why\": \"localStorage доступен из JavaScript. Безопаснее держать токен в памяти или использовать BFF с HttpOnly-cookie.\"}, {\"q\": \"Что гарантирует подпись JWT?\", \"a\": [\"Секретность содержимого\", \"Целостность и подлинность: токен не подделан\", \"Что пользователь онлайн\", \"Что токен нельзя украсть\"], \"c\": 1, \"why\": \"Содержимое JWT (payload) читается любым — это Base64URL. Подпись лишь доказывает, что его выдал сервер и не меняли.\"}, {\"q\": \"Какой поток для общения сервиса с сервисом без пользователя?\", \"a\": [\"Authorization Code\", \"Client Credentials\", \"Device Code\", \"Implicit\"], \"c\": 1, \"why\": \"Client Credentials: сервис получает токен по своему client_id и секрету.\"}], \"6\": [{\"q\": \"Что происходит при провале readiness probe?\", \"a\": [\"Контейнер перезапускается\", \"Под убирается из Service и не получает трафик\", \"Удаляется Deployment\", \"Ничего\"], \"c\": 1, \"why\": \"Перезапуск — это реакция на провал liveness. Readiness только временно выводит под из балансировки.\"}, {\"q\": \"Главная цель multi-stage сборки Docker?\", \"a\": [\"Ускорить запуск JVM\", \"Получить маленький итоговый образ без инструментов сборки\", \"Запустить несколько процессов\", \"Шифровать образ\"], \"c\": 1, \"why\": \"JDK, Gradle и исходники остаются в промежуточном образе; в итоговом — только JRE и jar.\"}, {\"q\": \"Какой объект Kubernetes даёт постоянный адрес группе подов?\", \"a\": [\"Pod\", \"Service\", \"ConfigMap\", \"Node\"], \"c\": 1, \"why\": \"Поды пересоздаются с новыми IP. Service находит их по меткам и даёт стабильное имя и адрес.\"}, {\"q\": \"Почему тег <code>latest</code> плох в production?\", \"a\": [\"Он медленнее\", \"Непонятно, какая версия развёрнута, и сложно откатиться\", \"Kubernetes его не поддерживает\", \"Он платный\"], \"c\": 1, \"why\": \"Неизменяемые теги (версия или SHA коммита) делают развёртывание воспроизводимым.\"}, {\"q\": \"По принципам Twelve-Factor App где хранить конфигурацию?\", \"a\": [\"В коде\", \"В переменных окружения\", \"В базе данных\", \"В README\"], \"c\": 1, \"why\": \"Конфигурация отделена от кода и меняется между окружениями без пересборки.\"}, {\"q\": \"Что делает <code>terraform plan</code>?\", \"a\": [\"Создаёт ресурсы\", \"Показывает, что изменится, ничего не меняя\", \"Удаляет ресурсы\", \"Форматирует код\"], \"c\": 1, \"why\": \"plan — предпросмотр. Изменения вносит apply, удаляет destroy.\"}, {\"q\": \"p95 времени ответа равен 200 мс. Что это значит?\", \"a\": [\"Среднее время 200 мс\", \"95 % запросов выполнились не дольше 200 мс\", \"5 % запросов выполнились за 200 мс\", \"Максимум 200 мс\"], \"c\": 1, \"why\": \"Перцентили лучше среднего показывают, что чувствует большинство пользователей, и не прячут медленные хвосты.\"}, {\"q\": \"Что делает <code>helm upgrade --install</code>?\", \"a\": [\"Только удаляет релиз\", \"Обновляет релиз, а если его нет — устанавливает\", \"Обновляет сам Helm\", \"Собирает образ\"], \"c\": 1, \"why\": \"Удобная идемпотентная команда для CI: одна и та же для первого и последующих развёртываний.\"}], \"7\": [{\"q\": \"Какую проблему решает паттерн Outbox?\", \"a\": [\"Медленные запросы\", \"Двойную запись: данные в БД и событие в брокер не сохраняются атомарно\", \"Нехватку памяти\", \"Авторизацию\"], \"c\": 1, \"why\": \"Событие пишется в таблицу в той же транзакции, что и данные, а отдельный процесс публикует его.\"}, {\"q\": \"Что делает Circuit Breaker в состоянии OPEN?\", \"a\": [\"Пропускает все вызовы\", \"Сразу отклоняет вызовы или отдаёт запасной ответ\", \"Повторяет вызов бесконечно\", \"Перезапускает сервис\"], \"c\": 1, \"why\": \"OPEN защищает систему от ожидания упавшего сервиса. Через время переходит в HALF_OPEN и пробует снова.\"}, {\"q\": \"Почему консьюмер Kafka должен быть идемпотентным?\", \"a\": [\"Так быстрее\", \"Обычная гарантия — at-least-once: сообщение может прийти повторно\", \"Kafka теряет сообщения\", \"Этого требует Spring\"], \"c\": 1, \"why\": \"После сбоя или ребалансировки сообщение может быть прочитано ещё раз. Повторная обработка не должна портить данные.\"}, {\"q\": \"В каком случае Kafka гарантирует порядок сообщений?\", \"a\": [\"Во всём топике\", \"Внутри одной партиции\", \"Никогда\", \"Только при одном консьюмере на кластер\"], \"c\": 1, \"why\": \"Порядок — внутри партиции. Сообщения с одним ключом попадают в одну партицию, поэтому ключ выбирают по сущности (например, apiId).\"}, {\"q\": \"Что утверждает закон Конвея?\", \"a\": [\"Число транзисторов удваивается каждые 2 года\", \"Системы повторяют структуру коммуникаций организации\", \"Добавление людей в опаздывающий проект задерживает его\", \"Сложность растёт квадратично\"], \"c\": 1, \"why\": \"Поэтому границы сервисов часто совпадают с границами команд. Остальные варианты — законы Мура и Брукса.\"}, {\"q\": \"Когда разумнее начать с модульного монолита?\", \"a\": [\"Всегда — микросервисы устарели\", \"Маленькая команда и неясные границы предметной области\", \"Если нужен Kubernetes\", \"Если есть база данных\"], \"c\": 1, \"why\": \"Микросервисы окупаются при независимых командах и понятных границах. Иначе их цена — сеть, развёртывание, наблюдаемость — выше пользы.\"}, {\"q\": \"Что делает API Gateway?\", \"a\": [\"Хранит данные\", \"Единая точка входа: маршрутизация, аутентификация, лимиты\", \"Компилирует сервисы\", \"Заменяет базу данных\"], \"c\": 1, \"why\": \"Клиенту не нужно знать адреса всех сервисов, а сквозные задачи решаются в одном месте.\"}, {\"q\": \"Что такое Saga?\", \"a\": [\"Распределённая блокировка\", \"Цепочка локальных транзакций с компенсирующими действиями при сбое\", \"Тип базы данных\", \"Протокол OAuth\"], \"c\": 1, \"why\": \"Вместо одной распределённой транзакции каждый сервис делает свою, а при ошибке выполняются компенсации (например, «отменить резерв»).\"}], \"8\": [{\"q\": \"Что такое ART в SAFe?\", \"a\": [\"Automated Release Tool\", \"Agile Release Train — несколько команд, планирующих работу вместе\", \"Тип спринта\", \"Роль тестировщика\"], \"c\": 1, \"why\": \"Команда из вакансии называется API ART: несколько команд вокруг API-продуктов с общим PI Planning.\"}, {\"q\": \"Средняя сложность поиска по ключу в HashMap?\", \"a\": [\"O(n)\", \"O(log n)\", \"O(1)\", \"O(n log n)\"], \"c\": 2, \"why\": \"В среднем O(1). При многих коллизиях в Java 8+ корзина превращается в дерево — O(log n) в худшем случае.\"}, {\"q\": \"Сложность бинарного поиска в отсортированном массиве?\", \"a\": [\"O(1)\", \"O(log n)\", \"O(n)\", \"O(n²)\"], \"c\": 1, \"why\": \"Каждый шаг делит диапазон пополам.\"}, {\"q\": \"Какой роли нет в Scrum Guide?\", \"a\": [\"Product Owner\", \"Scrum Master\", \"Developers\", \"Project Manager\"], \"c\": 3, \"why\": \"В Scrum три ответственности: Product Owner, Scrum Master и Developers.\"}, {\"q\": \"Какая структура данных подходит для проверки скобок?\", \"a\": [\"Очередь\", \"Стек\", \"Хэш-таблица\", \"Куча\"], \"c\": 1, \"why\": \"Последняя открытая скобка должна закрыться первой — принцип LIFO, то есть стек.\"}, {\"q\": \"Что из этого — ценность Agile-манифеста?\", \"a\": [\"Процессы и инструменты важнее людей\", \"Люди и взаимодействие важнее процессов и инструментов\", \"Документация важнее работающего продукта\", \"Следование плану важнее изменений\"], \"c\": 1, \"why\": \"Остальные варианты перевёрнуты: манифест ставит работающий продукт, сотрудничество с заказчиком и готовность к изменениям выше.\"}, {\"q\": \"Что означает STAR в ответах на собеседовании?\", \"a\": [\"Skills, Talent, Ability, Result\", \"Situation, Task, Action, Result\", \"Start, Test, Analyze, Repeat\", \"Strategy, Team, Agile, Review\"], \"c\": 1, \"why\": \"Ситуация, задача, ваши действия и результат — структура рассказа об опыте.\"}, {\"q\": \"Что такое Definition of Done?\", \"a\": [\"Дата окончания проекта\", \"Общий для команды критерий, когда задача считается готовой\", \"Список багов\", \"Отчёт менеджеру\"], \"c\": 1, \"why\": \"Например: код проверен, тесты зелёные, документация обновлена, задача развёрнута на стенд.\"}]};\n  const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };\n  const ruTimes = n => n % 10 === 1 && n % 100 !== 11 ? 'попытка' : [2, 3, 4].includes(n % 10) && ![12, 13, 14].includes(n % 100) ? 'попытки' : 'попыток';\n  const tries = {};\n  function quiz(box) {\n    const n = box.dataset.quiz, data = QUIZ[n];\n    const order = shuffle(data.map((_, i) => i)).map(i => ({ i, opts: shuffle(data[i].a.map((_, k) => k)) }));\n    const best = state['qz' + n];\n    box.classList.remove('done');\n    box.innerHTML = `<div class=\"qz-head\"><b>${data.length} вопросов · попыток без ограничений</b><span class=\"qz-best\">${best ? 'Лучший результат: ' + best + ' %' : 'Ещё не пройден'}</span></div>\n      <div class=\"qz-res\" hidden></div>\n      <ol>${order.map((o, qi) => `<li data-q=\"${o.i}\"><p class=\"qz-q\">${data[o.i].q}</p>${o.opts.map(k => `<label class=\"qz-opt\"><input type=\"radio\" name=\"qz${n}-${qi}\" value=\"${k}\"><span>${data[o.i].a[k]}</span></label>`).join('')}<div class=\"qz-why\" hidden></div></li>`).join('')}</ol>\n      <div class=\"qz-bar\"><button class=\"btn primary\" data-check>Проверить</button><span class=\"qz-note\">Без ответа вопрос считается неверным.</span></div>`;\n    box.querySelector('[data-check]').onclick = () => {\n      let right = 0;\n      box.querySelectorAll('ol > li').forEach(li => {\n        const q = data[li.dataset.q], pick = li.querySelector('input:checked'), v = pick ? +pick.value : -1, ok = v === q.c;\n        if (ok) right++;\n        li.querySelectorAll('.qz-opt').forEach(l => { const k = +l.querySelector('input').value; l.querySelector('input').disabled = true;\n          if (k === q.c) l.classList.add('right'); else if (k === v) l.classList.add('wrong'); });\n        const why = li.querySelector('.qz-why');\n        why.innerHTML = (ok ? '<b class=\"ok\">Верно.</b> ' : v < 0 ? '<b class=\"no\">Нет ответа.</b> ' : '<b class=\"no\">Неверно.</b> ') + q.why;\n        why.hidden = false;\n      });\n      const pct = Math.round(right * 100 / data.length);\n      tries[n] = (tries[n] || 0) + 1;\n      if (pct > (state['qz' + n] || 0)) { state['qz' + n] = pct; paint(); save(); }\n      box.classList.add('done');\n      box.querySelector('.qz-best').textContent = 'Лучший результат: ' + state['qz' + n] + ' %';\n      const res = box.querySelector('.qz-res');\n      res.innerHTML = `<span class=\"qz-pct ${pct >= 80 ? 'good' : pct < 50 ? 'low' : ''}\">${pct} %</span>\n        <span>Верно ${right} из ${data.length}. ${pct >= 80 ? 'Отлично, тему можно считать освоенной.' : pct >= 50 ? 'Неплохо: перечитайте разбор ошибок и попробуйте ещё раз.' : 'Стоит вернуться к теории главы и пройти тест снова.'}<br><small>${tries[n]} ${ruTimes(tries[n])} за этот заход · лучший результат: ${state['qz' + n] || pct} %</small></span>`;\n      res.hidden = false;\n      const bar = box.querySelector('.qz-bar');\n      bar.innerHTML = '<button class=\"btn primary\" data-again>Пройти заново</button><span class=\"qz-note\">Вопросы и варианты перемешаются.</span>';\n      bar.querySelector('[data-again]').onclick = () => { quiz(box); box.scrollIntoView({ block: 'start' }); };\n      res.scrollIntoView({ block: 'center' });\n    };\n  }\n  document.querySelectorAll('.quiz[data-quiz]').forEach(quiz);\n  const quizBest = () => document.querySelectorAll('.quiz[data-quiz]').forEach(b => { const v = state['qz' + b.dataset.quiz], el = b.querySelector('.qz-best'); if (el && v) el.textContent = 'Лучший результат: ' + v + ' %'; });\n\n  // ---------- «продолжить с места» ----------\n  function cont() {\n    const b = boxes.find(x => !x.checked);\n    const li = b ? b.closest('li') : $('#ch10');\n    closeNav();\n    li.scrollIntoView({ block: 'center' });\n    li.classList.remove('flash'); void li.offsetWidth; li.classList.add('flash');\n  }\n  $('#cont').onclick = cont; $('#cont-top').onclick = cont;\n\n  // ---------- подсветка текущей главы и темы ----------\n  const subs = $$('section[data-ch] h3[id]');\n  let ticking = false;\n  function spy() {\n    ticking = false;\n    const y = 90;\n    let cur = chapters[0];\n    for (const ch of chapters) if (ch.getBoundingClientRect().top <= y) cur = ch;\n    let sub = null;\n    for (const h of subs) if (cur.contains(h) && h.getBoundingClientRect().top <= y + 40) sub = h;\n    for (const li of toc.querySelectorAll('li[data-for]')) li.classList.toggle('on', li.dataset.for === cur.id);\n    for (const a of toc.querySelectorAll('a[data-sub]')) a.classList.toggle('on', !!sub && a.dataset.sub === sub.id);\n    $('#up').hidden = window.scrollY < 800;\n  }\n  window.addEventListener('scroll', () => { if (!ticking) { ticking = true; requestAnimationFrame(spy); } }, { passive: true });\n  spy();\n  $('#up').onclick = () => window.scrollTo({ top: 0 });\n\n  // ---------- меню на телефоне ----------\n  const menu = $('#menu');\n  function closeNav() { document.body.classList.remove('nav'); menu.setAttribute('aria-expanded', 'false'); }\n  menu.onclick = () => { const on = document.body.classList.toggle('nav'); menu.setAttribute('aria-expanded', String(on)); };\n  $('#scrim').onclick = closeNav;\n  toc.addEventListener('click', e => { if (e.target.closest('a')) closeNav(); });\n  document.addEventListener('keydown', e => {\n    if (e.key === 'Escape') closeNav();\n    if (e.key === '/' && document.activeElement.tagName !== 'INPUT') { e.preventDefault(); document.body.classList.add('nav'); $('#q').focus(); }\n  });\n\n  // ---------- поиск ----------\n  const idx = [];\n  for (const ch of chapters) {\n    const title = ch.dataset.title;\n    ch.querySelectorAll('h3[id], dt, ul.res li, ul.todo li, details, .goals li, p').forEach(el => {\n      if (el.closest('.quiz')) return;\n      const host = el.closest('[id]') && el.matches('h3[id]') ? el : el;\n      idx.push({ el: host, text: el.textContent.replace(/\\s+/g, ' ').trim(), title });\n    });\n  }\n  const esc = s => s.replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' })[c]);\n  const hits = $('#hits'), q = $('#q');\n  q.addEventListener('input', () => {\n    const s = q.value.trim().toLowerCase();\n    toc.hidden = !!s;\n    if (s.length < 2) { hits.innerHTML = ''; return; }\n    const found = idx.filter(x => x.text.toLowerCase().includes(s)).slice(0, 30);\n    hits.innerHTML = found.length ? found.map((x, i) => {\n      const t = x.text, at = t.toLowerCase().indexOf(s), from = Math.max(0, at - 30);\n      const snip = (from ? '…' : '') + esc(t.slice(from, at)) + '<mark>' + esc(t.slice(at, at + s.length)) + '</mark>' + esc(t.slice(at + s.length, at + s.length + 50)) + '…';\n      return `<li><a href=\"#\" data-i=\"${idx.indexOf(x)}\">${snip}<small>${esc(x.title)}</small></a></li>`;\n    }).join('') : '<li><small>Ничего не найдено</small></li>';\n  });\n  hits.addEventListener('click', e => {\n    const a = e.target.closest('a[data-i]'); if (!a) return;\n    e.preventDefault();\n    const el = idx[+a.dataset.i].el;\n    const d = el.closest('details'); if (d) d.open = true;\n    closeNav();\n    el.scrollIntoView({ block: 'center' });\n    el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash');\n  });\n})();\n</script>\n</body>\n</html>\n";
